  saved.password = secrets.password;
  saved.baseUrl = secrets.base;
  saved.endpoint = secrets.endpoint;
  saved.authMode = secrets.authMode;
  saved.authHeader = secrets.authHeader;
  saved.authPrefix = secrets.authPrefix;
