#pragma once
// ============================================================================
// TransferScreen — tela do modo "receber arquivo pelo Wi-Fi".
//
// Enquanto o aparelho esta servindo HTTP, esta tela e a unica coisa que ele
// mostra. Quem esta na frente da TV precisa LER dali o endereco, o usuario e a
// senha da sessao e digitar tudo num computador do outro lado da sala. Ou
// seja: e um cartaz, nao um painel de diagnostico. Dai a hierarquia do
// desenho, que e a regra que decide todo o resto deste arquivo:
//
//   1. endereco   — o dado que a pessoa precisa copiar primeiro, em fonte
//                   grossa (VcrFont 12x16) dentro de uma moldura ciano;
//   2. usuario/senha — tambem 12x16, porque tambem sao digitados;
//   3. estado     — faixa colorida, que se le pela cor mesmo antes do texto;
//   4. progresso  — nome do arquivo, porcentagem, barra e contagem de bytes;
//   5. rede e aviso — contexto, em corpo pequeno.
//
// Por que fontes diferentes por campo (nao e capricho):
//
//   * O endereco so tem digitos, ponto, dois-pontos e barra — nada que dependa
//     de caixa. Entao vai na VcrFont, que tem traco de 2 px constante e e a
//     unica que aguenta o borrao horizontal do NTSC (ver o cabecalho da
//     VcrFont.h). Ela desenha so em caixa alta, e isso aqui e inofensivo.
//   * Usuario e senha NAO podem passar pela VcrFont: a senha e gerada por
//     sessao e diferencia maiuscula de minuscula. Uma senha "aB7k" desenhada
//     como "AB7K" faria a pessoa digitar errado e culpar o aparelho. Esses dois
//     campos saem na Font0 do M5GFX em tamanho 2 — que tem exatamente a mesma
//     celula de 12x16 e traco de 2 px depois da escala, mas preserva a caixa.
//   * SSID, nome de arquivo e bytes saem em Font0 tamanho 1 quando nao couberem
//     grandes: e preferivel ler pequeno a ler truncado.
//
// Texto de fora (SSID, nome do arquivo, mensagem de erro) passa por
// ascii::normalize antes de chegar na tela. As fontes bitmap so tem ASCII e em
// UTF-8 cada letra acentuada sao dois bytes sem glifo — "Não" viraria "N  o".
//
// Geometria: tudo dentro de crt::SAFE_* (SafeArea.h), porque um tubo esconde
// ~7% de cada borda. So o fundo sangra ate a borda do raster. O cabecalho
// (HEAD_Y / HEAD_RULE_Y) e a faixa de rodape (BAR_Y / BAR_H) sao os mesmos das
// outras telas, para esta nao destoar.
//
// LCD e saida composta usam o MESMO desenho, nas mesmas coordenadas. O LCD do
// Core2 nao tem overscan e sobraria margem, mas duas geometrias para a mesma
// tela e justamente a armadilha 8 do AGENTS.md ("duas constantes descrevendo a
// mesma geometria"): elas divergem na primeira manutencao. No LCD isto aparece
// apenas como uma margem um pouco maior, que e o que drawInfo()/drawSettings()
// ja fazem hoje.
//
// Dependencias: M5GFX (vem pela VcrFont), SafeArea.h e Ascii.h. Nada de
// Arduino, WiFi, SD ou FreeRTOS: o destino e um LovyanGFX*, entao o mesmo
// header serve ao painel CVBS do aparelho e ao painel SDL do simulador.
//
// O modulo de transferencia em si (HTTP, cartao, senha de sessao) e de outro
// arquivo: esta tela recebe um State ja pronto e so desenha. Quem integra faz
// a ponte entre os dois.
//
// Compila em -std=gnu++11 (conferir com `make -C sim cxx11`).
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "VcrFont.h"

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

namespace xfer {

// ---------------------------------------------------------------------------
//  Estado exibido
// ---------------------------------------------------------------------------

// Estagio da sessao de transferencia. E o que escolhe a cor da faixa de estado
// e o que a area de progresso mostra.
enum class Stage : uint8_t {
  Waiting,   // servidor no ar, ninguem conectou ainda
  Receiving, // recebendo um arquivo agora
  Done,      // arquivo gravado no cartao
  Error      // falhou (sem espaco, conexao caiu, senha errada...)
};

// Rotulos padrao. Ficam aqui, e nao na LocalizationPTBR.h, porque este header
// nao pode depender de nada do firmware — mas todos sao sobrescreviveis pelo
// State, entao a integracao pode apontar para as strings de la.
constexpr const char *kTitle = "TRANSFERIR ARQUIVOS";
constexpr const char *kWarning = "RESTO DO APARELHO SUSPENSO";
// Enumera o que o aparelho aceita, porque essa e a duvida de quem esta parado
// na frente da TV com o computador aberto — "envie o arquivo no PC" nao dizia
// QUAL arquivo, e agora sao tres categorias (videos/, music/, fotos/).
//
// Curto de proposito: com 21 caracteres a dica ainda cabe em corpo grande na
// largura segura (21 x 12 = 252 px, contra os 272 de crt::SAFE_W). Uma frase
// mais longa cairia para a fonte fina e viraria um rodape ilegivel no meio da
// tela — 22 caracteres e o teto absoluto. ASCII sem acento: as fontes bitmap
// nao tem glifo para acentuado (AGENTS 2.7).
constexpr const char *kHint = "VIDEO, MUSICA E FOTOS";

struct State {
  // O que a pessoa digita no navegador, ja pronto: "http://192.168.0.12".
  // Nao inventamos o prefixo aqui — quem monta a string sabe se ha porta.
  const char *address = nullptr;
  const char *ssid = nullptr;     // rede em que o aparelho esta
  const char *user = nullptr;     // usuario do acesso HTTP
  const char *password = nullptr; // senha da sessao (caixa preservada!)

  Stage stage = Stage::Waiting;
  const char *fileName = nullptr; // arquivo em transito / recebido
  // Contagem de bytes. uint32_t basta: o limite de arquivo do FAT32 e 4 GiB-1,
  // que e exatamente o alcance deste tipo.
  uint32_t bytesReceived = 0;
  uint32_t bytesTotal = 0; // 0 = tamanho desconhecido (sem Content-Length)

  // Texto da faixa de estado. Nulo usa o rotulo padrao do estagio; e por aqui
  // que passa o detalhe do erro ("SEM ESPACO NO CARTAO").
  const char *statusText = nullptr;

  const char *title = kTitle;
  const char *warning = kWarning;      // aviso de que o aparelho esta suspenso
  const char *buttonLabel = nullptr;   // legenda do botao de sair, se houver
};

// ---------------------------------------------------------------------------
//  Cores — RGB565 escritas na mao, para o header nao depender das macros TFT_*
// ---------------------------------------------------------------------------

constexpr uint16_t kBg = 0x000F;     // azul-marinho, o mesmo das outras telas
constexpr uint16_t kPanel = 0x0018;  // azul do painel do endereco (um degrau
                                     // acima do fundo: em RGB332 o azul tem so
                                     // 2 bits, e estes dois caem em indices
                                     // diferentes — 0x0010 nao cairia)
constexpr uint16_t kInk = 0xFFFF;    // branco: valores
constexpr uint16_t kAccent = 0x07FF; // ciano: rotulos e molduras
constexpr uint16_t kDim = 0x8410;    // cinza: dica e texto secundario

// Cores dos estagios. Saturadas de proposito: em RGB332 (a profundidade do
// framebuffer composto) meio-tom vira banda, e a cor tem de ser reconhecivel
// do outro lado da sala antes de a pessoa ler a palavra.
constexpr uint16_t kWaitFill = 0x07FF; // ciano
constexpr uint16_t kRecvFill = 0xFFE0; // amarelo
constexpr uint16_t kDoneFill = 0x07E0; // verde
constexpr uint16_t kErrFill = 0xF800;  // vermelho

// ---------------------------------------------------------------------------
//  Geometria — colunas e linhas fixas dentro da area segura
// ---------------------------------------------------------------------------
namespace layout {

constexpr int kRowH = 16; // altura de uma linha de valor (a celula da VcrFont)

constexpr int kTitleY = crt::HEAD_Y;      // 18 — titulo, Font0 tamanho 2
constexpr int kRuleY = crt::HEAD_RULE_Y;  // 46 — regua ciano do cabecalho

constexpr int kNetY = 52;    // linha "REDE  <ssid>", corpo pequeno
constexpr int kNetH = 8;

constexpr int kAddrY = 62;   // painel do endereco
constexpr int kAddrH = 28;

constexpr int kUserY = 94;   // "USUARIO <valor>"
constexpr int kPassY = 114;  // "SENHA   <valor>"

constexpr int kStatusY = 136; // faixa colorida de estado
constexpr int kStatusH = 20;

constexpr int kFileY = 160;   // nome do arquivo + porcentagem
constexpr int kPctW = 56;     // reserva da porcentagem ("100%" = 48 px)

constexpr int kBarY = 180;    // barra de progresso
constexpr int kBarH = 12;

constexpr int kBytesY = 194;  // "RECEBIDO 1,2 MB / 4,6 MB", corpo pequeno
constexpr int kBytesH = 8;

// Coluna dos valores de REDE/USUARIO/SENHA. 54 px = o rotulo mais longo
// ("USUARIO", 42 px na Font0 tamanho 1) mais 12 de respiro. A coluna foi
// apertada ate aqui de proposito: cada pixel que sobra a esquerda e um
// caractere a mais de senha em corpo grande, e uma senha de sessao com 16
// caracteres so cabia grande depois disso.
constexpr int kLabelX = crt::SAFE_L;           // 24
constexpr int kValueX = crt::SAFE_L + 54;      // 78
constexpr int kValueW = crt::SAFE_R - kValueX; // 218 -> 18 caracteres grandes

// Faixa que drawProgress() repinta: do topo da faixa de estado ate o fim da
// linha de bytes. Exposta porque quem integra pode querer limpar a regiao por
// conta propria (numa transicao, por exemplo).
constexpr int kDynamicY = kStatusY;                        // 136
constexpr int kDynamicH = (kBytesY + kBytesH) - kStatusY;  // 66

// Quantos caracteres cabem em corpo grosso na largura segura. E o teto do
// endereco: "http://192.168.100.130" tem 22 e cabe raspando; com porta
// ("...:8080") ja nao cabe e o painel cai para a fonte fina, que e legivel de
// perto mas nao da poltrona. Quem monta a string faz bem em evitar a porta.
constexpr int kThickChars = crt::SAFE_W / vcrfont::CELL_W; // 22

static_assert(kTitleY >= crt::SAFE_T, "titulo escapa pelo topo da area segura");
static_assert(kBytesY + kBytesH <= crt::BAR_Y, "linha de bytes invade a faixa de rodape");
static_assert(crt::BAR_Y + crt::BAR_H <= crt::SAFE_B, "rodape escapa pela base da area segura");
static_assert(kValueX + kValueW <= crt::SAFE_R, "coluna de valores escapa pela direita");
static_assert(kThickChars >= 22, "endereco IPv4 sem porta nao cabe mais em corpo grosso");

// As linhas nao podem se encavalar. Sem isto, mexer em uma constante para
// ganhar 4 px desenha texto por cima de texto e so aparece no probe — se
// alguem lembrar de olhar o PNG.
static_assert(kRuleY < kNetY, "regua do cabecalho invade a linha da rede");
static_assert(kNetY + kNetH <= kAddrY, "linha da rede invade o painel do endereco");
static_assert(kAddrY + kAddrH <= kUserY, "painel do endereco invade a linha do usuario");
static_assert(kUserY + kRowH <= kPassY, "usuario invade a senha");
static_assert(kPassY + kRowH <= kStatusY, "senha invade a faixa de estado");
static_assert(kStatusY + kStatusH <= kFileY, "faixa de estado invade a linha do arquivo");
static_assert(kFileY + kRowH <= kBarY, "linha do arquivo invade a barra");
static_assert(kBarY + kBarH <= kBytesY, "barra invade a linha de bytes");

} // namespace layout

// ---------------------------------------------------------------------------
//  Utilitarios internos
// ---------------------------------------------------------------------------
namespace detail {

// Metrica da Font0 do M5GFX (GLCDfont 6x8). Usada direto, em vez de
// gfx->textWidth(), para o calculo nao depender de qual fonte o chamador
// deixou ativa — draw() fixa a Font0 antes de qualquer medida.
constexpr int kM5W = 6;
constexpr int kM5H = 8;

// Buffer de texto normalizado. 64 bytes cobrem o pior caso util: um SSID tem no
// maximo 32 caracteres e um nome de arquivo maior que isso ja sai truncado de
// qualquer jeito. Pequeno de proposito — a pilha do loopTask e 8 KB e o
// AGENTS.md conta duas travadas causadas por array grande em pilha (2.3).
constexpr size_t kBuf = 64;

// Normaliza para ASCII no buffer do chamador. Nulo vira string vazia, para o
// resto do desenho nao precisar testar ponteiro a cada linha.
inline const char *norm(char *dst, size_t cap, const char *src) {
  if (!cap)
    return "";
  if (!src) {
    dst[0] = 0;
    return dst;
  }
  ascii::normalize(dst, cap, src);
  return dst;
}

// Desenha na Font0 escolhendo o maior tamanho (<= maxSize) que couber em `w` e,
// se nem o tamanho 1 couber, trunca com "..." no fim. Centraliza verticalmente
// na faixa de altura `h`, para que cair de tamanho 2 para 1 nao desalinhe a
// linha. Devolve a largura consumida.
inline int drawFine(LovyanGFX *gfx, const char *s, int x, int y, int w, int h, int32_t ink,
                    int maxSize) {
  if (!gfx || !s || !*s)
    return 0;
  int len = (int)strlen(s);
  int size = maxSize;
  while (size > 1 && len * kM5W * size > w)
    --size;

  char cut[kBuf];
  const int maxChars = w / (kM5W * size);
  if (len > maxChars) {
    // Trunca com reticencias: um nome de arquivo cortado em seco parece nome
    // de arquivo, e a pessoa procura no computador um arquivo que nao existe.
    int keep = maxChars - 3;
    if (keep < 1)
      keep = maxChars > 0 ? maxChars : 0;
    if (keep > (int)kBuf - 4)
      keep = (int)kBuf - 4;
    memcpy(cut, s, (size_t)keep);
    cut[keep] = 0;
    if (maxChars >= 4)
      strncat(cut, "...", kBuf - strlen(cut) - 1);
    s = cut;
    len = (int)strlen(s);
  }

  gfx->setFont(&fonts::Font0);
  gfx->setTextSize((uint8_t)size);
  gfx->setTextDatum(lgfx::textdatum::top_left);
  gfx->setTextColor(ink); // fore == back no LovyanGFX significa fundo transparente
  gfx->drawString(s, x, y + (h - kM5H * size) / 2);
  gfx->setTextSize(1);
  return len * kM5W * size;
}

// Texto grosso: VcrFont 12x16 quando couber, senao a Font0 pequena, que cabe o
// dobro de caracteres. Degradar para a fonte fina e melhor que truncar um dado
// que a pessoa precisa copiar.
inline void drawThick(LovyanGFX *gfx, const char *s, int x, int y, int w, int h, int32_t ink) {
  if (!gfx || !s || !*s)
    return;
  if (vcrfont::textWidth(s) <= w) {
    vcrfont::drawText(gfx, s, x, y + (h - vcrfont::textHeight()) / 2, ink);
    return;
  }
  drawFine(gfx, s, x, y, w, h, ink, 1);
}

// Idem, centralizado na faixa [x, x + w).
inline void drawThickCentered(LovyanGFX *gfx, const char *s, int x, int y, int w, int h, int32_t ink) {
  if (!gfx || !s || !*s)
    return;
  const int tw = vcrfont::textWidth(s);
  if (tw <= w) {
    vcrfont::drawText(gfx, s, x + (w - tw) / 2, y + (h - vcrfont::textHeight()) / 2, ink);
    return;
  }
  const int len = (int)strlen(s);
  const int fw = len * kM5W;
  drawFine(gfx, s, x + (w > fw ? (w - fw) / 2 : 0), y, w, h, ink, 1);
}

// Bytes em unidade legivel, com uma casa decimal e virgula (pt-BR).
// Aritmetica inteira: %f no newlib-nano do ESP32 depende de flag de link e ja
// imprimiu lixo neste projeto; e a divisao por 1024 aqui e um shift.
inline void formatBytes(char *dst, size_t cap, uint32_t b) {
  if (b < 1024u) {
    snprintf(dst, cap, "%lu B", (unsigned long)b);
  } else if (b < 1024u * 1024u) {
    snprintf(dst, cap, "%lu,%lu KB", (unsigned long)(b >> 10), (unsigned long)(((b & 1023u) * 10u) >> 10));
  } else if (b < 1024u * 1024u * 1024u) {
    const uint32_t k = b >> 10;
    snprintf(dst, cap, "%lu,%lu MB", (unsigned long)(k >> 10), (unsigned long)(((k & 1023u) * 10u) >> 10));
  } else {
    const uint32_t m = b >> 20;
    snprintf(dst, cap, "%lu,%lu GB", (unsigned long)(m >> 10), (unsigned long)(((m & 1023u) * 10u) >> 10));
  }
}

// Rotulo padrao de cada estagio.
inline const char *stageLabel(Stage stage) {
  return stage == Stage::Waiting     ? "AGUARDANDO CONEXAO"
         : stage == Stage::Receiving ? "RECEBENDO ARQUIVO"
         : stage == Stage::Done      ? "CONCLUIDO"
                                     : "ERRO NA TRANSFERENCIA";
}

inline uint16_t stageFill(Stage stage) {
  return stage == Stage::Waiting     ? kWaitFill
         : stage == Stage::Receiving ? kRecvFill
         : stage == Stage::Done      ? kDoneFill
                                     : kErrFill;
}

// Tinta sobre a faixa: marinho sobre ciano/amarelo/verde (claros) e branco
// sobre vermelho (escuro). O criterio e luminancia, nao gosto.
inline uint16_t stageTextInk(Stage stage) {
  return stage == Stage::Error ? kInk : kBg;
}

} // namespace detail

// Porcentagem concluida, ou -1 quando nao da para saber (sem tamanho total).
// Publica porque a integracao costuma querer o mesmo numero no log serial.
inline int percent(const State &s) {
  if (s.stage == Stage::Done)
    return 100; // concluido sem Content-Length ainda e 100%
  if (!s.bytesTotal)
    return -1;
  // 64 bits no meio do caminho: bytesReceived * 100 estoura 32 bits a partir de
  // 43 MB, e um arquivo de video passa disso na primeira tentativa.
  uint64_t p = ((uint64_t)s.bytesReceived * 100u) / s.bytesTotal;
  if (p > 100u)
    p = 100u;
  return (int)p;
}

// ---------------------------------------------------------------------------
//  Desenho
// ---------------------------------------------------------------------------

// Parte que nao muda durante a sessao: cabecalho, rede, endereco, credenciais e
// a faixa de rodape com o aviso. Separada de drawProgress() porque a senha e o
// endereco nao mudam enquanto a tela existe, e repintar tudo a cada pacote
// recebido faria a tela piscar na TV.
inline void drawStatic(LovyanGFX *gfx, const State &s) {
  if (!gfx)
    return;
  char buf[detail::kBuf];
  using namespace layout;

  // Cabecalho, igual ao das outras telas.
  gfx->setFont(&fonts::Font0);
  gfx->setTextDatum(lgfx::textdatum::top_left);
  gfx->setTextSize(2);
  gfx->setTextColor(kInk);
  gfx->drawString(detail::norm(buf, sizeof(buf), s.title ? s.title : kTitle), crt::SAFE_L, kTitleY);
  gfx->setTextSize(1);
  gfx->drawFastHLine(crt::SAFE_L, kRuleY, crt::SAFE_W, kAccent);

  // Rede: contexto, nao dado a copiar — fica pequeno de proposito.
  detail::drawFine(gfx, "REDE", kLabelX, kNetY, kValueX - kLabelX, kNetH, kAccent, 1);
  detail::drawFine(gfx, detail::norm(buf, sizeof(buf), s.ssid), kValueX, kNetY, kValueW, kNetH, kInk, 1);

  // Painel do endereco: o unico elemento com moldura, porque e o unico que a
  // pessoa procura na tela antes de ler qualquer outra coisa.
  gfx->fillRect(crt::SAFE_L, kAddrY, crt::SAFE_W, kAddrH, kPanel);
  gfx->drawRect(crt::SAFE_L, kAddrY, crt::SAFE_W, kAddrH, kAccent);
  detail::drawThickCentered(gfx, detail::norm(buf, sizeof(buf), s.address), crt::SAFE_L + 2, kAddrY + 1,
                            crt::SAFE_W - 4, kAddrH - 2, kInk);

  // Usuario e senha: valores na Font0 tamanho 2, que preserva maiuscula e
  // minuscula. A senha e gerada por sessao; desenha-la em caixa alta seria
  // entregar uma senha errada.
  detail::drawFine(gfx, "USUARIO", kLabelX, kUserY, kValueX - kLabelX, kRowH, kAccent, 1);
  detail::drawFine(gfx, detail::norm(buf, sizeof(buf), s.user), kValueX, kUserY, kValueW, kRowH, kInk, 2);
  detail::drawFine(gfx, "SENHA", kLabelX, kPassY, kValueX - kLabelX, kRowH, kAccent, 1);
  detail::drawFine(gfx, detail::norm(buf, sizeof(buf), s.password), kValueX, kPassY, kValueW, kRowH, kInk,
                   2);

  // Rodape: mesma faixa das legendas das outras telas. Aqui ela carrega o aviso
  // de que o aparelho esta suspenso — a legenda do botao entra no mesmo texto
  // quando existe, porque 20 px nao comportam duas linhas.
  gfx->fillRect(0, crt::BAR_Y, crt::W, crt::BAR_H, kBg);
  char foot[detail::kBuf * 2];
  char warn[detail::kBuf];
  detail::norm(warn, sizeof(warn), s.warning ? s.warning : kWarning);
  if (s.buttonLabel && *s.buttonLabel) {
    char btn[detail::kBuf];
    detail::norm(btn, sizeof(btn), s.buttonLabel);
    snprintf(foot, sizeof(foot), "[ %s ]  %s", btn, warn);
    // Nao cabendo os dois, o aviso tem prioridade: a legenda do botao a pessoa
    // descobre apertando, o aviso nao.
    if ((int)strlen(foot) * detail::kM5W > crt::SAFE_W)
      snprintf(foot, sizeof(foot), "%s", warn);
  } else {
    snprintf(foot, sizeof(foot), "%s", warn);
  }
  const int fw = (int)strlen(foot) * detail::kM5W;
  detail::drawFine(gfx, foot, crt::SAFE_L + (fw < crt::SAFE_W ? (crt::SAFE_W - fw) / 2 : 0), crt::BAR_Y,
                   crt::SAFE_W, crt::BAR_H, kAccent, 1);
}

// Parte viva: faixa de estado, nome do arquivo, porcentagem, barra e bytes.
// Repinta o proprio fundo, entao pode ser chamada sozinha a cada atualizacao do
// progresso sem piscar o resto da tela.
inline void drawProgress(LovyanGFX *gfx, const State &s) {
  if (!gfx)
    return;
  char buf[detail::kBuf];
  using namespace layout;

  // O fundo sangra ate a borda do raster (regra da area segura: so o conteudo
  // fica dentro da caixa), entao a limpeza vai de x=0 a x=W.
  gfx->fillRect(0, kDynamicY, crt::W, kDynamicH, kBg);

  // Faixa de estado. A cor e o primeiro sinal: da para saber de longe que algo
  // deu errado sem conseguir ler a palavra "ERRO".
  const uint16_t fill = detail::stageFill(s.stage);
  gfx->fillRect(crt::SAFE_L, kStatusY, crt::SAFE_W, kStatusH, fill);
  detail::drawThickCentered(gfx, detail::norm(buf, sizeof(buf), s.statusText ? s.statusText
                                                                             : detail::stageLabel(s.stage)),
                            crt::SAFE_L + 2, kStatusY, crt::SAFE_W - 4, kStatusH,
                            detail::stageTextInk(s.stage));

  const int pct = percent(s);

  // Linha do arquivo: nome a esquerda, porcentagem grossa a direita. A
  // porcentagem fica fora da faixa de estado para sobreviver a um statusText
  // personalizado (mensagem de erro, por exemplo).
  if (s.stage == Stage::Waiting) {
    // Sem arquivo ainda: uma dica apagada ocupa o lugar, para a metade de baixo
    // da tela nao parecer defeito.
    detail::drawFine(gfx, kHint, crt::SAFE_L, kFileY, crt::SAFE_W, kRowH, kDim, 2);
  } else {
    detail::drawThick(gfx, detail::norm(buf, sizeof(buf), s.fileName), crt::SAFE_L, kFileY,
                      crt::SAFE_W - kPctW - 8, kRowH, kInk);
    if (pct >= 0) {
      char pctText[8];
      snprintf(pctText, sizeof(pctText), "%d%%", pct);
      const int pw = vcrfont::textWidth(pctText);
      vcrfont::drawText(gfx, pctText, crt::SAFE_R - pw, kFileY, fill);
    }
  }

  // Barra: moldura sempre, para o lugar do progresso existir antes de haver
  // progresso. O miolo tem 2 px de folga de cada lado, senao o preenchimento
  // encosta na moldura e some em RGB332.
  gfx->drawRect(crt::SAFE_L, kBarY, crt::SAFE_W, kBarH, kAccent);
  const int inner = crt::SAFE_W - 4;
  if (pct > 0) {
    int w = (inner * pct) / 100;
    if (w < 1)
      w = 1; // 1% tem de aparecer; zero px passaria por "nao comecou"
    gfx->fillRect(crt::SAFE_L + 2, kBarY + 2, w, kBarH - 4, fill);
  }

  // Bytes: a unica linha da tela que sobrou em corpo pequeno (8 px de altura
  // entre a barra e a faixa de rodape). Sai em branco, e nao no cinza da dica,
  // porque 6x8 em cinza sobre marinho nao sobrevive ao borrao do NTSC. Sem
  // total conhecido, mostra so o que ja chegou — inventar um total seria mentir
  // sobre o prazo.
  if (s.stage != Stage::Waiting) {
    char got[24], all[24];
    detail::formatBytes(got, sizeof(got), s.bytesReceived);
    if (s.bytesTotal) {
      detail::formatBytes(all, sizeof(all), s.bytesTotal);
      snprintf(buf, sizeof(buf), "RECEBIDO %s / %s", got, all);
    } else {
      snprintf(buf, sizeof(buf), "RECEBIDO %s", got);
    }
    detail::drawFine(gfx, buf, crt::SAFE_L, kBytesY, crt::SAFE_W, kBytesH, kInk, 1);
  }
}

// Tela inteira. O fillScreen sangra ate a borda do raster de proposito: tarja
// preta em volta faria a imagem parecer pequena no tubo (SafeArea.h).
inline void draw(LovyanGFX *gfx, const State &s) {
  if (!gfx)
    return;
  gfx->fillScreen(kBg);
  drawStatic(gfx, s);
  drawProgress(gfx, s);
  // Deixa o contexto de texto num estado conhecido: varias telas do firmware
  // desenham logo depois assumindo tamanho 1 e datum top_left.
  gfx->setTextSize(1);
  gfx->setTextDatum(lgfx::textdatum::top_left);
}

} // namespace xfer

#pragma once
// ============================================================================
// ChannelMode.h — "modo canal" (reproducao continua) e timer de soneca.
//
// Duas pecas que transformam o player de arquivos num aparelho de TV:
//
//   1. channel::Channel   — quando um programa acaba, o proximo entra sozinho,
//                           com uma vinheta curta ("A SEGUIR") no meio. E o que
//                           separa "abrir um arquivo" de "ligar um canal".
//   2. sleeptimer::SleepTimer — o SLEEP do videocassete: 15/30/60/90/120 min e
//                           o aparelho se desliga. Quem dorme na frente da TV
//                           nao levanta para apertar nada.
//
// ---------------------------------------------------------------------------
// O que este header NAO faz (de proposito)
// ---------------------------------------------------------------------------
//
// * Nao varre o cartao SD. A biblioteca ja existe em src/main.cpp
//   (scanLibrary / libraryProgramCount / libraryProgramAt) e re-implementar
//   isso aqui seria a armadilha 8 do AGENTS.md — duas coisas descrevendo o
//   mesmo estado, divergindo na primeira manutencao. O Channel guarda so
//   INDICES e pede o caminho ao chamador por um ponteiro de funcao.
// * Nao abre, fecha nem toca nada. Ele devolve "toque o indice N agora"; quem
//   chama o startProgram() continua sendo o loop().
// * Nao desliga o aparelho. O SleepTimer so responde `expired()`.
//
// ---------------------------------------------------------------------------
// Restricoes respeitadas (ver AGENTS.md secao 2)
// ---------------------------------------------------------------------------
//
// * C++11 (-std=gnu++11). Nenhum constexpr com laco ou variavel local — foi
//   isso que quebrou a VcrFont.h uma vez. As tabelas pequenas sao arrays locais
//   de funcao inline, que o compilador resolve sem exigir C++14.
// * SRAM. O objeto Channel inteiro cabe em ~90 bytes: a ordem embaralhada e um
//   array de 64 uint8_t (indices, nao ponteiros, nao String). Nenhum sprite —
//   um sprite de 5 KB ja causou falta de memoria neste projeto, e a vinheta e
//   desenhada direto no painel.
// * Texto ASCII e sem acento. O nome da pasta vem do cartao, entao passa por
//   ascii::normalizeUpper antes de ir para a tela.
// * Nada de ciano saturado (0x07FF): o dot crawl do NTSC faz aquilo tremer. O
//   acento e o 0x96BC que o resto do firmware ja usa.
// * Tudo dentro de crt::SAFE_* (SafeArea.h); so o fundo sangra ate a borda do
//   raster, sem tarja preta.
// * Prazo com millis(): TODA conta de tempo passa por timeReached() (UiLogic.h),
//   que compara a diferenca com sinal. millis() da a volta em ~49 dias e
//   `now > deadline` cru trava o timer para sempre quando isso acontece.
//
// Dependencias: M5GFX (vem pela VcrFont), SafeArea.h, UiLogic.h, Ascii.h.
// Nada de Arduino, SD, WiFi ou FreeRTOS: o destino e um lgfx::LovyanGFX*, entao
// o mesmo header serve ao painel CVBS do aparelho e ao painel SDL do simulador.
//
// Bancada: sim/probes/channel_mode.cpp.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "UiLogic.h" // timeReached()
#include "VcrFont.h" // traz o M5GFX junto

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

namespace channel {

// Acento seguro na saida composta. TFT_CYAN (0x07FF) esta proibido aqui: a
// crominancia saturada do NTSC produz dot crawl visivel em borda de texto.
constexpr uint16_t kAccent = 0x96BC;

// Mesmo teto de MAX_LIBRARY_ITEMS em src/main.cpp. Cabe em uint8_t de
// proposito: a permutacao do modo aleatorio e um array de 64 bytes.
constexpr int MAX_ITEMS = 64;

// Duracao padrao da vinheta entre programas. Curta: e respiro, nao intervalo.
constexpr uint32_t kDefaultBumperMs = 3000;

enum class Mode : uint8_t {
  Off = 0,        // comportamento atual: acabou o programa, volta para a lista
  Sequential = 1, // proximo da lista, dando a volta no fim
  Shuffle = 2     // permutacao sem repetir ate a lista esgotar
};

enum class Phase : uint8_t {
  Idle = 0,   // nada agendado
  Playing = 1,// um programa esta no ar
  Bumper = 2  // vinheta correndo; o proximo indice ja esta escolhido
};

// Como o Channel resolve um indice em caminho de pasta. O `user` e opaco: em
// src/main.cpp ele nem precisa ser usado, porque libraryProgramAt() e global.
typedef const char *(*PathFn)(int index, void *user);

// ---------------------------------------------------------------------------
//  Channel
// ---------------------------------------------------------------------------
//
// Ciclo de vida visto pelo chamador:
//
//   ch.attach(libraryProgramCount(), pathAdapter);   // ao entrar na biblioteca
//   ch.seed(millis());                               // semente da permutacao
//   ...
//   startProgram(p) deu certo  -> ch.started(index, millis());
//   playbackFinished           -> if (ch.finished(millis())) { desenha vinheta }
//                                 else { comportamento antigo: volta a lista }
//   a cada loop, em Bumper     -> ch.drawBumper(...); int n = ch.ready(millis());
//                                 if (n >= 0) startProgram(ch.pathAt(n));
//   startProgram falhou        -> if (!ch.failed(millis())) { volta a lista }
//   usuario apertou VOLTAR     -> ch.stop();
//
class Channel {
public:
  Channel()
      : pathFn_(0), user_(0), count_(0), cursor_(0), current_(-1), pending_(-1),
        failStreak_(0), mode_(Mode::Off), phase_(Phase::Idle), shuffled_(false),
        bumperMs_(kDefaultBumperMs), bumperStart_(0), bumperUntil_(0), rng_(1u), seed_(1u) {
    for (int i = 0; i < MAX_ITEMS; ++i)
      order_[i] = (uint8_t)i;
    paintDst_[0] = paintDst_[1] = 0;
    paintKey_[0] = paintKey_[1] = 0;
  }

  // -- playlist ------------------------------------------------------------

  // `count` e quantos programas a biblioteca listou; `fn` traduz indice em
  // caminho. Chamar de novo depois de re-varrer o cartao e barato.
  void attach(int count, PathFn fn, void *user = 0) {
    pathFn_ = fn;
    user_ = user;
    setCount(count);
  }

  void setCount(int count) {
    if (count < 0)
      count = 0;
    if (count > MAX_ITEMS)
      count = MAX_ITEMS;
    if (count == count_)
      return;
    count_ = count;
    shuffled_ = false; // a permutacao antiga nao vale mais
    if (current_ >= count_)
      current_ = -1;
    if (pending_ >= count_)
      pending_ = -1;
  }

  int count() const { return count_; }

  // Semente da permutacao. Deterministica de proposito: com a mesma semente a
  // ordem se repete, o que torna o modo aleatorio testavel numa bancada. Zero
  // nao serve como estado de LCG, entao vira 1.
  void seed(uint32_t s) {
    seed_ = s ? s : 1u;
    rng_ = seed_;
    shuffled_ = false;
  }

  const char *pathAt(int index) const {
    if (!pathFn_ || index < 0 || index >= count_)
      return 0;
    return pathFn_(index, user_);
  }

  const char *pendingPath() const { return pathAt(pending_); }

  // -- modo ----------------------------------------------------------------

  Mode mode() const { return mode_; }

  void setMode(Mode m) {
    if (m == mode_)
      return;
    mode_ = m;
    shuffled_ = false;
    if (mode_ == Mode::Off)
      stop();
  }

  // OFF -> SEQUENCIAL -> ALEATORIO -> OFF. Devolve o modo novo.
  Mode cycleMode() {
    setMode(mode_ == Mode::Off ? Mode::Sequential
            : mode_ == Mode::Sequential ? Mode::Shuffle
                                        : Mode::Off);
    return mode_;
  }

  // Rotulo ASCII para a tela de configuracoes.
  const char *modeLabel() const {
    return mode_ == Mode::Off ? "DESLIGADO" : mode_ == Mode::Sequential ? "EM ORDEM" : "ALEATORIO";
  }

  // -- vinheta -------------------------------------------------------------

  void setBumperMs(uint32_t ms) { bumperMs_ = ms; }
  uint32_t bumperMs() const { return bumperMs_; }

  Phase phase() const { return phase_; }
  bool bumperActive() const { return phase_ == Phase::Bumper; }
  int currentIndex() const { return current_; }
  int pendingIndex() const { return pending_; }

  // Quanto falta da vinheta, em ms. Sempre pela diferenca sem sinal — nunca
  // `deadline - now` cru sem antes checar timeReached, senao a volta do
  // millis() devolveria um numero gigante e a vinheta ficaria eterna.
  uint32_t bumperRemainingMs(uint32_t now) const {
    if (phase_ != Phase::Bumper || timeReached(now, bumperUntil_))
      return 0;
    return bumperUntil_ - now;
  }

  uint32_t bumperElapsedMs(uint32_t now) const {
    if (phase_ != Phase::Bumper)
      return 0;
    const uint32_t d = now - bumperStart_; // subtracao sem sinal: atravessa a volta
    return d > bumperMs_ ? bumperMs_ : d;
  }

  // -- transicoes ----------------------------------------------------------

  // O programa do indice `index` comecou a tocar de verdade.
  void started(int index, uint32_t now) {
    (void)now;
    current_ = (index >= 0 && index < count_) ? index : -1;
    pending_ = -1;
    failStreak_ = 0;
    phase_ = Phase::Playing;
    invalidateBumperPaint();
    // O usuario pode ter escolhido um titulo a dedo na biblioteca no meio de
    // uma rodada aleatoria. Puxar esse titulo para a posicao do cursor mantem a
    // promessa de nao repetir ninguem ate a lista esgotar.
    if (mode_ == Mode::Shuffle && shuffled_ && current_ >= 0 && cursor_ < count_ &&
        order_[cursor_] != (uint8_t)current_) {
      for (int i = cursor_; i < count_; ++i) {
        if (order_[i] == (uint8_t)current_) {
          const uint8_t t = order_[i];
          order_[i] = order_[cursor_];
          order_[cursor_] = t;
          break;
        }
      }
    }
  }

  // O programa acabou (chamar quando playbackFinished e nao houve erro de
  // midia). Devolve true quando o canal assumiu: o proximo indice ja esta
  // escolhido e a vinheta comecou — o chamador NAO deve voltar para a
  // biblioteca. Devolve false quando o comportamento antigo vale (modo
  // desligado, lista vazia ou programas demais falhando em sequencia).
  bool finished(uint32_t now) {
    if (mode_ == Mode::Off || count_ <= 0) {
      stop();
      return false;
    }
    // Portao contra laco apertado (armadilha 4 do AGENTS.md): um cartao cheio
    // de pastas quebradas nao pode fazer o aparelho girar a lista para sempre.
    if (failStreak_ > count_) {
      stop();
      return false;
    }
    const int next = nextIndex();
    if (next < 0) {
      stop();
      return false;
    }
    pending_ = next;
    bumperStart_ = now;
    bumperUntil_ = now + bumperMs_;
    phase_ = Phase::Bumper;
    invalidateBumperPaint();
    return true;
  }

  // Acabou a vinheta? Devolve o indice a tocar agora, ou -1 enquanto nao for a
  // hora. Depois de devolver um indice, ele nao volta a ser devolvido.
  int ready(uint32_t now) {
    if (phase_ != Phase::Bumper || pending_ < 0)
      return -1;
    if (!timeReached(now, bumperUntil_))
      return -1;
    phase_ = Phase::Idle; // esperando o startProgram() do chamador
    // Ja adota o pendente como atual: se o start falhar, failed() avanca a
    // partir dele e nao tenta o mesmo de novo.
    current_ = pending_;
    return pending_;
  }

  // O startProgram() do indice devolvido por ready() falhou. Reagenda o
  // seguinte; devolve false quando ja tentou a lista inteira sem sucesso.
  bool failed(uint32_t now) {
    ++failStreak_;
    return finished(now);
  }

  // Cancelamento explicito (usuario saiu do player, erro de midia, entrou
  // outra tela). Nao mexe no modo: o canal volta a valer no proximo programa.
  void stop() {
    phase_ = Phase::Idle;
    pending_ = -1;
    failStreak_ = 0;
    invalidateBumperPaint();
  }

  // -- desenho da vinheta --------------------------------------------------

  // Cartao "A SEGUIR" + titulo do proximo programa + barra de progresso da
  // vinheta. `nextTitle` pode ser 0: o titulo sai do caminho pendente.
  //
  // Repintura: o cartao inteiro so e pintado na primeira chamada de cada
  // vinheta e para cada destino (LCD e CVBS sao dois destinos). Nas chamadas
  // seguintes so a barra cresce. Nao e micro-otimizacao: repintar o fundo a
  // cada quadro deixaria o texto ausente do framebuffer nos microssegundos em
  // que o DMA do I2S0 varre aquelas linhas, e isso pisca na TV.
  void drawBumper(lgfx::LovyanGFX *dst, int ox, int oy, const char *nextTitle, uint32_t now) {
    if (!dst || phase_ != Phase::Bumper)
      return;

    char derived[kTitleCap];
    if (!nextTitle) {
      titleOf(pending_, derived, sizeof(derived));
      nextTitle = derived;
    }

    const int barX = crt::SAFE_L, barW = crt::SAFE_W;
    const int barY = crt::SAFE_B - 28, barH = 8;

    if (needsFullPaint(dst)) {
      // O fundo pode sangrar ate a borda do raster; o conteudo, nao.
      dst->fillRect(ox, oy, crt::W, crt::H, TFT_BLACK);
      vcrfont::drawTextCentered(dst, "A SEGUIR", ox + crt::SAFE_L, oy + crt::HEAD_Y, crt::SAFE_W,
                                kAccent);
      dst->drawFastHLine(ox + crt::SAFE_L, oy + crt::HEAD_RULE_Y, crt::SAFE_W, kAccent);
      drawTitle(dst, ox, oy, nextTitle);
      dst->drawRect(ox + barX, oy + barY, barW, barH, kAccent);
      vcrfont::drawTextCentered(dst, "M5 RETRO TV", ox + crt::SAFE_L, oy + crt::SAFE_B - 16,
                                crt::SAFE_W, kDim);
    }

    // A barra so cresce da esquerda para a direita: nunca apaga pixel, entao
    // repintar nao produz cintilacao.
    const uint32_t span = bumperMs_ ? bumperMs_ : 1u;
    const int inner = barW - 2;
    int fill = (int)((uint32_t)inner * bumperElapsedMs(now) / span);
    if (fill > inner)
      fill = inner;
    if (fill > 0)
      dst->fillRect(ox + barX + 1, oy + barY + 1, fill, barH - 2, kAccent);
  }

  // Forca a proxima drawBumper() a repintar o cartao inteiro. Use ao voltar
  // para a tela depois de outra coisa ter escrito por cima.
  void invalidateBumperPaint() {
    paintDst_[0] = paintDst_[1] = 0;
    paintKey_[0] = paintKey_[1] = 0;
  }

  // Titulo ASCII de um indice, a partir do ultimo segmento do caminho. Devolve
  // false (e escreve string vazia) quando nao ha caminho.
  bool titleOf(int index, char *out, size_t cap) const {
    if (!out || cap == 0)
      return false;
    out[0] = '\0';
    const char *path = pathAt(index);
    if (!path)
      return false;
    const char *base = path;
    for (const char *p = path; *p; ++p)
      if (*p == '/' || *p == '\\')
        base = p + 1;
    if (!*base)
      base = path;
    // Texto vindo do cartao: sem normalizar, um acento vira dois buracos.
    ascii::normalizeUpper(out, cap, base);
    return out[0] != '\0';
  }

private:
  static constexpr int kTitleCap = 25;  // 22 celulas de 12 px cabem em SAFE_W
  static constexpr uint16_t kDim = 0x8410; // cinza medio, luminancia segura

  // LCG de 32 bits (Numerical Recipes). Nada de rand(): a libc do ESP32 tem
  // estado global compartilhado com o resto do firmware e nao e reproduzivel
  // numa bancada.
  uint32_t nextRandom() {
    rng_ = rng_ * 1664525u + 1013904223u;
    return rng_;
  }

  // Sorteio em [0, n) pelos bits altos — o resto de um LCG tem periodo curto
  // nos bits baixos e produziria uma "aleatoriedade" que anda em ciclo.
  int below(int n) {
    if (n <= 1)
      return 0;
    return (int)(((uint64_t)nextRandom() * (uint32_t)n) >> 32);
  }

  // Fisher-Yates completo: a rodada e uma permutacao, entao ninguem se repete
  // antes de todo mundo ter tocado. `avoid` e o programa que acabou de sair,
  // que nao pode abrir a rodada seguinte (seria repeticao imediata na virada).
  void reshuffle(int avoid) {
    for (int i = 0; i < count_; ++i)
      order_[i] = (uint8_t)i;
    for (int i = count_ - 1; i > 0; --i) {
      const int j = below(i + 1);
      const uint8_t t = order_[i];
      order_[i] = order_[j];
      order_[j] = t;
    }
    if (count_ > 1 && avoid >= 0 && order_[0] == (uint8_t)avoid) {
      const uint8_t t = order_[0];
      order_[0] = order_[count_ - 1];
      order_[count_ - 1] = t;
    }
    cursor_ = 0;
    shuffled_ = true;
  }

  int nextIndex() {
    if (count_ <= 0)
      return -1;
    if (count_ == 1)
      return 0;
    if (mode_ == Mode::Shuffle) {
      if (!shuffled_)
        reshuffle(current_);
      else if (++cursor_ >= count_)
        reshuffle(current_); // lista esgotada: nova rodada
      return (int)order_[cursor_];
    }
    return current_ < 0 ? 0 : (current_ + 1) % count_;
  }

  // Titulo grande quando couber (24x32), pequeno quando nao. Truncar e melhor
  // do que deixar escapar da area segura.
  void drawTitle(lgfx::LovyanGFX *dst, int ox, int oy, const char *title) const {
    // Normaliza mesmo quando o titulo veio pronto do chamador: ele tambem pode
    // ter saido de um meta.json do cartao, e um acento em UTF-8 sao dois bytes
    // sem glifo — dois buracos, nao um (armadilha 9 do AGENTS.md).
    char buf[kTitleCap];
    int n = (int)ascii::normalizeUpper(buf, sizeof(buf), title ? title : "");
    int scale = 2;
    int maxChars = crt::SAFE_W / (vcrfont::CELL_W * 2); // 11
    if (n > maxChars) {
      scale = 1;
      maxChars = crt::SAFE_W / vcrfont::CELL_W; // 22
      if (n > maxChars) {
        // Reticencias: sem elas o corte parece nome de pasta errado, e nao
        // titulo que nao coube.
        buf[maxChars] = '\0';
        buf[maxChars - 1] = '.';
        buf[maxChars - 2] = '.';
      }
    }
    const int h = vcrfont::textHeight(scale);
    const int y = crt::SAFE_T + (crt::SAFE_H - h) / 2;
    vcrfont::drawTextCentered(dst, buf, ox + crt::SAFE_L, oy + y, crt::SAFE_W, TFT_WHITE, scale);
  }

  // Duas vagas: exatamente os dois destinos que existem (LCD e painel CVBS).
  bool needsFullPaint(const void *dst) {
    int slot = -1;
    for (int i = 0; i < 2; ++i)
      if (paintDst_[i] == dst)
        slot = i;
    if (slot < 0)
      for (int i = 0; i < 2 && slot < 0; ++i)
        if (paintDst_[i] == 0)
          slot = i;
    if (slot < 0)
      slot = 0; // mais de dois destinos: o terceiro so repinta, nunca erra
    const uint32_t key = bumperStart_ | 1u; // 0 fica reservado para "vazio"
    if (paintDst_[slot] == dst && paintKey_[slot] == key)
      return false;
    paintDst_[slot] = dst;
    paintKey_[slot] = key;
    return true;
  }

  PathFn pathFn_;
  void *user_;
  int count_;
  int cursor_;  // posicao atual dentro de order_ (modo aleatorio)
  int current_; // indice tocando agora, -1 se nenhum
  int pending_; // indice escolhido para depois da vinheta, -1 se nenhum
  int failStreak_;
  Mode mode_;
  Phase phase_;
  bool shuffled_;
  uint32_t bumperMs_;
  uint32_t bumperStart_;
  uint32_t bumperUntil_;
  uint32_t rng_;
  uint32_t seed_;
  uint8_t order_[MAX_ITEMS];
  const void *paintDst_[2];
  uint32_t paintKey_[2];
};

} // namespace channel

namespace sleeptimer {

// OFF / 15 / 30 / 60 / 90 / 120 — os mesmos degraus do SLEEP de um
// videocassete da epoca. Em minutos; 0 e "desligado".
constexpr int OPTION_COUNT = 6;

// Array local de funcao inline em vez de tabela no escopo do namespace: evita
// objeto com ligacao interna referenciado por funcao inline (e continua sendo
// C++11 — um constexpr com laco quebraria o firmware).
inline uint16_t optionAt(int i) {
  const uint16_t v[OPTION_COUNT] = {0, 15, 30, 60, 90, 120};
  return (i >= 0 && i < OPTION_COUNT) ? v[i] : 0;
}

class SleepTimer {
public:
  SleepTimer() : option_(0), start_(0), deadline_(0) {}

  bool active() const { return option_ != 0; }
  int option() const { return option_; }
  uint16_t minutes() const { return optionAt(option_); }

  void cancel() {
    option_ = 0;
    start_ = deadline_ = 0;
  }

  // Seleciona pelo indice da tabela e rearma a contagem.
  void setOption(int i, uint32_t now) {
    option_ = (uint8_t)((i >= 0 && i < OPTION_COUNT) ? i : 0);
    arm(now);
  }

  // Seleciona por valor em minutos. Valor fora da tabela desliga o timer —
  // melhor desligado do que com um prazo que a interface nao sabe mostrar.
  void setMinutes(uint16_t m, uint32_t now) {
    for (int i = 0; i < OPTION_COUNT; ++i) {
      if (optionAt(i) == m) {
        setOption(i, now);
        return;
      }
    }
    cancel();
  }

  // Proximo degrau, dando a volta. Devolve o valor novo em minutos (0 = OFF).
  uint16_t cycle(uint32_t now) {
    setOption((option_ + 1) % OPTION_COUNT, now);
    return minutes();
  }

  // Reinicia a contagem sem mudar o valor (o usuario mexeu em algo: nao e hora
  // de desligar na cara dele).
  void restart(uint32_t now) { arm(now); }

  // Venceu? Unico lugar que decide isso. timeReached() compara a DIFERENCA com
  // sinal: `now >= deadline` cru daria falso para sempre depois da volta do
  // millis(), e o aparelho nunca desligaria.
  bool expired(uint32_t now) const { return active() && timeReached(now, deadline_); }

  uint32_t remainingMs(uint32_t now) const {
    if (!active() || timeReached(now, deadline_))
      return 0;
    return deadline_ - now;
  }

  // Arredonda para cima: enquanto sobrar 1 s o mostrador diz "1", nunca "0".
  // Um "SLEEP 0" na tela por um minuto inteiro parece aparelho travado.
  uint16_t remainingMinutes(uint32_t now) const {
    return (uint16_t)((remainingMs(now) + 59999UL) / 60000UL);
  }

  uint32_t deadline() const { return deadline_; }

  // Indicador pequeno "SLEEP 30", alinhado a direita da area segura. Com
  // contorno preto por glifo (mesma ideia do VcrOsd) para continuar legivel
  // por cima da imagem, sem tarja de fundo.
  void drawBadge(lgfx::LovyanGFX *dst, int ox, int oy, uint32_t now, int y = crt::SAFE_T,
                 int32_t ink = (int32_t)channel::kAccent, int32_t outline = TFT_BLACK) const {
    if (!dst || !active())
      return;
    char text[16];
    snprintf(text, sizeof(text), "SLEEP %u", (unsigned)remainingMinutes(now));
    const int w = vcrfont::textWidth(text);
    vcrfont::drawText(dst, text, ox + crt::SAFE_R - w, oy + y, ink, 1, outline);
  }

private:
  void arm(uint32_t now) {
    start_ = now;
    // 120 min = 7.200.000 ms, folgado dentro dos 24,8 dias em que a
    // comparacao com sinal do timeReached() vale.
    deadline_ = now + (uint32_t)minutes() * 60000UL;
  }

  uint8_t option_;
  uint32_t start_;
  uint32_t deadline_;
};

} // namespace sleeptimer

#pragma once
// ============================================================================
//  PhotoShow — slideshow de fotos (.jpg/.jpeg) do cartão na saída composta.
//
//  Mostra uma foto por vez, centralizada no quadro de 320x240, avançando
//  sozinha num prazo configurável (3/5/10/30 s) e também pelos três botões.
//  A pasta é /M5RETRO/fotos.
//
//  ---------------------------------------------------------------------------
//  Regras deste aparelho que moldaram a API (ver AGENTS.md)
//  ---------------------------------------------------------------------------
//
//  1. A SRAM é o recurso escasso (o framebuffer CVBS já leva 150 KB e o heap
//     livre medido fica entre 28 e 38 KB). Por isso este header **não aloca
//     nada**, seguindo o mesmo contrato do ScreenFx.h:
//
//       * o buffer de decodificação é o `jpegBuffer` que o main.cpp já mantém
//         na PSRAM para o vídeo (128 KiB) — entra por `attachBuffer()`;
//       * a instância do JPEGDEC também é a do main.cpp (a JPEGIMAGE tem
//         dezenas de KB; duas não caberiam) — entra por `attachDecoder()`;
//       * o catálogo de nomes mora num "pool" fornecido pelo chamador
//         (`attachStorage()`), que pode ficar na PSRAM. Guardamos só o nome
//         curto de cada arquivo, nunca o caminho completo: o caminho é montado
//         num buffer de pilha, um de cada vez, na hora de abrir.
//
//     Nada de LGFX_Sprite aqui: um sprite de 5 KB já causou falta de memória
//     neste projeto, e um de tela cheia (76.800 B em RGB332) não cabe.
//
//  2. Transições são as do include/ScreenFx.h — este arquivo não tem dither
//     próprio. **Achado importante**: `crossfade()` e `fadeIn()` exigem um
//     LGFX_Sprite 320x240 RGB332 do chamador e, recebendo `nullptr`, caem em
//     `hardCut()` — corte seco, sem nenhuma animação, devolvendo false. Já o
//     `fadeThrough()` com `nullptr` continua **visível**: ele esmaece até o
//     preto com o dither de Bayer (que não precisa de buffer nenhum) e só o
//     segundo tempo, o reacender, vira corte seco. Como aqui não há SRAM para
//     o sprite, `beginTransition()` usa `fadeThrough`. É de propósito.
//
//  3. `millis()` dá a volta em ~49 dias. O prazo usa `timeReached()` da
//     UiLogic.h (aritmética com sinal sobre a diferença), nunca `now > prazo`.
//
//  4. O cartão é disputado com a tarefa de áudio e é protegido pelo `sdMutex`
//     do main.cpp. **Este header nunca toma o mutex.** As duas únicas funções
//     que tocam o cartão — `scan()` e `load()` — estão marcadas com
//     "PRÉ-CONDIÇÃO: o chamador segura o sdMutex" e são curtas de propósito,
//     para o mutex ser devolvido logo (segurar mata o áudio de fome). O
//     desenho, que é a parte demorada, **não toca no cartão**: ele
//     redecodifica os bytes que já estão no `jpegBuffer`, exatamente como o
//     `redrawCurrentFrame()` do player faz.
//
//  5. Texto em ASCII maiúsculo (`ascii::normalizeUpper`), porque as fontes
//     bitmap só têm ASCII e um nome acentuado viraria buraco duplo. O nome
//     guardado no catálogo é o **cru**, do jeito que veio do cartão — é ele
//     que abre o arquivo; a normalização acontece só na hora de desenhar.
//
//  6. Sem ciano saturado (0x07FF) na saída composta: dot crawl. O acento é o
//     mesmo 0x96BC do resto do firmware.
//
//  7. Texto e faixas dentro de crt::SAFE_* (SafeArea.h). A foto em si pode
//     usar o quadro inteiro — só ela sangra até a borda do raster.
//
//  8. O JPEGDEC deste projeto não decodifica tudo o que se chama JPEG. Um
//     arquivo maior que o jpegBuffer (MAX_JPEG = 128 KiB: uma foto de câmera
//     de 4000x3168 tem ~560 KB) é recusado pelo TAMANHO, antes de ler; um
//     progressivo e um 4:4:4 são recusados pelo CABEÇALHO, antes de decodificar.
//     Ver o bloco "O que ESTA versão do JPEGDEC realmente decodifica", abaixo.
//     Em todos esses casos a tela mostra o motivo e a apresentação segue no
//     próximo prazo — nada de travar nem de deixar meia foto na tela.
//
//  ---------------------------------------------------------------------------
//  Uso (integração no main.cpp)
//  ---------------------------------------------------------------------------
//
//    photo::Show photos;
//    // storage na PSRAM, uma vez no setup():
//    photos.attachStorage((char *)ps_malloc(photo::POOL_SUGGESTED), photo::POOL_SUGGESTED,
//                         (uint16_t *)ps_malloc(photo::MAX_ENTRIES * 2), photo::MAX_ENTRIES);
//    photos.attachBuffer(jpegBuffer, MAX_JPEG);
//    photos.attachDecoder(&jpeg);
//
//    // ao entrar na tela (zera todo o estado — armadilha 6 do AGENTS.md):
//    photos.reset(millis());
//    take(sdMutex); photos.scan(SD); give(sdMutex);
//    take(sdMutex); photos.load(SD, millis()); give(sdMutex);
//    photos.paint(&rca, 0, 0);   // primeiro quadro, sem transição
//
//    // no loop():
//    if (tx.busy())            tx.tick(millis());
//    else if (photos.dueForNext(millis())) {
//      photos.advance(1, millis());
//      take(sdMutex); photos.load(SD, millis()); give(sdMutex);
//      photos.beginTransition(tx, millis(), nullptr);
//    }
//
//  Compila em -std=gnu++11. Depende de M5GFX (pelo ScreenFx.h), SafeArea.h,
//  Ascii.h e UiLogic.h. SD e JPEGDEC são detectados por __has_include: sem
//  eles (simulador de desktop) o arquivo continua compilando, só sem as duas
//  funções de cartão e sem o decode — o que permite testar a lógica pura em
//  sim/probes/photo_show.cpp.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "ScreenFx.h"
#include "UiLogic.h" // timeReached()

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#if !defined(PHOTOSHOW_HAS_JPEGDEC) && defined(__has_include)
#if __has_include(<JPEGDEC.h>)
#define PHOTOSHOW_HAS_JPEGDEC 1
#endif
#endif
#if !defined(PHOTOSHOW_HAS_SD) && defined(__has_include)
#if __has_include(<FS.h>)
#define PHOTOSHOW_HAS_SD 1
#endif
#endif

#if PHOTOSHOW_HAS_JPEGDEC
#include <JPEGDEC.h>
#endif
#if PHOTOSHOW_HAS_SD
#include <FS.h>
