namespace photo {

// ---------------------------------------------------------------------------
//  Limites e aparência
// ---------------------------------------------------------------------------

// Teto de fotos catalogadas. 256 já é mais do que alguém navega com três
// botões, e o custo é só o vetor de deslocamentos (2 B por entrada).
const int MAX_ENTRIES = 256;
// Maior nome de arquivo aceito. Acima disso a foto é ignorada: sem o nome
// inteiro não dá para reabrir o arquivo depois.
const int NAME_LIMIT = 63;
// Pool sugerido para os nomes. Com nome médio de ~16 caracteres cabem ~240
// fotos; quando acaba, a varredura para e `dropped()` conta o que ficou fora.
const int POOL_SUGGESTED = 4096;

constexpr const char *kDefaultDir = "/M5RETRO/fotos";
constexpr const char *kTitle = "FOTOS";
// Legendas dos três botões. O pintor desenha esta faixa ele mesmo: as
// transições repintam a tela inteira, e algo desenhado só uma vez pelo
// chamador sumiria no primeiro esmaecimento (armadilha 7 do AGENTS.md).
constexpr const char *kBtnPrev = "ANTERIOR";
constexpr const char *kBtnDwell = "TEMPO";
constexpr const char *kBtnNext = "PROXIMA";

// Mesmo acento seguro do resto do firmware. Ciano puro (0x07FF) faz dot crawl
// na composta; este azul claro tem a mesma luminância e croma baixo.
const uint16_t ACCENT = 0x96BC;

// Faixa da legenda, logo acima da barra de botões, dentro da área segura.
const int CAPTION_H = 16;
const int CAPTION_Y = crt::BAR_Y - CAPTION_H - 4; // 182 .. 198

// Prazos oferecidos pelo botão do meio, em milissegundos.
// C++11: corpo de constexpr é UM return só — nada de laço ou variável local.
constexpr uint32_t dwellMsAt(int slot) {
  return slot <= 0 ? 3000u : slot == 1 ? 5000u : slot == 2 ? 10000u : 30000u;
}
const int DWELL_SLOTS = 4;

// ---------------------------------------------------------------------------
//  Escolha do fator de redução do JPEGDEC
// ---------------------------------------------------------------------------
//
//  O JPEGDEC reduz na própria decodificação (1/2, 1/4, 1/8), sem buffer
//  intermediário: os blocos já saem menores para o callback. É o que permite
//  uma foto de câmera de 4000x3000 virar imagem na tela sem nada de 12
//  megapixels na memória.
//
//  Os valores de JPEG_SCALE_HALF/QUARTER/EIGHTH são 2, 4 e 8, e escala 1 é
//  opção 0 — por isso `option` sai daqui sem precisar do JPEGDEC.h, e esta
//  função pode ser testada no desktop.
struct Fit {
  uint8_t scale;  // 1, 2, 4 ou 8
  uint8_t option; // 0, 2, 4 ou 8 (o que vai em jpeg.decode(0,0,option))
  int16_t w, h;   // dimensões já reduzidas
  bool fits;      // false = nem 1/8 coube; desenha recortada no centro
};

// Regra: reduzir enquanto a imagem AINDA COBRIR o quadro, e parar antes do
// passo que a deixaria menor. O excesso e recortado no centro pelo desenho.
//
// A alternativa -- reduzir ate caber inteira -- parece mais segura e e pior de
// olhar. Uma foto de 1364x1080 cabe inteira so em 1/8, que da 171x135: pouco
// mais de um quarto do quadro, cercada de tarja preta. Em 1/4 ela da 341x270,
// estoura 6% e some so com as bordas. Na TV, 6% de recorte nao se nota; 171x135
// no meio de um quadro de 320x240 se nota de longe. E o CRT ja come ~7% por
// borda em overscan de qualquer jeito, entao parte desse recorte nem chega a
// ser visivel.
//
// Nao existe 1/16 no JPEGDEC, entao uma foto de camera de 4000 px para em 1/8 e
// sai recortada (500x396 -> fits=false), que e o melhor possivel sem
// redimensionar antes. tools/prepare_photos.py evita esse caso na origem.
inline Fit fitFor(int srcW, int srcH) {
  Fit f;
  int s = 1;
  while (s < 8) {
    const int nx = s * 2;
    // Para se o proximo passo derrubar qualquer um dos lados abaixo do quadro.
    if ((srcW + nx - 1) / nx < crt::W || (srcH + nx - 1) / nx < crt::H)
      break;
    s = nx;
  }
  f.scale = (uint8_t)s;
  f.option = (uint8_t)(s == 1 ? 0 : s);
  f.w = (int16_t)((srcW + s - 1) / s);
  f.h = (int16_t)((srcH + s - 1) / s);
  f.fits = (f.w <= crt::W && f.h <= crt::H);
  return f;
}

// ---------------------------------------------------------------------------
//  O que ESTA versão do JPEGDEC realmente decodifica
// ---------------------------------------------------------------------------
//
//  Medido na biblioteca do próprio projeto
//  (.pio/libdeps/m5stack-core2/JPEGDEC), não suposto:
//
//   * PROGRESSIVO FALHA EM SILÊNCIO — e é o caso perigoso. `decode()` devolve
//     sucesso e `getLastError()` devolve 0, mas só sai 1/8 da imagem: o
//     jpeg.inl, linha 4961, diz "progressive mode - we only decode the first
//     scan (DC values)". Uma foto de 320x240 vira um borrão de 40x30. Não há
//     código de erro para pegar isso DEPOIS, então a checagem é ANTES, pelo
//     `getJPEGType()` (0xC2 = SOF2 = progressivo). Exportadores web e o "Save
//     for Web" do Photoshop geram progressivo por padrão, então isto acontece
//     com foto de gente de verdade, não é caso de laboratório.
//
//   * 4:4:4 (yuvj444p) NÃO DECODIFICA: devolve JPEG_DECODE_ERROR, e pior,
//     depois de já ter chamado o callback para alguns blocos — sobra meia
//     imagem na tela. Por isso o pintor LIMPA o quadro quando o decode falha.
//     O Y do SOF sai em `getSubSample()`: 0x11 é 4:4:4 (recusado), 0x21/0x12/
//     0x22 são os 4:2:2/4:2:0 que funcionam, e 0 é escala de cinza (1 só
//     componente), que funciona e não pode ser confundida com 4:4:4.
//
//  Formato recomendado para o cartão: 320x240, baseline, yuvj420p, -q:v 5
//  (~8 KB por foto). O resto é tratado com educação, não com travamento.
enum Support : uint8_t { SUP_OK, SUP_PROGRESSIVE, SUP_SUBSAMPLE };

// `jpegType` é o que o getJPEGType() devolve (0 = baseline, 1 = progressivo) e
// `subSample` o que o getSubSample() devolve. Fora do JPEGDEC.h de propósito,
// para poder ser testado no desktop.
inline Support supportFor(int jpegType, int subSample) {
  return jpegType == 1 ? SUP_PROGRESSIVE : (subSample == 0x11 ? SUP_SUBSAMPLE : SUP_OK);
}

// ---------------------------------------------------------------------------
//  Resultado da última tentativa de carregar uma foto
// ---------------------------------------------------------------------------
enum Result : uint8_t {
  RES_NONE,        // ainda não se tentou carregar nada
  RES_OK,          // bytes no buffer, dimensões conhecidas
  RES_EMPTY,       // a pasta não tem foto nenhuma
  RES_NO_BUFFER,   // faltou attachBuffer()/attachDecoder()
  RES_UNREADABLE,  // não abriu, ou a leitura veio curta
  RES_TOO_BIG,     // arquivo maior que o jpegBuffer (MAX_JPEG = 128 KiB)
  RES_BAD_JPEG,    // cabeçalho inválido, ou o decode falhou no meio
  RES_PROGRESSIVE, // JPEG progressivo: sairia 1/8 da imagem, sem erro nenhum
  RES_SUBSAMPLE    // 4:4:4: o decodificador desiste no meio do quadro
};

// Mensagem ASCII maiúscula correspondente, para a tela.
inline const char *message(Result r) {
  return r == RES_OK            ? ""
         : r == RES_EMPTY       ? "SEM FOTOS NO CARTAO"
         : r == RES_NO_BUFFER   ? "SEM MEMORIA PARA DECODIFICAR"
         : r == RES_UNREADABLE  ? "NAO FOI POSSIVEL LER A FOTO"
         : r == RES_TOO_BIG     ? "FOTO MUITO GRANDE - PULANDO"
         : r == RES_BAD_JPEG    ? "FOTO INVALIDA - PULANDO"
         : r == RES_PROGRESSIVE ? "JPEG PROGRESSIVO - USE BASELINE"
         : r == RES_SUBSAMPLE   ? "JPEG 4:4:4 - USE 4:2:0"
                                : "CARREGANDO";
}

// ---------------------------------------------------------------------------
//  Catálogo: nomes curtos num pool do chamador, ordenados por nome
// ---------------------------------------------------------------------------
class Catalog {
public:
  Catalog()
      : pool_(nullptr), off_(nullptr), poolCap_(0), poolUsed_(0), maxEntries_(0), count_(0),
        dropped_(0) {}

  // `pool` guarda os nomes (com o \0); `offsets` tem um uint16_t por entrada.
  // Os dois podem vir da PSRAM — este header nunca aloca.
  void attachStorage(char *pool, uint16_t poolCap, uint16_t *offsets, uint16_t maxEntries) {
    pool_ = pool;
    poolCap_ = poolCap;
    off_ = offsets;
    maxEntries_ = maxEntries > (uint16_t)MAX_ENTRIES ? (uint16_t)MAX_ENTRIES : maxEntries;
    clear();
  }
  bool attached() const { return pool_ && off_ && poolCap_ > 0 && maxEntries_ > 0; }
  void clear() {
    poolUsed_ = 0;
    count_ = 0;
    dropped_ = 0;
  }

  int count() const { return count_; }
  int dropped() const { return dropped_; } // quantas ficaram de fora do pool
  int capacity() const { return maxEntries_; }
  const char *name(int i) const { return (i >= 0 && i < count_) ? pool_ + off_[i] : ""; }

  // O iterador de diretório do ESP32 às vezes devolve o caminho inteiro
  // ("/M5RETRO/fotos/a.jpg") e às vezes só o nome. Fica só o nome.
  static const char *baseName(const char *p) {
    if (!p)
      return "";
    const char *s = strrchr(p, '/');
    return s ? s + 1 : p;
  }

  // Extensão .jpg/.jpeg, sem diferenciar caixa. Ignora o que começa com '.'
  // (arquivos de recurso do macOS, "._IMG_0001.JPG", são lixo no cartão).
  static bool isJpeg(const char *name) {
    if (!name || !*name || name[0] == '.')
      return false;
    const size_t n = strlen(name);
    if (n > 4 && lowerEq(name + n - 4, ".jpg", 4))
      return true;
    return n > 5 && lowerEq(name + n - 5, ".jpeg", 5);
  }

  // Guarda o nome CRU (é ele que abre o arquivo). Devolve false quando não é
  // foto ou quando não coube. Não ordena: chame sort() no fim da varredura.
  bool add(const char *rawName) {
    if (!attached())
      return false;
    const char *n = baseName(rawName);
    if (!isJpeg(n))
      return false;
    const size_t len = strlen(n);
    if (len > (size_t)NAME_LIMIT || count_ >= maxEntries_ ||
        poolUsed_ + (uint32_t)len + 1 > (uint32_t)poolCap_) {
      ++dropped_;
      return false;
    }
    memcpy(pool_ + poolUsed_, n, len + 1);
    off_[count_++] = poolUsed_;
    poolUsed_ = (uint16_t)(poolUsed_ + len + 1);
    return true;
  }

  // Ordena por nome, sem diferenciar caixa. Inserção sobre o vetor de
  // deslocamentos: os nomes não se movem no pool, só os índices. Com 256
  // entradas o pior caso são ~32 mil comparações curtas — milissegundos, e
  // roda uma vez por visita à tela.
  void sort() {
    for (int i = 1; i < count_; ++i) {
      const uint16_t key = off_[i];
      int j = i - 1;
      while (j >= 0 && casecmp(pool_ + off_[j], pool_ + key) > 0) {
        off_[j + 1] = off_[j];
        --j;
      }
      off_[j + 1] = key;
    }
  }

  // Monta "dir/nome" num buffer do chamador. É o único lugar onde um caminho
  // completo existe, e ele vive só durante o open().
  bool path(int i, const char *dir, char *dst, size_t cap) const {
    if (!dst || cap == 0)
      return false;
    dst[0] = 0;
    const char *n = name(i);
    if (!dir || !n[0])
      return false;
    const int need = snprintf(dst, cap, "%s/%s", dir, n);
    return need > 0 && (size_t)need < cap;
  }

  static int casecmp(const char *a, const char *b) {
    while (*a && *b) {
      const int ca = up(*a), cb = up(*b);
      if (ca != cb)
        return ca - cb;
      ++a;
      ++b;
    }
    return up(*a) - up(*b);
  }

private:
  static int up(char c) { return (c >= 'a' && c <= 'z') ? c - ('a' - 'A') : (unsigned char)c; }
  static bool lowerEq(const char *s, const char *lower, size_t n) {
    for (size_t i = 0; i < n; ++i)
      if (up(s[i]) != up(lower[i]))
        return false;
    return true;
  }

  char *pool_;
  uint16_t *off_;
  uint16_t poolCap_, poolUsed_, maxEntries_;
  int count_, dropped_;
};

// ---------------------------------------------------------------------------
//  Alvo do callback do JPEGDEC
// ---------------------------------------------------------------------------
//  O JPEGDEC só aceita ponteiro de função (nada de lambda com captura), então
//  o destino do bloco vai por um contexto de arquivo — mesmo padrão do
//  `posterSprite` do main.cpp. Fica num static de função para o header
//  continuar sem .cpp (C++11 não tem variável `inline`).
struct Blit {
  lgfx::LovyanGFX *dst;
  int x0, y0;
  int32_t clipW, clipH; // tamanho do destino, para descartar bloco fora dele
};
inline Blit &blitCtx() {
  static Blit b = {nullptr, 0, 0, 0, 0};
  return b;
}

#if PHOTOSHOW_HAS_JPEGDEC
inline int blitCallback(JPEGDRAW *draw) {
  Blit &b = blitCtx();
  if (!b.dst)
    return 1;
  const int x = b.x0 + draw->x, y = b.y0 + draw->y;
  // Uma foto de 4000x3168 ainda sai 500x396 em 1/8 — o JPEGDEC não tem 1/16 —
  // então há blocos fora da tela em toda apresentação com foto de câmera.
  // Descartar o bloco inteiramente fora poupa a chamada; o parcialmente fora
  // vai para o pushImage, que recorta contra o clipRect corrente nos quatro
  // lados (LGFXBase::pushImage, ajuste de _clip_l/_clip_t + _adjust_width) e
  // corrige o ponteiro de origem. Nada é escrito fora do painel.
  if (x >= b.clipW || y >= b.clipH || x + draw->iWidth <= 0 || y + draw->iHeight <= 0)
    return 1;
  b.dst->pushImage(x, y, draw->iWidth, draw->iHeight,
                   reinterpret_cast<const lgfx::rgb565_t *>(draw->pPixels));
  return 1;
}
#endif

// ---------------------------------------------------------------------------
//  A tela
// ---------------------------------------------------------------------------
class Show {
public:
  // O que o chamador precisa fazer depois de um botão.
  enum Action : uint8_t {
    ACT_NONE,    // nada mudou
    ACT_REPAINT, // só redesenhar (mudou o prazo)
    ACT_LOAD     // trocou de foto: load() com o mutex e depois a transição
  };

  Show()
      : dir_(kDefaultDir), buf_(nullptr), bufCap_(0), index_(0), dwell_(1), deadline_(0),
        result_(RES_NONE), bytes_(0), srcW_(0), srcH_(0) {
#if PHOTOSHOW_HAS_JPEGDEC
    jpeg_ = nullptr;
#endif
    fit_ = fitFor(1, 1);
  }

  // -- ligações (uma vez, no setup) -----------------------------------------

  void attachStorage(char *pool, uint16_t poolCap, uint16_t *offsets, uint16_t maxEntries) {
    cat_.attachStorage(pool, poolCap, offsets, maxEntries);
  }
  // REUSA o jpegBuffer do vídeo (PSRAM, 128 KiB). Não alocar outro.
  void attachBuffer(uint8_t *jpegBuffer, size_t cap) {
    buf_ = jpegBuffer;
    bufCap_ = cap;
  }
#if PHOTOSHOW_HAS_JPEGDEC
  // REUSA a instância global do JPEGDEC: a JPEGIMAGE é grande demais para duas.
  void attachDecoder(JPEGDEC *dec) { jpeg_ = dec; }
#endif
  void setFolder(const char *dir) { dir_ = dir ? dir : kDefaultDir; }
  const char *folder() const { return dir_; }

  // Zera TUDO ao entrar na tela. Estado static/membro herdado da visita
  // anterior é a armadilha 6 do AGENTS.md.
  void reset(uint32_t now) {
    cat_.clear();
    index_ = 0;
    result_ = RES_NONE;
    bytes_ = 0;
    srcW_ = srcH_ = 0;
    fit_ = fitFor(1, 1);
    resetTimer(now);
  }

  // -- catálogo --------------------------------------------------------------

  Catalog &catalog() { return cat_; } // exposto para teste nativo e diagnóstico
  const Catalog &catalog() const { return cat_; }
  int count() const { return cat_.count(); }
  int index() const { return index_; }
  const char *rawName() const { return cat_.name(index_); }

  // Nome da foto corrente em ASCII maiúsculo, para desenhar.
  size_t displayName(char *dst, size_t cap) const {
    return ascii::normalizeUpper(dst, cap, cat_.name(index_));
  }

  // Fecha a varredura: ordena, prende o índice na faixa e reinicia o prazo.
  // Chamado pelo scan(); público para o probe nativo poder alimentar o
  // catálogo à mão, sem cartão.
  void afterScan(uint32_t now) {
    cat_.sort();
    if (index_ >= cat_.count())
      index_ = 0;
    result_ = cat_.count() ? RES_NONE : RES_EMPTY;
    bytes_ = 0;
    resetTimer(now);
  }

  // -- navegação e prazo -----------------------------------------------------

  int dwellSlot() const { return dwell_; }
  uint32_t dwellMs() const { return dwellMsAt(dwell_); }
  uint32_t deadline() const { return deadline_; }

  void resetTimer(uint32_t now) { deadline_ = now + dwellMs(); }

  // Prazo vencido? `timeReached` compara a DIFERENÇA com sinal, então o wrap
  // de millis() (~49 dias) não faz a foto congelar nem correr.
  bool dueForNext(uint32_t now) const { return cat_.count() > 0 && timeReached(now, deadline_); }

  // Avança `delta` fotos, dando a volta nas duas pontas. Reinicia o prazo.
  void advance(int delta, uint32_t now) {
    const int n = cat_.count();
    if (n <= 0) {
      index_ = 0;
      resetTimer(now);
      return;
    }
    int i = (index_ + delta) % n;
    if (i < 0)
      i += n; // % em C++ pode devolver negativo
    index_ = i;
    bytes_ = 0;
    result_ = RES_NONE;
    resetTimer(now);
  }

  void setIndex(int i, uint32_t now) { advance(i - index_, now); }

  void cycleDwell(uint32_t now) {
    dwell_ = (dwell_ + 1) % DWELL_SLOTS;
    resetTimer(now); // o prazo novo vale a partir de agora
  }

  // Botões: 0 = anterior, 1 = tempo, 2 = próxima.
  Action onButton(int button, uint32_t now) {
    if (button == 0) {
      advance(-1, now);
      return ACT_LOAD;
    }
    if (button == 2) {
      advance(1, now);
      return ACT_LOAD;
    }
    if (button == 1) {
      cycleDwell(now);
      return ACT_REPAINT;
    }
    return ACT_NONE;
  }

  // -- estado da foto --------------------------------------------------------

  Result result() const { return result_; }
  const char *statusText() const { return message(result_); }
  bool hasImage() const { return result_ == RES_OK && bytes_ > 0; }
  size_t bytes() const { return bytes_; }
  int srcWidth() const { return srcW_; }
  int srcHeight() const { return srcH_; }
  const Fit &fit() const { return fit_; }

  // -- cartão (PRÉ-CONDIÇÃO: o chamador segura o sdMutex) --------------------
#if PHOTOSHOW_HAS_SD
  // Lista a pasta e ordena. Curto de propósito: só lê nomes de diretório.
  //
  // PRÉ-CONDIÇÃO: o chamador já tomou o sdMutex e o devolve logo depois.
  int scan(fs::FS &fs, uint32_t now = 0) {
    cat_.clear();
    fs::File dir = fs.open(dir_);
    if (!dir || !dir.isDirectory()) {
      if (dir)
        dir.close();
      afterScan(now);
      return 0;
    }
    for (fs::File e = dir.openNextFile(); e; e = dir.openNextFile()) {
      if (!e.isDirectory())
        cat_.add(e.name());
      e.close();
    }
    dir.close();
    afterScan(now);
    return cat_.count();
  }

  // Lê a foto corrente inteira para o jpegBuffer e mede as dimensões. O
  // decode de verdade acontece no pintor, sem cartão — assim o mutex fica
  // preso só pelo tempo da leitura.
  //
  // PRÉ-CONDIÇÃO: o chamador já tomou o sdMutex e o devolve logo depois.
  Result load(fs::FS &fs, uint32_t now) {
    bytes_ = 0;
    srcW_ = srcH_ = 0;
    if (!cat_.count())
      return finish(RES_EMPTY, now);
    if (!buf_ || bufCap_ == 0)
      return finish(RES_NO_BUFFER, now);
    char p[160];
    if (!cat_.path(index_, dir_, p, sizeof(p)))
      return finish(RES_UNREADABLE, now);
    fs::File f = fs.open(p);
    if (!f || f.isDirectory()) {
      if (f)
        f.close();
      return finish(RES_UNREADABLE, now);
    }
    const size_t size = (size_t)f.size();
    if (size == 0) {
      f.close();
      return finish(RES_BAD_JPEG, now);
    }
    // Maior que o buffer: pula com mensagem em vez de arriscar a memória.
    if (size > bufCap_) {
      f.close();
      return finish(RES_TOO_BIG, now);
    }
    const size_t got = f.read(buf_, size);
    f.close();
    if (got != size)
      return finish(RES_UNREADABLE, now);
    bytes_ = size;
    return measure(now);
  }
#endif // PHOTOSHOW_HAS_SD

  // Mede o cabeçalho do que já está no buffer e escolhe a redução. Separado do
  // load() para o chamador poder alimentar o buffer por outro caminho.
  Result measure(uint32_t now) {
#if PHOTOSHOW_HAS_JPEGDEC
    if (!jpeg_ || !buf_ || !bytes_)
      return finish(RES_NO_BUFFER, now);
    if (!jpeg_->openRAM(buf_, (int)bytes_, blitCallback)) {
      bytes_ = 0;
      return finish(RES_BAD_JPEG, now);
    }
    srcW_ = jpeg_->getWidth();
    srcH_ = jpeg_->getHeight();
    // Formato do arquivo, ainda com o cabeçalho aberto. É a ÚNICA chance de
    // pegar o progressivo: depois do decode ele mente que deu certo.
    const Support sup = supportFor(jpeg_->getJPEGType(), jpeg_->getSubSample());
    jpeg_->close();
    if (srcW_ < 1 || srcH_ < 1) {
      bytes_ = 0;
      return finish(RES_BAD_JPEG, now);
    }
    if (sup != SUP_OK) {
      bytes_ = 0; // não chega a desenhar nada: a tela mostra o motivo
      return finish(sup == SUP_PROGRESSIVE ? RES_PROGRESSIVE : RES_SUBSAMPLE, now);
    }
    fit_ = fitFor(srcW_, srcH_);
    return finish(RES_OK, now);
#else
    (void)now;
    return finish(RES_NO_BUFFER, now);
#endif
  }

  // -- desenho ---------------------------------------------------------------

  // Pintor no formato dos outros: soma (ox, oy) a TUDO, não mexe no recorte
  // (é por ele que o ScreenFx limita o repinte) e pode ser chamado mais de uma
  // vez no mesmo quadro. Serve para o painel CVBS e para o LCD.
  void paint(lgfx::LovyanGFX *dst, int ox, int oy) {
    if (!dst)
      return;
    dst->fillScreen(TFT_BLACK); // respeita o recorte corrente
    if (!decodeInto(dst, ox, oy))
      drawMessage(dst, ox, oy);
    if (cat_.count() > 0)
      drawCaption(dst, ox, oy);
    drawLegend(dst, ox, oy);
  }

  // Ponte para o crt::fx::Paint (que leva um void* em vez do this).
  static void paintFn(lgfx::LovyanGFX *dst, int ox, int oy, void *user) {
    if (user)
      static_cast<Show *>(user)->paint(dst, ox, oy);
  }
  crt::fx::Screen screen() { return crt::fx::screen(&Show::paintFn, this); }

  // Começa a transição para a foto corrente.
  //
  // `scratch` é o LGFX_Sprite 320x240 RGB332 que o crossfade exigiria. NESTE
  // APARELHO ELE É SEMPRE nullptr: não há SRAM para 76.800 bytes e a PSRAM
  // está descartada para o caminho de vídeo. Por isso aqui se usa
  // `fadeThrough`, e não `crossfade`: sem sprite o crossfade vira corte seco
  // puro (hardCut), enquanto o fadeThrough ainda esmaece de verdade até o
  // preto com o dither de Bayer — que não precisa de buffer nenhum — e só o
  // reacender é que vira corte. Devolve o que o ScreenFx devolveu (false =
  // degradou, que é o esperado com nullptr).
  bool beginTransition(crt::fx::Transition &tx, uint32_t now, lgfx::LGFX_Sprite *scratch = nullptr,
                       uint32_t msOut = 260, uint32_t msIn = 200) {
    return tx.fadeThrough(now, screen(), scratch, msOut, msIn, TFT_BLACK);
  }

private:
  Result finish(Result r, uint32_t now) {
    result_ = r;
    // Mesmo com erro o prazo recomeça: a foto ruim mostra a mensagem e some
    // sozinha no próximo avanço, em vez de travar a apresentação.
    resetTimer(now);
    return r;
  }

  bool decodeInto(lgfx::LovyanGFX *dst, int ox, int oy) {
#if PHOTOSHOW_HAS_JPEGDEC
    if (!hasImage() || !jpeg_)
      return false;
    if (!jpeg_->openRAM(buf_, (int)bytes_, blitCallback))
      return false;
    jpeg_->setPixelType(RGB565_LITTLE_ENDIAN);
    Blit &b = blitCtx();
    b.dst = dst;
    // Centralizado. Quando nem 1/8 coube, a origem fica negativa e o
    // pushImage recorta: aparece o centro da foto, que é o menos ruim.
    b.x0 = ox + (crt::W - fit_.w) / 2;
    b.y0 = oy + (crt::H - fit_.h) / 2;
    b.clipW = dst->width();
    b.clipH = dst->height();
    const bool ok = jpeg_->decode(0, 0, (int)fit_.option) != 0;
    b.dst = nullptr;
    jpeg_->close();
    if (!ok) {
      // O decode falha DEPOIS de ter desenhado alguns blocos (foi assim que o
      // 4:4:4 deixou uma tira de 320x80 na tela). Limpar é obrigatório, senão
      // fica meia foto sob a mensagem de erro.
      dst->fillScreen(TFT_BLACK);
      bytes_ = 0;
      result_ = RES_BAD_JPEG; // a mensagem logo abaixo já sai com o motivo certo
    }
    return ok;
#else
    (void)dst;
    (void)ox;
    (void)oy;
    return false;
#endif
  }

  // Tela de recado: título + motivo, centralizados na área segura.
  void drawMessage(lgfx::LovyanGFX *dst, int ox, int oy) {
    dst->setFont(&fonts::Font2);
    dst->setTextSize(1);
    dst->setTextDatum(top_left);
    dst->setTextColor(TFT_WHITE, TFT_BLACK);
    dst->drawString(kTitle, ox + crt::SAFE_L, oy + crt::HEAD_Y);
    dst->drawFastHLine(ox + crt::SAFE_L, oy + crt::HEAD_RULE_Y, crt::SAFE_W, ACCENT);
    dst->setTextDatum(middle_center);
    dst->setTextColor(ACCENT, TFT_BLACK);
    dst->drawString(statusText(), ox + crt::W / 2, oy + crt::H / 2 - 8);
    if (cat_.count() > 0) {
      char nm[40];
      displayName(nm, sizeof(nm));
      dst->setFont(&fonts::Font0);
      dst->setTextColor(TFT_WHITE, TFT_BLACK);
      dst->drawString(nm, ox + crt::W / 2, oy + crt::H / 2 + 14);
    }
  }

  // Faixa da legenda: nome à esquerda, "n / total" e o prazo à direita.
  void drawCaption(lgfx::LovyanGFX *dst, int ox, int oy) {
    char nm[40], right[24], shown[40];
    displayName(nm, sizeof(nm));
    snprintf(right, sizeof(right), "%d / %d  %luS", index_ + 1, cat_.count(),
             (unsigned long)(dwellMs() / 1000UL));
    // Font0 tem 6 px por caractere: o lado direito come ~14 caracteres da
    // largura segura (272 px = 45), então o nome fica com 26 e reticências.
    fitText(shown, sizeof(shown), nm, 26);
    dst->fillRect(ox + crt::SAFE_L, oy + CAPTION_Y, crt::SAFE_W, CAPTION_H, TFT_BLACK);
    dst->drawFastHLine(ox + crt::SAFE_L, oy + CAPTION_Y, crt::SAFE_W, ACCENT);
    dst->setFont(&fonts::Font0);
    dst->setTextSize(1);
    dst->setTextDatum(top_left);
    dst->setTextColor(TFT_WHITE, TFT_BLACK);
    dst->drawString(shown, ox + crt::SAFE_L + 4, oy + CAPTION_Y + 4);
    dst->setTextDatum(top_right);
    dst->setTextColor(ACCENT, TFT_BLACK);
    dst->drawString(right, ox + crt::SAFE_R - 4, oy + CAPTION_Y + 4);
  }

  // Mesma faixa de botões das outras telas. Desenhada AQUI porque a transição
  // repinta a tela toda e o que o chamador desenhasse por fora sumiria.
  void drawLegend(lgfx::LovyanGFX *dst, int ox, int oy) {
    char line[64];
    snprintf(line, sizeof(line), "[ %s ]  [ %s ]  [ %s ]", kBtnPrev, kBtnDwell, kBtnNext);
    dst->fillRect(ox, oy + crt::BAR_Y, crt::W, crt::BAR_H, TFT_NAVY);
    dst->setFont(&fonts::Font0);
    dst->setTextSize(1);
    dst->setTextDatum(middle_center);
    dst->setTextColor(ACCENT, TFT_NAVY);
    dst->drawString(line, ox + crt::W / 2, oy + crt::BAR_Y + crt::BAR_H / 2);
  }

  // Corta em `maxChars` com ".." no fim, como o truncateText do main.cpp.
  static void fitText(char *dst, size_t cap, const char *src, int maxChars) {
    if (!dst || cap == 0)
      return;
    const size_t len = strlen(src);
    if ((int)len <= maxChars || maxChars < 3) {
      snprintf(dst, cap, "%s", src);
      return;
    }
    const int keep = maxChars - 2;
    size_t n = (size_t)keep;
    if (n > cap - 3)
      n = cap - 3;
    memcpy(dst, src, n);
    dst[n] = '.';
    dst[n + 1] = '.';
    dst[n + 2] = 0;
  }

  Catalog cat_;
  const char *dir_;
  uint8_t *buf_;
  size_t bufCap_;
#if PHOTOSHOW_HAS_JPEGDEC
  JPEGDEC *jpeg_;
#endif
  int index_, dwell_;
  uint32_t deadline_;
  Result result_;
  size_t bytes_;
  int srcW_, srcH_;
  Fit fit_;
};

} // namespace photo

#pragma once
// ============================================================================
// RadioScreen — a tela do rádio pela internet do M5 RETRO TV.
//
// A especificação é curta e é a regra que decide todo o resto deste arquivo:
// **o logotipo da estação, e nada além de um relógio em hora local.** Não é uma
// tela de player. Não tem barra de progresso, não tem espectro, não tem capa,
// não tem menu. É um relógio de parede com o logotipo da rádio em cima, que por
// acaso está tocando som. Tudo que for acrescentado aqui tira dela exatamente o
// que a torna boa de deixar ligada.
//
// As duas únicas concessões são uma linha de estado (CONECTANDO / NO AR / SEM
// SINAL) e, quando o servidor manda, o nome da música num letreiro lento. Ambas
// em corpo pequeno, cinza, no rodapé — presentes para quem procurar, invisíveis
// para quem não.
//
// ---------------------------------------------------------------------------
//  Repintura parcial: por que isto não é otimização prematura
// ---------------------------------------------------------------------------
//
// A saída composta roda a ~23 quadros/s e o framebuffer do CVBS vive na SRAM.
// Repintar 320x240 uma vez por segundo, só para mudar dois dígitos, gastaria
// ciclos do core 1 e — pior — piscaria a tela inteira no tubo uma vez por
// segundo. É o mesmo motivo pelo qual o relógio do menu inicial do src/main.cpp
// redesenha só a própria faixa.
//
// Então o desenho é dividido em regiões e `tick()` repinta SÓ o que mudou:
//
//   R_LOGO    nunca, depois da primeira pintura
//   R_SEC     uma vez por segundo  (72x32 px)
//   R_HOUR    uma vez por minuto   (180x48 px)
//   R_DATE    uma vez por dia
//   R_STATUS  quando o estado da conexão muda
//   R_TICKER  um passo de caractere a cada 500 ms, e só se o título não couber
//
// `tick()` devolve a máscara das regiões repintadas e `regionRect()` dá o
// retângulo de cada uma, para quem integra saber o que sujou (útil para as
// transições do ScreenFx.h e para o espelhamento no LCD).
//
// ---------------------------------------------------------------------------
//  Restrições do tubo que este arquivo respeita
// ---------------------------------------------------------------------------
//
// * Tudo dentro de crt::SAFE_* (SafeArea.h): um CRT come ~7% de cada borda.
//   Só o fundo sangra até o limite do raster.
// * Nada de ciano saturado (TFT_CYAN / 0x07FF): na composta ele produz dot
//   crawl visível. O acento seguro do projeto é 0x96BC.
// * Texto ASCII sem acento: as fontes bitmap só têm 0x20..0x7E. O título vindo
//   do servidor já chega normalizado pelo RadioStream.h, mas esta tela
//   normaliza de novo antes de desenhar — sai mais barato do que confiar.
// * Nada de LGFX_Sprite: não há SRAM para isso (uma alocação de 5 KB já
//   derrubou o aparelho). Todo desenho vai direto no destino.
//
// A entrada de desenho é (LovyanGFX *dst, int ox, int oy), como os pintores da
// previsão do tempo: o mesmo código serve ao painel CVBS, ao LCD do Core2 e ao
// painel SDL do simulador, e o deslocamento permite usar as transições.
//
// Compila em -std=gnu++11. Todo corpo de constexpr aqui é um único return.
// ============================================================================

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "Ascii.h"
#include "SafeArea.h"
#include "UiLogic.h" // timeReached()
#include "VcrFont.h" // traz o M5GFX junto

// ---------------------------------------------------------------------------
//  Logotipo da estação (header GERADO, fora deste arquivo)
// ---------------------------------------------------------------------------
//
// O bitmap do logotipo NÃO é criado aqui: ele é gerado a partir da arte da
// própria estação e entregue em include/DiarioLogo.h. Quando esse header não
// existe, a tela cai no nome da estação em texto ASCII e continua correta.
//
// Contrato esperado de include/DiarioLogo.h (é só isto; nada mais é lido):
//
//   #pragma once
//   #include <stdint.h>
//   namespace diariologo {
//   constexpr int      WIDTH       = 176;     // <= radioui::LOGO_MAX_W (272)
//   constexpr int      HEIGHT      =  56;     // <= radioui::LOGO_MAX_H  (64)
//   constexpr bool     HAS_TRANSPARENT = true;
//   constexpr uint16_t TRANSPARENT  = 0x0000; // cor tratada como buraco
//   const uint16_t     PIXELS[WIDTH * HEIGHT] = { ... };
//   }
//
//   * PIXELS é RGB565 na ordem NATIVA do uint16_t (o mesmo formato que o
//     src/main.cpp já empurra com pushImage e lgfx::rgb565_t), linha a linha,
//     começando pelo canto superior esquerdo, sem cabeçalho e sem padding.
//   * HAS_TRANSPARENT = false para um logotipo retangular opaco; nesse caso
//     TRANSPARENT é ignorado (mas precisa existir, para o header compilar).
//   * O gerador deve EVITAR ciano saturado (0x07FF e vizinhos) na arte: na
//     saída composta essa cor glitcha. Se a arte original tiver, puxe o
//     vermelho para cima como o RCA_ACCENT do projeto faz.
//   * WIDTH/HEIGHT são constexpr int porque o tamanho do vetor depende deles.
//
// Nada além de WIDTH, HEIGHT, HAS_TRANSPARENT, TRANSPARENT e PIXELS é usado.
#if defined(__has_include)
#if __has_include("DiarioLogo.h")
#include "DiarioLogo.h"
#define RADIOUI_HAVE_LOGO 1
#endif
#endif

namespace radioui {

// ---------------------------------------------------------------------------
//  Cores
// ---------------------------------------------------------------------------

constexpr uint16_t BG = 0x000F;     // TFT_NAVY, o fundo das outras telas
constexpr uint16_t INK = 0xFFFF;    // branco: croma zero, nunca glitcha
constexpr uint16_t ACCENT = 0x96BC; // azul-claro seguro para NTSC (ver main.cpp)
constexpr uint16_t DIM = 0x8410;    // cinza médio, também sem croma
constexpr uint16_t SHADOW = 0x0000; // contorno dos glifos grandes

// ---------------------------------------------------------------------------
//  Geometria
// ---------------------------------------------------------------------------
//
// Tudo derivado de crt::SAFE_* — duas constantes descrevendo a mesma geometria
// é a armadilha 8 do AGENTS.md.
//
//   logotipo  [20, 84)   faixa de 272x64, centralizado
//   HH:MM     [96,144)   VcrFont escala 3 (36x48 por célula), 5 células = 180
//   :SS       [112,144)  VcrFont escala 2 (24x32), 3 células = 72, base alinhada
//   data      [152,168)  escala 1
//   estado    [182,198)  escala 1
//   letreiro  [202,218)  escala 1
//
// O relógio não é HH:MM:SS do mesmo tamanho porque 8 células na escala 3 dariam
// 288 px e a largura segura tem 272. Em vez de encolher tudo para a escala 2, os
// segundos descem um degrau: o dado que se lê de longe (a hora) fica o maior
// possível e a região que repinta a cada segundo fica a MENOR possível.

struct Rect {
  int16_t x, y, w, h;
};

constexpr int LOGO_MAX_W = crt::SAFE_W; // 272
constexpr int LOGO_MAX_H = 64;

constexpr int HOUR_SCALE = 3;
constexpr int SEC_SCALE = 2;
constexpr int SMALL_SCALE = 1;

constexpr int HOUR_W = 5 * vcrfont::CELL_W * HOUR_SCALE; // "HH:MM" = 180
constexpr int SEC_W = 3 * vcrfont::CELL_W * SEC_SCALE;   // ":SS"   =  72
constexpr int CLOCK_GAP = 8;
constexpr int CLOCK_W = HOUR_W + CLOCK_GAP + SEC_W; // 260
constexpr int CLOCK_X = crt::SAFE_L + (crt::SAFE_W - CLOCK_W) / 2; // 30
constexpr int CLOCK_Y = 96;
constexpr int HOUR_H = vcrfont::CELL_H * HOUR_SCALE; // 48
constexpr int SEC_H = vcrfont::CELL_H * SEC_SCALE;   // 32

constexpr Rect LOGO_RECT = {(int16_t)crt::SAFE_L, (int16_t)(crt::SAFE_T + 2), (int16_t)LOGO_MAX_W,
                            (int16_t)LOGO_MAX_H};
constexpr Rect HOUR_RECT = {(int16_t)CLOCK_X, (int16_t)CLOCK_Y, (int16_t)HOUR_W, (int16_t)HOUR_H};
// Base alinhada com a da hora: CLOCK_Y + HOUR_H - SEC_H.
constexpr Rect SEC_RECT = {(int16_t)(CLOCK_X + HOUR_W + CLOCK_GAP), (int16_t)(CLOCK_Y + HOUR_H - SEC_H),
                           (int16_t)SEC_W, (int16_t)SEC_H};
constexpr Rect DATE_RECT = {(int16_t)crt::SAFE_L, 152, (int16_t)crt::SAFE_W, 16};
constexpr Rect STATUS_RECT = {(int16_t)crt::SAFE_L, 182, (int16_t)crt::SAFE_W, 16};
constexpr Rect TICKER_RECT = {(int16_t)crt::SAFE_L, 202, (int16_t)crt::SAFE_W, 16};

// Quantos caracteres cabem no letreiro (escala 1 = 12 px por célula).
constexpr int TICKER_COLS = crt::SAFE_W / vcrfont::CELL_W; // 22

// Um passo de caractere a cada 500 ms. Lento de propósito: o ponto da tela é o
// relógio, e um letreiro rápido rouba o olho.
constexpr uint32_t TICKER_STEP_MS = 500;

// ---------------------------------------------------------------------------
//  Regiões
// ---------------------------------------------------------------------------

enum Region : uint8_t {
  R_NONE = 0,
  R_LOGO = 1 << 0,
  R_HOUR = 1 << 1,
  R_SEC = 1 << 2,
  R_DATE = 1 << 3,
  R_STATUS = 1 << 4,
  R_TICKER = 1 << 5,
  R_ALL = 0x3F
};

inline Rect regionRect(uint8_t bit) {
  return bit == R_LOGO     ? LOGO_RECT
         : bit == R_HOUR   ? HOUR_RECT
         : bit == R_SEC    ? SEC_RECT
         : bit == R_DATE   ? DATE_RECT
         : bit == R_STATUS ? STATUS_RECT
         : bit == R_TICKER ? TICKER_RECT
                           : Rect{0, 0, 0, 0};
}

// ---------------------------------------------------------------------------
//  Estado exibido
// ---------------------------------------------------------------------------
//
// Struct burra de propósito: esta tela não sabe o que é Wi-Fi, socket ou NTP.
// Quem integra preenche e chama. É o que permite ao probe desenhar qualquer
// combinação sem simular nada.
struct State {
  uint8_t hour = 0, minute = 0, second = 0; // hora LOCAL já resolvida
  uint8_t day = 1, month = 1;
  uint16_t year = 2026;
  uint8_t weekday = 0;       // 0 = domingo ... 6 = sábado
  bool timeValid = false;    // false -> desenha --:-- / --
  const char *stationName = "";  // usado só quando não há DiarioLogo.h
  const char *statusText = "";    // radio::connLabel(): "NO AR", "CONECTANDO"...
  const char *title = "";         // StreamTitle; "" quando não houver
};

// Abreviações pt-BR em ASCII (AGENTS.md 2.7: as fontes não têm acento).
inline const char *weekdayName(uint8_t w) {
  static const char *const N[7] = {"DOM", "SEG", "TER", "QUA", "QUI", "SEX", "SAB"};
  return N[w < 7 ? w : 0];
}
inline const char *monthName(uint8_t m) {
  static const char *const N[12] = {"JAN", "FEV", "MAR", "ABR", "MAI", "JUN",
                                    "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"};
  return N[(m >= 1 && m <= 12) ? m - 1 : 0];
}

// ---------------------------------------------------------------------------
//  Cache da repintura parcial
// ---------------------------------------------------------------------------
//
// Mora no CHAMADOR, não em `static` de função. A armadilha 6 do AGENTS.md é
// exatamente estado estático herdado da visita anterior a uma tela — aqui basta
// zerar o Cache ao entrar (cacheReset) e o problema não existe.
struct Cache {
  bool painted = false;
  uint8_t hour = 255, minute = 255, second = 255;
  uint8_t day = 255, month = 255;
  uint16_t year = 0;
  bool timeValid = false;
  char status[16] = {0};
  uint32_t titleHash = 0;
  int16_t titleLen = 0;
  int16_t tickerPos = 0;
  uint32_t tickerAt = 0;
};

inline void cacheReset(Cache &c) {
  c = Cache();
}

namespace detail {

// FNV-1a de 32 bits. Só serve para detectar "o título mudou"; colisão aqui
// custa um letreiro desatualizado até a próxima música, não um bug.
inline uint32_t hashStr(const char *s) {
  uint32_t h = 2166136261u;
  for (; s && *s; ++s)
    h = (h ^ (uint8_t)*s) * 16777619u;
  return h;
}

inline void clearRect(LovyanGFX *dst, int ox, int oy, const Rect &r) {
  dst->fillRect(ox + r.x, oy + r.y, r.w, r.h, BG);
}

// Duas casas, ou "--" quando o relógio ainda não foi sincronizado.
inline void two(char *dst, int v, bool valid) {
  if (valid)
    snprintf(dst, 3, "%02d", v % 100);
  else {
    dst[0] = '-';
    dst[1] = '-';
    dst[2] = 0;
  }
}

} // namespace detail

// ---------------------------------------------------------------------------
//  Pintores
// ---------------------------------------------------------------------------

// O fundo sangra até a borda do raster: sem tarja preta em volta, senão a
// imagem parece pequena no tubo (AGENTS.md 2.5).
inline void drawBackground(LovyanGFX *dst, int ox, int oy) {
  if (!dst)
    return;
  dst->fillRect(ox, oy, crt::W, crt::H, BG);
}

// Logotipo, ou o nome da estação em texto quando não há o header gerado.
inline void drawLogo(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, LOGO_RECT);
#ifdef RADIOUI_HAVE_LOGO
  const int w = diariologo::WIDTH <= LOGO_MAX_W ? diariologo::WIDTH : LOGO_MAX_W;
  const int h = diariologo::HEIGHT <= LOGO_MAX_H ? diariologo::HEIGHT : LOGO_MAX_H;
  const int x = ox + LOGO_RECT.x + (LOGO_RECT.w - w) / 2;
  const int y = oy + LOGO_RECT.y + (LOGO_RECT.h - h) / 2;
  const lgfx::rgb565_t *px = reinterpret_cast<const lgfx::rgb565_t *>(diariologo::PIXELS);
  if (diariologo::HAS_TRANSPARENT)
    dst->pushImage(x, y, w, h, px, lgfx::rgb565_t(diariologo::TRANSPARENT));
  else
    dst->pushImage(x, y, w, h, px);
#else
  // Sem logotipo: o nome da estação em corpo grosso, centralizado na faixa.
  // Normaliza mesmo vindo de constante — é barato e fecha o caminho.
  char name[24];
  ascii::normalizeUpper(name, sizeof(name), s.stationName && *s.stationName ? s.stationName : "RADIO");
  const int y = LOGO_RECT.y + (LOGO_RECT.h - vcrfont::textHeight(2)) / 2;
  vcrfont::drawTextCentered(dst, name, ox + LOGO_RECT.x, oy + y, LOGO_RECT.w, ACCENT, 2);
#endif
}

// HH:MM. Contorno preto por glifo: no tubo o branco puro sobre azul "sangra" e
// o contorno devolve a borda (é a mesma técnica do OSD do player).
inline void drawHour(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, HOUR_RECT);
  char buf[8];
  detail::two(buf, s.hour, s.timeValid);
  buf[2] = ':';
  detail::two(buf + 3, s.minute, s.timeValid);
  vcrfont::drawText(dst, buf, ox + HOUR_RECT.x, oy + HOUR_RECT.y, INK, HOUR_SCALE, SHADOW);
}

// :SS — a única região que repinta uma vez por segundo, e a menor de todas.
inline void drawSeconds(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, SEC_RECT);
  char buf[8];
  buf[0] = ':';
  detail::two(buf + 1, s.second, s.timeValid);
  vcrfont::drawText(dst, buf, ox + SEC_RECT.x, oy + SEC_RECT.y, ACCENT, SEC_SCALE, SHADOW);
}

inline void drawDate(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, DATE_RECT);
  char buf[24];
  if (s.timeValid)
    snprintf(buf, sizeof(buf), "%s %02u %s %04u", weekdayName(s.weekday), (unsigned)s.day,
             monthName(s.month), (unsigned)s.year);
  else
    snprintf(buf, sizeof(buf), "--- -- --- ----");
  vcrfont::drawTextCentered(dst, buf, ox + DATE_RECT.x, oy + DATE_RECT.y, DATE_RECT.w, DIM, SMALL_SCALE);
}

// Linha de estado. "NO AR" ganha o acento; o resto fica cinza, para que a tela
// no ar não tenha nada competindo com o relógio.
inline void drawStatus(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, STATUS_RECT);
  char buf[20];
  ascii::normalizeUpper(buf, sizeof(buf), s.statusText ? s.statusText : "");
  if (!buf[0])
    return;
  const uint16_t color = strcmp(buf, "NO AR") == 0 ? ACCENT : DIM;
  vcrfont::drawTextCentered(dst, buf, ox + STATUS_RECT.x, oy + STATUS_RECT.y, STATUS_RECT.w, color,
                            SMALL_SCALE);
}

// Janela de TICKER_COLS caracteres do título, começando em `pos`.
//
// Quando o título cabe, `pos` é ignorado e o texto sai centralizado e parado —
// um letreiro que rola sem precisar é só ruído.
inline void tickerWindow(const char *title, int pos, char *dst, size_t cap) {
  char norm[160];
  ascii::normalizeUpper(norm, sizeof(norm), title ? title : "");
  const int n = (int)strlen(norm);
  if (n <= TICKER_COLS) {
    strncpy(dst, norm, cap - 1);
    dst[cap - 1] = 0;
    return;
  }
  // Separador entre o fim e o recomeço, para não emendar palavra com palavra.
  static const char SEP[] = "   ---   ";
  const int sep = (int)sizeof(SEP) - 1;
  const int period = n + sep;
  int p = pos % period;
  if (p < 0)
    p += period;
  size_t j = 0;
  for (int k = 0; k < TICKER_COLS && j + 1 < cap; ++k) {
    const int idx = (p + k) % period;
    dst[j++] = idx < n ? norm[idx] : SEP[idx - n];
  }
  dst[j] = 0;
}

inline void drawTicker(LovyanGFX *dst, int ox, int oy, const State &s, int pos) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, TICKER_RECT);
  if (!s.title || !*s.title)
    return;
  char win[TICKER_COLS + 2];
  tickerWindow(s.title, pos, win, sizeof(win));
  vcrfont::drawTextCentered(dst, win, ox + TICKER_RECT.x, oy + TICKER_RECT.y, TICKER_RECT.w, DIM,
                            SMALL_SCALE);
}

// Repintura completa. É o que as transições do ScreenFx.h chamam e o que
// `tick()` faz na primeira vez.
inline void draw(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  dst->startWrite();
  drawBackground(dst, ox, oy);
  drawLogo(dst, ox, oy, s);
  drawHour(dst, ox, oy, s);
  drawSeconds(dst, ox, oy, s);
  drawDate(dst, ox, oy, s);
  drawStatus(dst, ox, oy, s);
  drawTicker(dst, ox, oy, s, 0);
  dst->endWrite();
}

// ---------------------------------------------------------------------------
//  Repintura incremental
// ---------------------------------------------------------------------------

// Repinta só o que mudou e devolve a máscara das regiões sujas (0 = nada
// mudou, e nesse caso NADA foi escrito no destino).
//
// `nowMs` é o millis() do chamador e só serve ao passo do letreiro. A
// comparação usa timeReached() porque o millis() dá a volta em ~49 dias — e
// `nowMs > c.tickerAt` cru é justamente o que a AGENTS.md 3.3 proíbe.
inline uint8_t tick(LovyanGFX *dst, int ox, int oy, const State &s, Cache &c, uint32_t nowMs) {
  if (!dst)
    return R_NONE;
  if (!c.painted) {
    draw(dst, ox, oy, s);
    c.painted = true;
    c.hour = s.hour;
    c.minute = s.minute;
    c.second = s.second;
    c.day = s.day;
    c.month = s.month;
    c.year = s.year;
    c.timeValid = s.timeValid;
    ascii::normalizeUpper(c.status, sizeof(c.status), s.statusText ? s.statusText : "");
    c.titleHash = detail::hashStr(s.title);
    c.titleLen = (int16_t)(s.title ? strlen(s.title) : 0);
    c.tickerPos = 0;
    c.tickerAt = nowMs + TICKER_STEP_MS;
    return R_ALL;
  }

  uint8_t dirty = R_NONE;
  const bool validChanged = (c.timeValid != s.timeValid);

  dst->startWrite();

  if (validChanged || c.second != s.second) {
    drawSeconds(dst, ox, oy, s);
    c.second = s.second;
    dirty |= R_SEC;
  }
  if (validChanged || c.minute != s.minute || c.hour != s.hour) {
    drawHour(dst, ox, oy, s);
    c.hour = s.hour;
    c.minute = s.minute;
    dirty |= R_HOUR;
  }
  if (validChanged || c.day != s.day || c.month != s.month || c.year != s.year) {
    drawDate(dst, ox, oy, s);
    c.day = s.day;
    c.month = s.month;
    c.year = s.year;
    dirty |= R_DATE;
  }
  c.timeValid = s.timeValid;

  char status[16];
  ascii::normalizeUpper(status, sizeof(status), s.statusText ? s.statusText : "");
  if (strcmp(status, c.status) != 0) {
    drawStatus(dst, ox, oy, s);
    memcpy(c.status, status, sizeof(status));
    dirty |= R_STATUS;
  }

  const uint32_t h = detail::hashStr(s.title);
  if (h != c.titleHash) {
    // Música nova: o letreiro recomeça do início, senão a primeira volta
    // entraria pelo meio do título.
    c.titleHash = h;
    c.titleLen = (int16_t)(s.title ? strlen(s.title) : 0);
    c.tickerPos = 0;
    c.tickerAt = nowMs + TICKER_STEP_MS;
    drawTicker(dst, ox, oy, s, 0);
    dirty |= R_TICKER;
  } else if (c.titleLen > TICKER_COLS && timeReached(nowMs, c.tickerAt)) {
    ++c.tickerPos;
    c.tickerAt = nowMs + TICKER_STEP_MS;
    drawTicker(dst, ox, oy, s, c.tickerPos);
    dirty |= R_TICKER;
  }

  dst->endWrite();
  return dirty;
}

} // namespace radioui

#pragma once
// ============================================================================
// RadioStream — cliente de rádio pela internet (Icecast/Shoutcast) do M5 RETRO TV.
//
// Entrega PCM 22050 Hz estéreo pelo MESMO contrato do mp3ReadPcm() do
// src/main.cpp, para que a tarefa de áudio (RCA_PCM, core 0) não precise de um
// segundo caminho de saída: quem integra troca a fonte do bloco e o resto do
// audioTask — escala de volume, i2s_write, ritmo pelo relógio de amostras —
// continua igual.
//
// ---------------------------------------------------------------------------
//  Por que cada decisão deste arquivo é assim
// ---------------------------------------------------------------------------
//
// 1. WiFiClient, NUNCA WiFiClientSecure. A estação é HTTP puro. Um cliente TLS
//    custa dezenas de KB de SRAM (buffers de record de 16 KB + contexto do
//    mbedTLS) e a SRAM é o recurso escasso deste aparelho: o framebuffer do
//    CVBS já leva 153.600 B e o mínimo de heap livre medido aqui foi de 28 a
//    38 KB. Uma alocação de 5 KB de sprite já causou falta de memória dura.
//
// 2. O buffer circular mora na PSRAM. São ~3,8 MB livres lá contra dezenas de
//    KB na SRAM. Ele é o ÚNICO bloco grande deste módulo e é alocado com
//    heap_caps_malloc(MALLOC_CAP_SPIRAM); se a alocação falhar o módulo entra
//    em Conn::NoMemory e NÃO tenta a SRAM — cair de pé é melhor do que derrubar
//    o aparelho inteiro.
//
// 3. O de-interleave do icy-metaint acontece ANTES do buffer circular. O que
//    entra no anel é fluxo MP3 puro; o decodificador nunca vê um byte de
//    metadado. Se o bloco de metadado fosse para o anel, o libhelix perderia o
//    sync e o áudio viraria estalo a cada ~8 segundos.
//
// 4. Reconexão com backoff exponencial (1, 2, 4, 8, 16, 30 s). A armadilha 4 do
//    AGENTS.md — "retentativa sem backoff" — já mordeu este projeto: um portão
//    que só avançava no sucesso virava laço apertado criando tarefas HTTP
//    quando a rede caía.
//
// 5. A leitura da rede roda numa tarefa própria PINADA NO CORE 0
//    (xTaskCreatePinnedToCore(..., 8192, ..., 0, nullptr, 1)), como as tarefas
//    WEATHER_HTTP e RADAR_HTTPS. O core 1 é do loop() e do desenho; um
//    client.read() bloqueante lá dentro travaria o raster. Duas tarefas já
//    estouraram 8 KB de pilha neste repositório (armadilha 2), então aqui o
//    maior local da tarefa tem 512 bytes e todo o resto é estado da classe.
//
// 6. A lógica pura (parse de URL, parse de cabeçalho, de-interleave, parse do
//    StreamTitle, backoff) vive fora do #if defined(ARDUINO) e não depende de
//    Arduino, WiFi nem FreeRTOS. É isso que permite testá-la nativamente em
//    sim/probes/radio_stream.cpp com g++ -std=gnu++11.
//
// Compila em -std=gnu++11 (arduino-esp32 2.x): todo corpo de constexpr aqui é
// um único return, sem laço e sem variável local (armadilha 1 do AGENTS.md).
// ============================================================================

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include <atomic>

#include "Ascii.h"   // normalização para ASCII: as fontes bitmap só têm ASCII
#include "UiLogic.h" // timeReached(): millis() dá a volta em ~49 dias

namespace radio {

// ---------------------------------------------------------------------------
//  Tabela de estações (tempo de compilação)
// ---------------------------------------------------------------------------
//
// Uma entrada hoje. A tabela existe desde já para que acrescentar estação seja
// acrescentar uma linha, e não reestruturar o módulo: STATION_COUNT vem do
// sizeof, então nada mais precisa ser tocado.

struct Station {
  const char *name; // rótulo curto, ASCII, para a tela quando não houver logo
  const char *url;  // http:// apenas — ver a nota 1 no cabeçalho
};

constexpr Station STATIONS[] = {
    {"DIARIO FM", "http://51-222-26-208.webnow.com.br/diario.mp3"},
};

constexpr int STATION_COUNT = (int)(sizeof(STATIONS) / sizeof(STATIONS[0]));

// ---------------------------------------------------------------------------
//  Estado da conexão
// ---------------------------------------------------------------------------
//
// O pré-buffer conta como CONECTANDO de propósito: para quem está na frente da
// TV, "NO AR" tem que significar "já está saindo som", não "o socket abriu".

enum class Conn : uint8_t {
  Idle,       // módulo parado
  Connecting, // resolvendo/conectando/lendo cabeçalho/enchendo o pré-buffer
  OnAir,      // áudio saindo
  NoSignal,   // caiu ou recusou; esperando o backoff
  NoMemory    // PSRAM ou decodificador indisponível — não adianta tentar de novo
};

// Rótulos ASCII sem acento (AGENTS.md 2.7): as fontes bitmap só têm 0x20..0x7E.
inline const char *connLabel(Conn c) {
  return c == Conn::OnAir        ? "NO AR"
         : c == Conn::Connecting ? "CONECTANDO"
         : c == Conn::NoSignal   ? "SEM SINAL"
         : c == Conn::NoMemory   ? "SEM MEMORIA"
                                 : "PARADO";
}

// ---------------------------------------------------------------------------
//  Dimensionamento (ver o relatório de orçamento de memória no README do módulo)
// ---------------------------------------------------------------------------

// 96 kbps = 12.000 bytes/s. 64 KiB = 5,46 s de áudio.
//
// Por que 64 KiB e não mais nem menos: a rede Wi-Fi entrega em rajada e o
// aparelho ainda perde alguns milissegundos por varredura de canal e por
// retransmissão TCP. Meio segundo de anel não sobrevive a isso; 5,5 s
// sobrevivem com folga a uma pausa de rede completa. Mais do que isso só
// aumentaria a latência entre trocar de estação e ouvir som — e a PSRAM,
// apesar de sobrar, é lenta, então não há motivo para exagerar.
constexpr size_t RING_BYTES = 65536;

// Espelha o mp3In[4096] do src/main.cpp: mesma janela de entrada do libhelix.
constexpr size_t MP3_IN_BYTES = 4096;

// Espelha o mp3FramePcm[2304] do src/main.cpp: um frame MPEG1 estéreo (1152x2).
constexpr size_t MP3_PCM_SHORTS = 2304;

// Tudo numa alocação só: um caminho de falha em vez de três.
constexpr size_t PSRAM_BYTES = RING_BYTES + MP3_IN_BYTES + MP3_PCM_SHORTS * 2;

// Só declara OnAir depois de 2 s de áudio no anel. Evita o pior sintoma de
// rádio na internet: começar a tocar e engasgar três segundos depois.
constexpr size_t PREBUFFER_BYTES = 24576;

// Saída fixa do aparelho: o I2S1 é aberto a 22050 Hz estéreo pelo
// initExternalAudio() do src/main.cpp. O resampler linear abaixo leva qualquer
// taxa de origem (44100 na prática, mas lida do primeiro frame) para cá.
constexpr int OUT_RATE = 22050;

// ---------------------------------------------------------------------------
//  Backoff
// ---------------------------------------------------------------------------

constexpr uint32_t BACKOFF_MIN_MS = 1000;
constexpr uint32_t BACKOFF_MAX_MS = 30000;

// 1 s, 2, 4, 8, 16, depois 30 s para sempre. Determinístico de propósito: dá
// para testar (sim/probes/radio_stream.cpp) e, com uma estação só, não há
// rebanho de clientes para dispersar com jitter.
//
// C++11: corpo de constexpr é um único return, sem laço e sem local.
constexpr uint32_t backoffDelayMs(uint32_t attempt) {
  return attempt >= 5 ? BACKOFF_MAX_MS : (BACKOFF_MIN_MS << attempt);
}

// ---------------------------------------------------------------------------
//  Parse da URL
// ---------------------------------------------------------------------------

struct Url {
  char host[80];
  char path[144];
  uint16_t port;
};

// Aceita "http://host[:porta][/caminho]". Recusa https:// de propósito: este
// módulo não abre TLS (ver nota 1). Caminho vazio vira "/".
inline bool parseUrl(const char *url, Url &out) {
  out.host[0] = 0;
  out.path[0] = 0;
  out.port = 80;
  if (!url)
    return false;
  const char *p = url;
  if (strncmp(p, "http://", 7) == 0)
    p += 7;
  else if (strncmp(p, "https://", 8) == 0)
    return false; // sem TLS aqui
  else if (strstr(url, "://"))
    return false; // esquema desconhecido
  // Authority vai até '/', '?' ou fim.
  size_t h = 0;
  for (; *p && *p != '/' && *p != '?'; ++p) {
    if (*p == ':') {
      ++p;
      uint32_t v = 0;
      for (; *p >= '0' && *p <= '9'; ++p)
        v = v * 10 + (uint32_t)(*p - '0');
      if (!v || v > 65535)
        return false;
      out.port = (uint16_t)v;
      break;
    }
    if (h + 1 < sizeof(out.host))
      out.host[h++] = *p;
  }
  out.host[h] = 0;
  if (!h)
    return false;
  // Resto é o caminho (com query, se houver).
  while (*p && *p != '/' && *p != '?')
    ++p;
  size_t j = 0;
  if (*p != '/' && j + 1 < sizeof(out.path))
    out.path[j++] = '/';
  for (; *p && j + 1 < sizeof(out.path); ++p)
    out.path[j++] = *p;
  out.path[j] = 0;
  if (!j) {
    out.path[0] = '/';
    out.path[1] = 0;
  }
  return true;
}

// ---------------------------------------------------------------------------
//  Parse do cabeçalho de resposta
// ---------------------------------------------------------------------------

struct IcyInfo {
  int32_t status;  // código HTTP da linha de status; 0 se não lido
  int32_t metaint; // -1 quando o servidor não manda icy-metaint
  char name[40];   // icy-name  (ex.: "DIARIO FM")
  char desc[80];   // icy-description, quando houver
  bool audio;      // Content-Type é audio/mpeg (ou mp3)
};

inline void icyInfoInit(IcyInfo &i) {
  i.status = 0;
  i.metaint = -1;
  i.name[0] = 0;
  i.desc[0] = 0;
  i.audio = false;
}

namespace detail {

inline bool iEqPrefix(const char *s, const char *prefix) {
  for (size_t i = 0; prefix[i]; ++i) {
    const char a = s[i] >= 'A' && s[i] <= 'Z' ? (char)(s[i] + 32) : s[i];
    const char b = prefix[i] >= 'A' && prefix[i] <= 'Z' ? (char)(prefix[i] + 32) : prefix[i];
    if (!s[i] || a != b)
      return false;
  }
  return true;
}

inline const char *skipSpace(const char *s) {
  while (*s == ' ' || *s == '\t')
    ++s;
  return s;
}

// Copia já normalizado para ASCII: icy-name e icy-description vêm de fora e o
// AGENTS.md 2.7 exige normalizar tudo que venha de fora antes de desenhar.
inline void copyAscii(char *dst, size_t cap, const char *src) {
  ascii::normalize(dst, cap, src);
}

} // namespace detail

// Interpreta UMA linha de cabeçalho já sem o CRLF. Chamada pelo HeaderParser,
// exposta porque é o que o probe exercita diretamente.
inline void parseHeaderLine(const char *line, IcyInfo &out) {
  if (!line || !*line)
    return;
  if (detail::iEqPrefix(line, "HTTP/") || detail::iEqPrefix(line, "ICY ")) {
    // "HTTP/1.1 200 OK" ou "ICY 200 OK" (Shoutcast antigo).
    const char *p = line;
    while (*p && *p != ' ')
      ++p;
    p = detail::skipSpace(p);
    int32_t v = 0;
    while (*p >= '0' && *p <= '9')
      v = v * 10 + (*p++ - '0');
    out.status = v;
    return;
  }
  const char *colon = strchr(line, ':');
  if (!colon)
    return;
  const char *value = detail::skipSpace(colon + 1);
  if (detail::iEqPrefix(line, "icy-metaint:")) {
    int32_t v = 0;
    for (const char *p = value; *p >= '0' && *p <= '9'; ++p)
      v = v * 10 + (*p - '0');
    // metaint zero ou absurdo é tratado como "sem metadado": melhor perder o
    // título do que picotar o fluxo MP3 num intervalo errado.
    out.metaint = (v > 0 && v <= 1024 * 1024) ? v : -1;
  } else if (detail::iEqPrefix(line, "icy-name:")) {
    detail::copyAscii(out.name, sizeof(out.name), value);
  } else if (detail::iEqPrefix(line, "icy-description:")) {
    detail::copyAscii(out.desc, sizeof(out.desc), value);
  } else if (detail::iEqPrefix(line, "content-type:")) {
    out.audio = detail::iEqPrefix(value, "audio/mpeg") || detail::iEqPrefix(value, "audio/mp3") ||
                detail::iEqPrefix(value, "application/octet-stream");
  }
}

// Consome bytes do socket até o fim do cabeçalho (CRLF CRLF ou LF LF).
//
// Trabalha byte a byte porque o cabeçalho e o áudio chegam no MESMO read(): a
// função precisa devolver exatamente quantos bytes eram do cabeçalho para que
// o primeiro byte de áudio não seja perdido nem contado errado no metaint.
class HeaderParser {
public:
  void reset() {
    len_ = 0;
    done_ = false;
    ok_ = false;
    icyInfoInit(info_);
  }

  // Devolve quantos bytes de `data` pertenciam ao cabeçalho. Se done(), o resto
  // (n - consumidos) já é o corpo e deve ir para o de-interleaver.
  size_t feed(const uint8_t *data, size_t n) {
    size_t i = 0;
    for (; i < n && !done_; ++i) {
      const char c = (char)data[i];
      if (c == '\r')
        continue; // CR é ignorado: trata CRLF e LF do mesmo jeito
      if (c != '\n') {
        if (len_ + 1 < sizeof(line_))
          line_[len_++] = c;
        continue;
      }
      line_[len_] = 0;
      if (!len_) {
        // Linha vazia: fim do cabeçalho.
        done_ = true;
        ok_ = (info_.status == 200) && info_.audio;
        ++i;
        break;
      }
      parseHeaderLine(line_, info_);
      len_ = 0;
    }
    return i;
  }

  bool done() const { return done_; }
  bool ok() const { return ok_; }
  const IcyInfo &info() const { return info_; }

private:
  // 200 bytes: cabe icy-url, icy-genre e afins. Uma linha mais longa é truncada
  // — o que se perde é o fim do valor, nunca o sincronismo do fluxo, porque o
  // corte é só na cópia e o byte continua sendo consumido.
  char line_[200];
  uint16_t len_ = 0;
  bool done_ = false;
  bool ok_ = false;
  IcyInfo info_;
};

// ---------------------------------------------------------------------------
//  StreamTitle
// ---------------------------------------------------------------------------

// Extrai o valor de StreamTitle='...'; de um bloco de metadados ICY.
//
// A regra do Icecast/Shoutcast é que o valor termina na sequência "';" — aspa
// simples SEGUIDA de ponto-e-vírgula. Uma aspa solta no meio é conteúdo, e é
// comum ("ROCK N' ROLL"). Cortar na primeira aspa truncaria esses títulos.
// Servidores que omitem o ';' final também existem: aí vale até o fim.
//
// Escreve em `dst` já normalizado para ASCII. Devolve true se achou o campo.
inline bool parseStreamTitle(const char *meta, char *dst, size_t cap) {
  if (!dst || !cap)
    return false;
  dst[0] = 0;
  if (!meta)
    return false;
  const char *k = strstr(meta, "StreamTitle='");
  if (!k)
    return false;
  const char *v = k + 13; // strlen("StreamTitle='")
  const char *e = strstr(v, "';");
  size_t n;
  if (e) {
    n = (size_t)(e - v);
  } else {
    // Sem o ';' final o valor vale ate o fim -- mas a aspa que FECHA o campo
    // ainda esta la e nao faz parte do titulo. Sem esta poda, um servidor que
    // manda StreamTitle='FULANO' sem ponto e virgula deixava a aspa sobrando
    // na tela. So a ultima e podada: uma aspa no meio e conteudo ("ROCK N'
    // ROLL") e continua intacta.
    n = strlen(v);
    if (n && v[n - 1] == '\'')
      --n;
  }
  // Buffer temporário pequeno e limitado: o título vive num campo de tela, não
  // faz sentido guardar mais do que cabe nele.
  char raw[160];
  if (n >= sizeof(raw))
    n = sizeof(raw) - 1;
  memcpy(raw, v, n);
  raw[n] = 0;
  ascii::normalize(dst, cap, raw);
  return true;
}

// ---------------------------------------------------------------------------
//  De-interleave do icy-metaint
// ---------------------------------------------------------------------------

// O servidor intercala, a cada `metaint` bytes de áudio, um bloco de metadado:
// um byte de comprimento (em unidades de 16 bytes) seguido de len*16 bytes de
// texto. Comprimento zero — o caso mais comum — significa "nada mudou".
//
// Esta máquina de estados devolve SÓ os bytes de áudio, contíguos, e não se
// importa com onde a leitura do socket cortou: um bloco de metadado partido
// entre duas leituras é retomado no ponto exato.
//
// `out` PODE ser o mesmo ponteiro que `in`: os bytes de áudio só andam para a
// esquerda, então a cópia in-place é segura e é o que a tarefa de rede usa para
// gastar 256 bytes de pilha em vez de 512.
class MetaSplitter {
public:
  void begin(int32_t metaint) {
    metaint_ = metaint;
    audioLeft_ = metaint > 0 ? (uint32_t)metaint : 0;
    stage_ = metaint > 0 ? Stage::Audio : Stage::Passthrough;
    metaLeft_ = 0;
    bufLen_ = 0;
    blocks_ = 0;
    titleNew_ = false;
    title_[0] = 0;
  }

  size_t split(const uint8_t *in, size_t n, uint8_t *out) {
    size_t w = 0, i = 0;
    if (stage_ == Stage::Passthrough) {
      if (out != in)
        memmove(out, in, n);
      return n;
    }
    while (i < n) {
      if (stage_ == Stage::Audio) {
        size_t k = n - i;
        if (k > audioLeft_)
          k = audioLeft_;
        if (k) {
          memmove(out + w, in + i, k);
          w += k;
          i += k;
          audioLeft_ -= (uint32_t)k;
        }
        if (!audioLeft_)
          stage_ = Stage::Length;
        continue;
      }
      if (stage_ == Stage::Length) {
        metaLeft_ = (uint32_t)in[i++] * 16u;
        bufLen_ = 0;
        ++blocks_;
        if (!metaLeft_)
          rearm();
        else
          stage_ = Stage::Meta;
        continue;
      }
      // Stage::Meta
      size_t k = n - i;
      if (k > metaLeft_)
        k = metaLeft_;
      for (size_t j = 0; j < k; ++j) {
        // Guarda só o começo do bloco. Um bloco ICY pode ter até 4080 bytes,
        // mas o StreamTitle vem primeiro e um título maior que isto não cabe na
        // tela de qualquer jeito. O RESTO CONTINUA SENDO CONSUMIDO — é isso que
        // mantém o de-interleave correto sem gastar 4 KB de SRAM.
        if (bufLen_ + 1 < sizeof(buf_))
          buf_[bufLen_++] = (char)in[i + j];
      }
      i += k;
      metaLeft_ -= (uint32_t)k;
      if (!metaLeft_) {
        buf_[bufLen_] = 0;
        char t[128];
        if (parseStreamTitle(buf_, t, sizeof(t))) {
          if (strcmp(t, title_) != 0) {
            memcpy(title_, t, sizeof(t));
            titleNew_ = true;
          }
        }
        rearm();
      }
    }
    return w;
  }

  const char *title() const { return title_; }
  bool takeTitleFlag() {
    const bool v = titleNew_;
    titleNew_ = false;
    return v;
  }
  uint32_t blocks() const { return blocks_; }
  int32_t metaint() const { return metaint_; }

private:
  enum class Stage : uint8_t { Passthrough, Audio, Length, Meta };

  void rearm() {
    audioLeft_ = (uint32_t)metaint_;
    stage_ = Stage::Audio;
  }

  int32_t metaint_ = -1;
  uint32_t audioLeft_ = 0;
  uint32_t metaLeft_ = 0;
  uint32_t blocks_ = 0;
  Stage stage_ = Stage::Passthrough;
  bool titleNew_ = false;
  uint16_t bufLen_ = 0;
  char buf_[224];  // janela de captura do bloco de metadado
  char title_[128]; // já normalizado para ASCII
};

// ---------------------------------------------------------------------------
//  Anel produtor-consumidor (um escritor, um leitor)
// ---------------------------------------------------------------------------
//
// A tarefa de rede (core 0) escreve; a tarefa de áudio (core 0) lê. Um índice
// por lado, cada um escrito por um único dono: não precisa de mutex, e não usar
// mutex aqui é de propósito — o áudio não pode nunca ficar esperando a rede.
class Ring {
public:
  void attach(uint8_t *mem, size_t size) {
    buf_ = mem;
    size_ = size;
    clear();
  }
  void clear() {
    head_.store(0, std::memory_order_relaxed);
    tail_.store(0, std::memory_order_relaxed);
  }
  size_t capacity() const { return size_; }
  size_t used() const {
    const size_t h = head_.load(std::memory_order_acquire);
    const size_t t = tail_.load(std::memory_order_acquire);
    return h >= t ? h - t : size_ - (t - h);
  }
  // Uma posição fica sempre vaga para distinguir cheio de vazio.
  size_t space() const { return size_ ? size_ - used() - 1 : 0; }

  size_t write(const uint8_t *src, size_t n) {
    if (!buf_)
      return 0;
    size_t free = space();
    if (n > free)
      n = free;
    size_t h = head_.load(std::memory_order_relaxed);
    const size_t first = (h + n <= size_) ? n : size_ - h;
    memcpy(buf_ + h, src, first);
    if (n > first)
      memcpy(buf_, src + first, n - first);
    h += n;
    if (h >= size_)
      h -= size_;
    head_.store(h, std::memory_order_release);
    return n;
  }

  size_t read(uint8_t *dst, size_t n) {
    if (!buf_)
      return 0;
    size_t avail = used();
    if (n > avail)
      n = avail;
    size_t t = tail_.load(std::memory_order_relaxed);
    const size_t first = (t + n <= size_) ? n : size_ - t;
    memcpy(dst, buf_ + t, first);
    if (n > first)
      memcpy(dst + first, buf_, n - first);
    t += n;
    if (t >= size_)
      t -= size_;
    tail_.store(t, std::memory_order_release);
    return n;
  }

private:
  uint8_t *buf_ = nullptr;
  size_t size_ = 0;
  std::atomic<size_t> head_;
  std::atomic<size_t> tail_;
};

} // namespace radio

// ===========================================================================
//  Daqui para baixo: só no aparelho (Arduino + WiFi + FreeRTOS + libhelix).
//  O simulador e os probes compilam apenas a lógica pura acima.
// ===========================================================================
#if defined(ARDUINO)

#include <Arduino.h>
#include <WiFi.h> // WiFiClient — NUNCA WiFiClientSecure aqui (ver nota 1)
#include <esp_heap_caps.h>

#include "libhelix-mp3/mp3dec.h"

namespace radio {

// Timeouts. Todos comparados com timeReached() (aritmética sem sinal): o
// millis() é de 32 bits e dá a volta em ~49 dias (AGENTS.md 3.3).
constexpr uint32_t CONNECT_TIMEOUT_MS = 8000;
constexpr uint32_t HEADER_TIMEOUT_MS = 6000;
constexpr uint32_t STALL_TIMEOUT_MS = 6000; // socket aberto mas mudo: derruba

class Stream {
public:
  // -- ciclo de vida (chamado pelo loop(), core 1) --------------------------

  // Aloca a PSRAM, inicializa o libhelix e cria a tarefa de rede no core 0.
  // Não bloqueia esperando a conexão: a tela mostra CONECTANDO enquanto isso.
  bool begin(int stationIndex) {
    if (running_)
      return true;
    if (stationIndex < 0 || stationIndex >= STATION_COUNT)
      return false;
    station_ = stationIndex;
    if (!parseUrl(STATIONS[station_].url, url_)) {
      conn_.store((uint8_t)Conn::NoMemory);
      return false;
    }
    // Um bloco só de PSRAM para os três buffers: um caminho de falha.
    psram_ = (uint8_t *)heap_caps_malloc(PSRAM_BYTES, MALLOC_CAP_SPIRAM);
    if (!psram_) {
      conn_.store((uint8_t)Conn::NoMemory);
      Serial.println("[M5RETRO] Radio: sem PSRAM para o buffer");
      return false;
    }
    ring_.attach(psram_, RING_BYTES);
    mp3In_ = psram_ + RING_BYTES;
    mp3Pcm_ = (int16_t *)(psram_ + RING_BYTES + MP3_IN_BYTES);
    // O allocador do libhelix (AllocatorExt) já tenta ps_malloc primeiro, então
    // os ~25 KB de estado do decodificador também caem na PSRAM.
    dec_ = MP3InitDecoder();
    if (!dec_) {
      heap_caps_free(psram_);
      psram_ = nullptr;
      conn_.store((uint8_t)Conn::NoMemory);
      Serial.println("[M5RETRO] Radio: sem memoria para o decodificador MP3");
      return false;
    }
    resetDecoder();
    ascii::normalize(name_, sizeof(name_), STATIONS[station_].name);
    title_[0] = 0;
    conn_.store((uint8_t)Conn::Connecting);
    stop_.store(false);
    netAlive_.store(true);
    running_ = true;
    if (xTaskCreatePinnedToCore(netTaskEntry, "RADIO_ICY", 8192, this, 0, nullptr, 1) != pdPASS) {
      netAlive_.store(false);
      running_ = false;
      MP3FreeDecoder(dec_);
      dec_ = nullptr;
      heap_caps_free(psram_);
      psram_ = nullptr;
      conn_.store((uint8_t)Conn::NoMemory);
      return false;
    }
    return true;
  }

  // Encerra tudo. O chamador DEVE ter parado de chamar readPcm() antes (ou
  // seja: desligar o modo rádio do audioTask primeiro).
  //
  // Todas as esperas aqui têm prazo. A armadilha 3 do AGENTS.md foi exatamente
  // uma espera sem prazo que congelou o aparelho para sempre.
  void end() {
    if (!running_)
      return;
    stop_.store(true);
    const uint32_t limit = millis() + 3000;
    while (netAlive_.load() && !timeReached(millis(), limit))
      delay(10);
    const uint32_t limit2 = millis() + 500;
    while (pcmBusy_.load() && !timeReached(millis(), limit2))
      delay(5);
    running_ = false;
    if (dec_) {
      MP3FreeDecoder(dec_);
      dec_ = nullptr;
    }
    if (psram_) {
      heap_caps_free(psram_);
      psram_ = nullptr;
    }
    mp3In_ = nullptr;
    mp3Pcm_ = nullptr;
    ring_.attach(nullptr, 0);
    conn_.store((uint8_t)Conn::Idle);
  }

  // -- consumo de áudio (chamado pela tarefa RCA_PCM, core 0) ---------------

  // MESMO contrato do mp3ReadPcm() do src/main.cpp: escreve `samples` shorts
  // (pares L/R) a 22050 Hz e devolve quantos escreveu.
  //
  // Diferença de propósito em relação ao arquivo: quando o anel seca, isto
  // devolve SILÊNCIO em vez de 0. Devolver 0 faria o audioTask marcar
  // playbackFinished e derrubar a reprodução — e num rádio um engasgo de rede
  // não é fim de faixa.
  size_t readPcm(int16_t *dst, size_t samples) {
    pcmBusy_.store(true);
    size_t produced = 0;
    if (running_ && dec_ && conn_.load() == (uint8_t)Conn::OnAir)
      produced = decodeInto(dst, samples);
    for (size_t i = produced; i < samples; ++i)
      dst[i] = 0;
    pcmBusy_.store(false);
    return samples;
  }

  // -- leitura de estado (qualquer core) ------------------------------------

  Conn state() const { return (Conn)conn_.load(); }
  const char *stateLabel() const { return connLabel(state()); }
  bool active() const { return running_; }
  int station() const { return station_; }

  // Nome da estação: o icy-name quando o servidor mandou, senão o da tabela.
  const char *stationName() const { return icyName_[0] ? icyName_ : name_; }

  // Título corrente (StreamTitle), já ASCII. String vazia quando não há.
  // Copiado sob uma trava curta porque a tarefa de rede pode reescrevê-lo.
  void copyTitle(char *dst, size_t cap) const {
    if (!dst || !cap)
      return;
    titleLock_.store(true);
    strncpy(dst, title_, cap - 1);
    dst[cap - 1] = 0;
    titleLock_.store(false);
  }

  uint32_t reconnects() const { return reconnects_.load(); }
  uint32_t bytesReceived() const { return bytesIn_.load(); }
  // 0..100: quanto do anel está cheio. Útil no `diag status`.
  uint8_t bufferPercent() const {
    return ring_.capacity() ? (uint8_t)((uint64_t)ring_.used() * 100 / ring_.capacity()) : 0;
  }
  // Taxa real lida do primeiro frame decodificado (não presumida).
  int sourceRate() const { return mp3Rate_; }
  int sourceChannels() const { return mp3Chans_; }
  int bitrateKbps() const { return bitrate_; }

private:
  // -- decodificação (espelha mp3ReadPcm do src/main.cpp) -------------------

  void resetDecoder() {
    mp3InLen_ = 0;
    mp3PcmCount_ = 0;
    mp3Phase_ = 0.0;
    mp3Rate_ = 44100;
    mp3Chans_ = 2;
  }

  size_t decodeInto(int16_t *dst, size_t samples) {
    size_t produced = 0;
    while (produced + 1 < samples) {
      if (mp3PcmCount_ == 0) {
        if (mp3InLen_ < 2048) {
          const size_t got = ring_.read(mp3In_ + mp3InLen_, MP3_IN_BYTES - mp3InLen_);
          if (!got && mp3InLen_ == 0)
            break; // anel seco: o chamador completa com silêncio
          mp3InLen_ += got;
        }
        unsigned char *in = mp3In_;
        int bytesLeft = (int)mp3InLen_;
        // MP3Decode devolve código de erro; a CONTAGEM de amostras vem de
        // MP3GetLastFrameInfo().outputSamps — igual ao src/main.cpp.
        const int err = MP3Decode(dec_, &in, &bytesLeft, mp3Pcm_, 0);
        const size_t consumed = (size_t)(in - mp3In_);
        if (consumed > 0) {
          memmove(mp3In_, in, mp3InLen_ - consumed);
          mp3InLen_ -= consumed;
        }
        if (err == 0) {
          MP3FrameInfo info;
          MP3GetLastFrameInfo(dec_, &info);
          mp3PcmCount_ = (size_t)info.outputSamps;
          mp3Phase_ = 0.0;
          mp3Rate_ = info.samprate; // taxa REAL do fluxo, não presumida
          mp3Chans_ = info.nChans;
          if (info.bitrate > 0)
            bitrate_ = info.bitrate / 1000;
        } else if (consumed == 0) {
          // Não avançou: frame corrompido ou desincronizado. Descarta 1 byte e
          // tenta ressincronizar, sem laço apertado.
          if (mp3InLen_ > 0) {
            memmove(mp3In_, mp3In_ + 1, mp3InLen_ - 1);
            --mp3InLen_;
          } else {
            break;
          }
          continue;
        } else {
          continue; // consumiu mas falhou: tenta o próximo frame
        }
      }
      const int ch = mp3Chans_;
      const double ratio = (double)mp3Rate_ / (double)OUT_RATE;
      const int framesIn = (int)(mp3PcmCount_ / ch);
      const int idx = (int)mp3Phase_;
      if (idx >= framesIn - 1) {
        mp3PcmCount_ = 0;
        continue;
      }
      const float frac = (float)(mp3Phase_ - idx);
      for (int c = 0; c < 2; ++c) {
        const int sc = (ch == 1) ? 0 : c;
        const int16_t a = mp3Pcm_[idx * ch + sc];
        const int16_t b = mp3Pcm_[(idx + 1) * ch + sc];
        dst[produced++] = (int16_t)(a + (b - a) * frac);
      }
      mp3Phase_ += ratio;
    }
    return produced;
  }

  // -- tarefa de rede (core 0) ----------------------------------------------

  static void netTaskEntry(void *self) {
    static_cast<Stream *>(self)->netTask();
  }

  void netTask() {
    uint32_t attempt = 0;
    while (!stop_.load()) {
      if (sessionOnce())
        attempt = 0; // sessão útil: o próximo tropeço recomeça do 1 s
      if (stop_.load())
        break;
      conn_.store((uint8_t)Conn::NoSignal);
      // Backoff: dorme em fatias para continuar respondendo ao end().
      const uint32_t wait = backoffDelayMs(attempt);
      const uint32_t until = millis() + wait;
      Serial.printf("[M5RETRO] Radio: reconecta em %lums\n", (unsigned long)wait);
      while (!stop_.load() && !timeReached(millis(), until))
        vTaskDelay(pdMS_TO_TICKS(100));
      if (attempt < 5)
        ++attempt;
      reconnects_.fetch_add(1);
    }
    netAlive_.store(false);
    vTaskDelete(nullptr);
  }

  // Uma sessão HTTP completa. Devolve true se chegou a entrar no ar.
  //
  // Locais: só `buf[256]`. A pilha desta tarefa é de 8 KB e duas tarefas já a
  // estouraram neste repositório (AGENTS.md 2.3) — nada de array grande aqui.
  bool sessionOnce() {
    conn_.store((uint8_t)Conn::Connecting);
    ring_.clear();
    resetDecoder();
    header_.reset();
    WiFiClient client;
    client.setTimeout(5); // segundos: o WiFiClient do arduino-esp32 usa segundos
    if (!client.connect(url_.host, url_.port, CONNECT_TIMEOUT_MS)) {
      Serial.printf("[M5RETRO] Radio: falha ao conectar em %s:%u\n", url_.host, (unsigned)url_.port);
      return false;
    }
    // Icy-MetaData: 1 pede o título da música. Connection: close porque não há
    // reuso a fazer — este socket fica aberto até cair.
    client.printf("GET %s HTTP/1.1\r\n"
                  "Host: %s\r\n"
                  "User-Agent: M5RetroTV/1.0\r\n"
                  "Icy-MetaData: 1\r\n"
                  "Connection: close\r\n"
                  "\r\n",
                  url_.path, url_.host);

    uint8_t buf[256]; // único local grande da tarefa
    // --- cabeçalho ---
    const uint32_t hdrDeadline = millis() + HEADER_TIMEOUT_MS;
    bool started = false;
    while (!stop_.load() && !header_.done()) {
      if (timeReached(millis(), hdrDeadline)) {
        client.stop();
        return false;
      }
      const int n = client.read(buf, sizeof(buf));
      if (n <= 0) {
        if (!client.connected() && !client.available()) {
          client.stop();
          return false;
        }
        vTaskDelay(pdMS_TO_TICKS(10));
        continue;
      }
      const size_t used = header_.feed(buf, (size_t)n);
      if (header_.done()) {
        if (!header_.ok()) {
          Serial.printf("[M5RETRO] Radio: resposta invalida (status %ld)\n",
                        (long)header_.info().status);
          client.stop();
          return false;
        }
        const IcyInfo &icy = header_.info();
        if (icy.name[0])
          strncpy(icyName_, icy.name, sizeof(icyName_) - 1);
        splitter_.begin(icy.metaint);
        Serial.printf("[M5RETRO] Radio: %s metaint:%ld\n", stationName(), (long)icy.metaint);
        started = true;
        // A sobra do MESMO read já é corpo: passa pelo de-interleave in-place.
        if ((size_t)n > used) {
          const size_t got = splitter_.split(buf + used, (size_t)n - used, buf);
          ring_.write(buf, got);
          bytesIn_.fetch_add((uint32_t)got);
        }
      }
    }
    if (!started || stop_.load()) {
      client.stop();
      return false;
    }

    // --- corpo ---
    uint32_t lastData = millis();
    bool onAir = false;
    while (!stop_.load()) {
      if (!client.connected() && !client.available())
        break;
      if (timeReached(millis(), lastData + STALL_TIMEOUT_MS)) {
        Serial.println("[M5RETRO] Radio: fluxo mudo, derrubando");
        break;
      }
      // Anel quase cheio: o decodificador está atrasado. Espera em vez de
      // descartar, porque descartar byte de MP3 é estalo garantido.
      if (ring_.space() < sizeof(buf)) {
        vTaskDelay(pdMS_TO_TICKS(20));
        continue;
      }
      const int n = client.read(buf, sizeof(buf));
      if (n <= 0) {
        vTaskDelay(pdMS_TO_TICKS(5));
        continue;
      }
      lastData = millis();
      // in-place: os bytes de áudio só andam para a esquerda.
      const size_t got = splitter_.split(buf, (size_t)n, buf);
      if (got)
        ring_.write(buf, got);
      bytesIn_.fetch_add((uint32_t)got);
      if (splitter_.takeTitleFlag())
        publishTitle(splitter_.title());
      if (!onAir && ring_.used() >= PREBUFFER_BYTES) {
        onAir = true;
        conn_.store((uint8_t)Conn::OnAir);
        Serial.println("[M5RETRO] Radio: no ar");
      }
    }
    client.stop();
    return onAir;
  }

  void publishTitle(const char *t) {
    // Trava de ocupado curtíssima: uma cópia de <=128 bytes. Não é um mutex de
    // verdade e não precisa ser — a alternativa (leitor ver meia string) só
    // afetaria um quadro de texto.
    while (titleLock_.load())
      vTaskDelay(1);
    strncpy(title_, t, sizeof(title_) - 1);
    title_[sizeof(title_) - 1] = 0;
    Serial.printf("[M5RETRO] Radio: %s\n", title_);
  }

  // -- estado ---------------------------------------------------------------

  Url url_{};
  int station_ = 0;
  bool running_ = false;

  uint8_t *psram_ = nullptr;
  Ring ring_;
  unsigned char *mp3In_ = nullptr;
  int16_t *mp3Pcm_ = nullptr;

  HMP3Decoder dec_ = nullptr;
  size_t mp3InLen_ = 0, mp3PcmCount_ = 0;
  int mp3Rate_ = 44100, mp3Chans_ = 2, bitrate_ = 0;
  double mp3Phase_ = 0.0;

  HeaderParser header_;
  MetaSplitter splitter_;

  char name_[40] = {0};    // da tabela
  char icyName_[40] = {0}; // do servidor
  char title_[128] = {0};

  std::atomic<uint8_t> conn_{(uint8_t)Conn::Idle};
  std::atomic<bool> stop_{false};
  std::atomic<bool> netAlive_{false};
  std::atomic<bool> pcmBusy_{false};
  mutable std::atomic<bool> titleLock_{false};
  std::atomic<uint32_t> reconnects_{0};
  std::atomic<uint32_t> bytesIn_{0};
};

} // namespace radio

#endif // ARDUINO

#pragma once
// ============================================================================
// Relogio do M5 RETRO TV: BM8563 (RTC com bateria) + NTP + fuso do Brasil.
//
// O PROBLEMA QUE ISTO RESOLVE
//
// Antes deste header o relogio vinha so do NTP, por `configTime(0, 0, ...)`.
// Duas consequencias:
//
//  1. Sem Wi-Fi o epoch fica em 1970 e a tela inicial mostra o aviso de nao
//     sincronizado, mesmo com o BM8563 da placa marcando a hora certa desde o
//     boot anterior.
//  2. `configTime(0, 0, ...)` chama `setTimeZone(0, 0)`, que escreve
//     TZ="UTC0DST0" e roda `tzset()` (ver esp32-hal-time.c do arduino-esp32
//     2.x). Ou seja, `localtime_r()` devolvia **UTC**: o relogio da tela
//     adiantava 3 horas em relacao ao horario de Brasilia.
//
// COMO FUNCIONA
//
// Convencao: o BM8563 guarda **UTC**, nunca hora local. E a mesma convencao do
// M5Unified (`RTC_Class::setSystemTimeFromRtc()` forca GMT0 no `mktime`), entao
// quem usar a outra API continua enxergando a mesma coisa. Toda a conversao
// para horario de Brasilia e feita pela libc, via TZ.
//
//   boot   -> begin()  le o BM8563, valida e semeia o relogio com settimeofday
//   loop   -> poll()   detecta o acerto do NTP e devolve a hora ao BM8563
//
// POR QUE NAO USAR `M5.Rtc.setSystemTimeFromRtc()` DIRETO
//
// O `M5.begin()` ja chama essa funcao (M5Unified.cpp, `_begin_rtc_imu`), mas
// ela nao serve sozinha aqui:
//
//  - nao valida nada: BM8563 zerado (placa nova ou bateria morta) vira
//    01/01/2000 e o firmware passaria a exibir uma data falsa com a mesma
//    confianca de uma data boa;
//  - ela troca TZ para "GMT0" para forcar `mktime` em UTC, restaura o valor
//    antigo com `setenv`/`unsetenv` e **nao chama `tzset()` de novo**. O estado
//    interno da libc fica em GMT0 ate alguem chamar `tzset()`;
//  - `getenv("TZ")` seguido de `setenv("TZ", ...)` pode invalidar o ponteiro
//    devolvido pelo `getenv`.
//
// Aqui a conversao data->epoch e aritmetica pura (algoritmo de dias civis), sem
// `mktime` e sem mexer em TZ no meio do caminho.
//
// CUSTO
//
// Nenhuma alocacao. O estado mora num unico `static` de funcao: 24 bytes de
// SRAM. Nada aqui bloqueia o boot — leitura e escrita do BM8563 sao quatro
// transacoes I2C curtas no barramento interno, e qualquer falha so faz a fonte
// ficar SOURCE_NONE.
//
// C++11 (-std=gnu++11). ASCII puro no texto de interface.
// ============================================================================

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#if defined(ARDUINO) || defined(ESP_PLATFORM)
#define RTCCLOCK_HARDWARE 1
#include <Arduino.h>
#include <M5Unified.h>
#include <sys/time.h>
#if __has_include(<esp_sntp.h>)
#include <esp_sntp.h>
#define RTCCLOCK_HAS_SNTP 1
#endif
#else
// Compilacao nativa (sim/probes): so a logica pura fica disponivel.
#define RTCCLOCK_HARDWARE 0
#endif

namespace rtcclock {

// --------------------------------------------------------------------------
// Fuso horario
// --------------------------------------------------------------------------

// Horario de Brasilia, UTC-3, SEM horario de verao. O Brasil revogou o horario
// de verao em 2019 (Decreto 9.772/2019), entao nao existe regra de transicao a
// implementar — e inventar uma deixaria o relogio uma hora errado meio ano.
//
// Formato POSIX: o nome entre <> e obrigatorio porque "-03" comeca com sinal, e
// o numero apos o nome e quanto somar a hora LOCAL para chegar em UTC. Logo
// "3" significa UTC-3, nao UTC+3. Sem virgula depois = sem horario de verao.
//
// A forma entre <> e suportada pelo newlib do toolchain xtensa-esp32 (o parser
// de `_tzset_unlocked_r` compara com '<' e '>'), pelo glibc e pelo tzcode do
// macOS. Ainda assim `applyTimezone()` confere o resultado e cai para "BRT3",
// que e ASCII alfabetico puro, se algum dia o parser mudar.
static const char TZ_BRASILIA[] = "<-03>3";
static const char TZ_BRASILIA_FALLBACK[] = "BRT3";

// Deslocamento esperado: -3 h. Serve de criterio do autoteste de TZ.
static const long UTC_OFFSET_SECONDS = -3L * 3600L;

// --------------------------------------------------------------------------
// Janela de plausibilidade
// --------------------------------------------------------------------------

// 2020-01-01T00:00:00Z. Abaixo disto a data e lixo: um BM8563 zerado marca
// 2000-01-01 e um relogio sem `settimeofday` marca 1970-01-01. O firmware ja
// usa 1704067200 (2024) como "houve NTP"; aqui o limiar e mais baixo de
// proposito, porque uma data de 2021 vinda do RTC ainda e melhor que nada.
static const time_t EPOCH_MIN = 1577836800; // 2020-01-01
static const time_t EPOCH_MAX = 4102444800; // 2100-01-01

// De quanto em quanto tempo reescrever o BM8563 enquanto o NTP estiver vivo.
static const uint32_t REWRITE_INTERVAL_MS = 6UL * 3600UL * 1000UL; // 6 h

// Tolerancia para considerar que alguem pulou o relogio (o NTP acertou).
static const int32_t STEP_TOLERANCE_S = 2;

// --------------------------------------------------------------------------
// Logica pura — testavel no PC (sim/probes/rtc_clock.cpp)
// --------------------------------------------------------------------------

inline int daysInMonth(int year, int month) {
  if (month < 1 || month > 12)
    return 0;
  if (month == 2)
    return ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) ? 29 : 28;
  const int table[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  return table[month - 1];
}

// Dias civis desde 1970-01-01 (algoritmo days_from_civil de Howard Hinnant).
// Calendario gregoriano proleptico, sem tabela e sem laco.
inline int64_t daysFromCivil(int year, int month, int day) {
  year -= (month <= 2) ? 1 : 0;
  const int64_t era = (year >= 0 ? year : year - 399) / 400;
  const int64_t yoe = int64_t(year) - era * 400;                       // [0, 399]
  const int64_t doy = (153 * (month + (month > 2 ? -3 : 9)) + 2) / 5 + day - 1;
  const int64_t doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;           // [0, 146096]
  return era * 146097 + doe - 719468;
}

// Data/hora **em UTC** -> epoch. Equivale a `timegm()`, que o newlib nao tem.
inline time_t epochFromUtc(int year, int month, int day, int hour, int minute, int second) {
  return time_t(daysFromCivil(year, month, day) * 86400LL + int64_t(hour) * 3600LL +
                int64_t(minute) * 60LL + int64_t(second));
}

// Uma leitura do BM8563 so e aceita se passar por aqui. Um chip sem bateria
// devolve 2000-01-01, e um chip com o barramento ruim devolve campos fora de
// faixa; os dois casos caem fora.
inline bool isPlausibleDate(int year, int month, int day, int hour, int minute, int second) {
  if (year < 2020 || year > 2099)
    return false;
  if (month < 1 || month > 12)
    return false;
  if (day < 1 || day > daysInMonth(year, month))
    return false;
  if (hour < 0 || hour > 23)
    return false;
  if (minute < 0 || minute > 59)
    return false;
  if (second < 0 || second > 60) // 60 cobre segundo bissexto lido do chip
    return false;
  return true;
}

inline bool isPlausibleEpoch(time_t t) { return t >= EPOCH_MIN && t < EPOCH_MAX; }

// --------------------------------------------------------------------------
// Fonte da hora, para a tela SISTEMA
// --------------------------------------------------------------------------

enum Source : uint8_t {
  SOURCE_NONE = 0, // nao ha hora confiavel
  SOURCE_RTC = 1,  // semeada pelo BM8563 no boot
  SOURCE_NTP = 2   // acertada pela rede (e ja devolvida ao BM8563)
};

// ASCII sem acento: vai direto para a tela composta.
inline const char *sourceLabel(Source s) {
  switch (s) {
  case SOURCE_RTC:
    return "RTC";
  case SOURCE_NTP:
    return "NTP";
  default:
    return "SEM HORA";
  }
}

// --------------------------------------------------------------------------
// Estado (24 bytes de SRAM, num static de funcao inline: um por programa)
// --------------------------------------------------------------------------

struct State {
  time_t baseEpoch;   // epoch da ultima vez que sabiamos a hora
  const char *tz;     // string de TZ que de fato vingou (ponteiro para literal)
  uint32_t baseMs;    // millis() correspondente, para detectar o pulo do NTP
  uint32_t lastPollMs;
  uint32_t lastWriteMs;
  Source source;
  bool present;    // o BM8563 respondeu ao I2C
  bool batteryLow; // flag VL do BM8563: a hora guardada pode ter sido perdida
  bool tzApplied;
};

inline State &state() {
  static State s = {0, NULL, 0, 0, 0, SOURCE_NONE, false, false, false};
  return s;
}

inline Source source() { return state().source; }
inline const char *sourceLabel() { return sourceLabel(state().source); }
inline bool synced() { return state().source != SOURCE_NONE; }
inline bool present() { return state().present; }
inline bool batteryLow() { return state().batteryLow; }
inline long utcOffsetSeconds() { return UTC_OFFSET_SECONDS; }
// String de TZ em vigor, para a tela SISTEMA e para o `diag status`.
inline const char *timezoneString() { return state().tz ? state().tz : TZ_BRASILIA; }

// --------------------------------------------------------------------------
// TZ
// --------------------------------------------------------------------------

// Confere se o TZ em vigor de fato coloca o horario local 3 h atras do UTC.
// Usa uma data de janeiro so para nao depender de nada: sem horario de verao o
// deslocamento e o mesmo o ano inteiro.
inline bool timezoneOffsetOk() {
  const time_t probe = 1767225600; // 2026-01-01T00:00:00Z
  struct tm local;
  memset(&local, 0, sizeof(local));
  if (!localtime_r(&probe, &local))
    return false;
  const time_t asUtc = epochFromUtc(local.tm_year + 1900, local.tm_mon + 1, local.tm_mday,
                                    local.tm_hour, local.tm_min, local.tm_sec);
  return (long)(asUtc - probe) == UTC_OFFSET_SECONDS;
}

// Impoe o fuso do Brasil. Idempotente e barata: so mexe no ambiente se o TZ
// atual for outro. Precisa ser rechamada depois de qualquer `configTime()`,
// que reescreve TZ para "UTC0DST0" pelas costas.
inline bool applyTimezone() {
  State &s = state();
  const char *current = getenv("TZ");
  // Caminho rapido, que e o do loop(): se o TZ do ambiente ainda e o que nos
  // instalamos, nao ha nada a fazer e o custo e um strcmp de 6 bytes.
  if (s.tzApplied && current && s.tz && strcmp(current, s.tz) == 0)
    return true;

  setenv("TZ", TZ_BRASILIA, 1);
  tzset();
  if (timezoneOffsetOk()) {
    s.tz = TZ_BRASILIA;
    s.tzApplied = true;
    return true;
  }
  // Parser de TZ sem suporte a <...>: cai para a forma alfabetica.
  setenv("TZ", TZ_BRASILIA_FALLBACK, 1);
  tzset();
  s.tz = TZ_BRASILIA_FALLBACK;
  s.tzApplied = timezoneOffsetOk();
  return s.tzApplied;
}

// --------------------------------------------------------------------------
// Hardware: BM8563 via M5Unified 0.2.10 (m5::RTC_Class, driver PCF8563, 0x51)
// --------------------------------------------------------------------------

#if RTCCLOCK_HARDWARE

namespace detail {

inline void rebase(time_t epoch) {
  State &s = state();
  s.baseEpoch = epoch;
  s.baseMs = millis();
}

#if defined(RTCCLOCK_HAS_SNTP)
// Roda na tarefa do SNTP, nao no loop(). Aqui **so** se levanta a bandeira:
// I2C e desenho ficam para o poll(), no loop(), como manda o resto do firmware.
inline volatile bool &ntpFlag() {
  static volatile bool flag = false;
  return flag;
}
inline void onNtpSync(struct timeval *tv) {
  (void)tv;
  ntpFlag() = true;
}
#endif

} // namespace detail

// Grava o relogio do sistema (convertido para UTC) no BM8563. Devolve false se
// o chip nao respondeu ou se a hora do sistema ainda nao presta.
inline bool saveToRtc() {
  State &s = state();
  if (!M5.Rtc.isEnabled())
    return false;
  const time_t now = time(NULL);
  if (!isPlausibleEpoch(now))
    return false;
  struct tm utc;
  memset(&utc, 0, sizeof(utc));
  if (!gmtime_r(&now, &utc))
    return false;
  // rtc_datetime_t(const tm&) preenche data e hora, inclusive tm_wday.
  m5::rtc_datetime_t dt(utc);
  M5.Rtc.setDateTime(&dt);
  s.lastWriteMs = millis();
  return true;
}

// Chamar uma vez no setup(), depois de M5.begin() (que e quem inicializa o
// barramento I2C interno e o driver do BM8563). Nao bloqueia: se o chip nao
// responder, a funcao devolve false e o firmware segue com SOURCE_NONE.
inline bool begin() {
  State &s = state();
  applyTimezone();

#if defined(RTCCLOCK_HAS_SNTP)
  // Registrado antes do configTime: nem sntp_stop() nem sntp_init() limpam o
  // callback, entao a ordem nao importa — mas registrar cedo evita perder o
  // primeiro acerto se a rede subir rapido.
  sntp_set_time_sync_notification_cb(detail::onNtpSync);
#endif

  // M5.begin() ja chamou M5.Rtc.begin() (cfg.internal_rtc e true por padrao).
  // Isto aqui e so a rede de seguranca para quem mudar a config; sao duas
  // transacoes I2C com timeout proprio do driver, nao ha espera indefinida.
  if (!M5.Rtc.isEnabled())
    M5.Rtc.begin(&M5.In_I2C, M5.getBoard());
  if (!M5.Rtc.isEnabled()) {
    s.present = false;
    s.source = SOURCE_NONE;
    return false;
  }
  s.present = true;
  s.batteryLow = M5.Rtc.getVoltLow();

  m5::rtc_datetime_t dt;
  if (!M5.Rtc.getDateTime(&dt)) {
    s.source = SOURCE_NONE;
    return false;
  }
  if (!isPlausibleDate(dt.date.year, dt.date.month, dt.date.date, dt.time.hours, dt.time.minutes,
                       dt.time.seconds)) {
    // Placa nova, bateria morta ou leitura corrompida: melhor continuar sem
    // hora (a tela ja sabe avisar) que exibir 01/01/2000 com ar de verdade.
    s.source = SOURCE_NONE;
    return false;
  }

  const time_t epoch = epochFromUtc(dt.date.year, dt.date.month, dt.date.date, dt.time.hours,
                                    dt.time.minutes, dt.time.seconds);
  if (!isPlausibleEpoch(epoch)) {
    s.source = SOURCE_NONE;
    return false;
  }
  struct timeval tv;
  tv.tv_sec = epoch;
  tv.tv_usec = 0;
  settimeofday(&tv, NULL);
  detail::rebase(epoch);
  s.source = SOURCE_RTC;
  return true;
}

// Substitui `configTime(0, 0, ...)`: mesmo SNTP, mas o TZ que fica valendo e o
// do Brasil, e nao "UTC0DST0".
inline void configTimeBrazil(const char *server1 = "pool.ntp.org",
                             const char *server2 = "time.cloudflare.com",
                             const char *server3 = NULL) {
  configTzTime(TZ_BRASILIA, server1, server2, server3);
  // configTzTime escreve o TZ cru; a checagem devolve o fallback se preciso.
  applyTimezone();
}

// Chamar a cada volta do loop(). Custa um millis() e um strcmp fora da janela
// de 1 s. Devolve true quando acabou de gravar a hora no BM8563.
inline bool poll() {
  State &s = state();
  const uint32_t nowMs = millis();
  if (uint32_t(nowMs - s.lastPollMs) < 1000u)
    return false;
  s.lastPollMs = nowMs;

  // Se alguem chamou configTime() no meio do caminho, o TZ virou UTC0DST0.
  applyTimezone();

  const time_t now = time(NULL);
  if (!isPlausibleEpoch(now))
    return false;

  bool stepped = false;
#if defined(RTCCLOCK_HAS_SNTP)
  if (detail::ntpFlag()) {
    detail::ntpFlag() = false;
    stepped = true;
  }
#endif
  if (!stepped) {
    if (s.source == SOURCE_NONE) {
      // Nao havia hora nenhuma e agora ha: so pode ter vindo da rede.
      stepped = true;
    } else {
      // O relogio do sistema avanca com o mesmo tick do millis(); divergir
      // acima da tolerancia quer dizer que alguem chamou settimeofday().
      const int64_t elapsed = int64_t(uint32_t(nowMs - s.baseMs)) / 1000;
      const int64_t drift = int64_t(now) - (int64_t(s.baseEpoch) + elapsed);
      if (drift > STEP_TOLERANCE_S || drift < -STEP_TOLERANCE_S)
        stepped = true;
    }
  }

  if (stepped) {
    s.source = SOURCE_NTP;
    detail::rebase(now);
    return saveToRtc();
  }
  // Reescrita periodica: mantem o BM8563 disciplinado numa sessao longa.
  if (s.source == SOURCE_NTP && uint32_t(nowMs - s.lastWriteMs) >= REWRITE_INTERVAL_MS) {
    detail::rebase(now);
    return saveToRtc();
  }
  return false;
}

#else // !RTCCLOCK_HARDWARE — compilacao nativa: so a logica pura

inline bool begin() { return false; }
inline bool saveToRtc() { return false; }
inline bool poll() { return false; }

#endif // RTCCLOCK_HARDWARE

} // namespace rtcclock

#pragma once
// ============================================================================
// Subtitles — legendas .srt no estilo do closed caption da linha 21 do NTSC.
//
// Por que existe: o par MJPEG+WAV do cartao nao carrega legenda nenhuma. Quem
// prepara o video (tools/prepare_video.py) pode deixar um `.srt` ao lado do
// `.mjpeg`, e este modulo o le enquanto o filme roda.
//
//   /M5RETRO/videos/foo/video.mjpeg  ->  /M5RETRO/videos/foo/video.srt
//
// Vocabulario visual reproduzido — o closed caption de verdade, nao a legenda
// de cinema: caixa preta opaca atras de cada linha, texto branco puro em caixa
// alta, no maximo duas linhas, ancorado na base. Nada de ciano: croma saturado
// (TFT_CYAN / 0x07FF) faz dot crawl na saida composta, e o CC original era
// branco no preto justamente porque era o que sobrevivia ao sinal.
//
// ---------------------------------------------------------------------------
//  Tres decisoes que valem explicacao
// ---------------------------------------------------------------------------
//
// 1) LEITURA SO PARA A FRENTE, SEM INDICE. Um .srt de um filme longo tem
//    milhares de cues; indexar todos custaria dezenas de KB de SRAM, que e o
//    recurso escasso aqui (ver AGENTS.md secao 2.2). Este leitor guarda no
//    maximo DUAS cues: a exibida e a proxima. O resto fica no cartao. Custo:
//    nao da para voltar. Depois de qualquer salto para tras (reiniciar o
//    programa, trocar de video) o chamador faz `arquivo.seek(0)` e `reset()`.
//
// 2) O RELOGIO E O DO AUDIO, NAO O `millis()`. O firmware ja acerta o video por
//    `samplesPlayed` (ver videoTick em src/main.cpp); a legenda usa o mesmo
//    relogio ou desanda junto com o video nos quadros descartados. Por isso a
//    API recebe `positionMs` pronto e nunca chama millis():
//
//      const uint32_t posMs = sampleRate ? uint32_t(uint64_t(samplesPlayed.load())
//                                                   * 1000ULL / sampleRate) : 0;
//
// 3) O CHAMADOR E DONO DO sdMutex. Este header NAO toma o mutex — nao inclui
//    FreeRTOS nem SD, justamente para compilar tambem no simulador de desktop.
//    `update()` recebe o `File&` ja aberto e **exige que o chamador segure o
//    sdMutex durante a chamada** (uma tomada por chamada, devolvida logo
//    depois — nunca segurar por mais tempo, senao o audio passa fome). Em
//    troca, `update()` faz pouquissima leitura: 192 bytes por bloco e no maximo
//    `kCuesPerUpdate` cues por chamada. `draw()` NAO toca no cartao.
//
// ---------------------------------------------------------------------------
//  Orcamento
// ---------------------------------------------------------------------------
//  sizeof(Subtitles) ~ 330 bytes (static_assert abaixo trava em 1 KB), sem
//  alocacao dinamica, sem String e sem LGFX_Sprite. A instancia deve ser
//  global/estatica: um objeto destes na pilha de uma tarefa que faz HTTPS ja
//  seria metade do respiro do handshake (AGENTS.md secao 2.3). `update()` usa
//  ~280 bytes de pilha em buffers locais; roda no loop() (8192), onde cabe.
//
// ---------------------------------------------------------------------------
//  Conflito com o OSD do player
// ---------------------------------------------------------------------------
//  A caixa da legenda ocupa y 168..199, e o OSD de videocassete (VcrOsd.h)
//  ocupa 148..221. Eles se sobrepoem de proposito: os dois querem a base da
//  tela, como na TV de verdade. Quem chama decide a precedencia — o caminho
//  recomendado e esconder a legenda enquanto `drawPlaybackOsd()` estiver
//  visivel (o OSD e transitorio, 3 s), simplesmente nao chamando `draw()`.
//
// ---------------------------------------------------------------------------
//  Limitacao conhecida da fonte
// ---------------------------------------------------------------------------
//  A VcrFont tem 45 glifos: espaco, 0-9, A-Z e : . - / % + ? ! — nao tem
//  virgula. Legenda e texto cheio de virgula, e cada uma sai como um espaco
//  (glyphIndex devolve SPACE para o que nao existe). O texto NAO e alterado
//  aqui de proposito: trocar ',' por '.' seria mentir na pontuacao. Resolver
//  de verdade custa um glifo novo na VcrFont.h (16 linhas de tabela, 32 bytes
//  de flash) e uma entrada em glyphIndex — fora do escopo deste header.
//
// Dependencias: SafeArea.h, VcrFont.h (que traz o M5GFX) e Ascii.h. Nada de
// Arduino, SD ou FreeRTOS — o mesmo header compila no firmware (gnu++11) e no
// simulador SDL.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "VcrFont.h"

#include <stddef.h>
#include <stdint.h>
#include <string.h>

namespace subs {

// ---------------------------------------------------------------------------
//  Geometria — ancorada na base da area segura, ACIMA da barra dos botoes
// ---------------------------------------------------------------------------
namespace layout {

constexpr int kScale = 1;                 // 12x16 na tela; CC nunca foi grande
constexpr int kLineH = vcrfont::CELL_H;   // 16
constexpr int kMaxLines = 2;              // o CC da linha 21 tambem parava em 2
constexpr int kPadX = 4;                  // respiro da caixa preta, por lado
constexpr int kGapToBar = 2;              // folga ate a barra de legendas

// Colunas que cabem na largura segura com a caixa preta inclusa:
// (272 - 8) / 12 = 22 caracteres.
constexpr int kMaxCols = (crt::SAFE_W - 2 * kPadX) / (vcrfont::CELL_W * kScale);

constexpr int kBlockH = kMaxLines * kLineH;       // 32
constexpr int kBottom = crt::BAR_Y - kGapToBar;   // 200 — primeira linha livre
constexpr int kTop = kBottom - kBlockH;           // 168

// A celula da VcrFont ja tem 2 px de folga em cima e embaixo, entao a caixa
// preta nao precisa de padding vertical proprio: sai com a altura da celula.
static_assert(kBottom <= crt::BAR_Y, "legenda invade a barra dos botoes");
static_assert(kTop >= crt::SAFE_T, "legenda escapa pelo topo da area segura");
static_assert(kMaxCols >= 10, "area segura estreita demais para uma legenda");

} // namespace layout

// Cores em RGB565, escritas na mao (o header nao depende das macros TFT_*).
// Branco no preto: o par do CC original e o unico que nao sofre dot crawl.
constexpr uint16_t kInk = 0xFFFF;
constexpr uint16_t kBox = 0x0000;

// Retangulo em coordenadas do destino (ja com o deslocamento ox/oy aplicado).
// Sem inicializador de membro de proposito: em C++11 um NSDMI tiraria o status
// de agregado e quebraria a inicializacao por chaves.
struct Rect {
  int x, y, w, h;
};

// Faixa maxima que `draw()` pode tocar. Serve a quem prefere repintar sempre a
// mesma regiao a rastrear o retangulo sujo de cada cue.
inline Rect band() {
  Rect r;
  r.x = crt::SAFE_L;
  r.y = layout::kTop;
  r.w = crt::SAFE_W;
  r.h = layout::kBlockH;
  return r;
}

// Troca a extensao de `videoPath` por ".srt" (o `.srt` mora ao lado do video).
// Sem extensao, anexa. Devolve false se nao couber em `cap`.
inline bool makeSrtPath(const char *videoPath, char *dst, size_t cap) {
  if (!videoPath || !dst || cap < 5)
    return false;
  const size_t n = strlen(videoPath);
  size_t cut = n;
  for (size_t i = n; i > 0; --i) {
    const char c = videoPath[i - 1];
    if (c == '/')
      break; // ponto depois da ultima barra, ou nao vale
    if (c == '.') {
      cut = i - 1;
      break;
    }
  }
  if (cut + 5 > cap)
    return false;
  memcpy(dst, videoPath, cut);
  memcpy(dst + cut, ".srt", 5);
  return true;
}

// ---------------------------------------------------------------------------
//  Leitor + renderizador
// ---------------------------------------------------------------------------
//
// `Stream` e qualquer coisa com `read(uint8_t *, size_t) -> tamanho lido`,
// exatamente o contrato que `playback::MjpegReader` usa: o `File` do Arduino
// serve, e no desktop uma classe de 10 linhas sobre um buffer ou um
// std::istream tambem. E o que torna o parser testavel sem cartao SD.
class Subtitles {
public:
  // Quantas cues no maximo cada `update()` consome. Limita o trabalho (e o
  // tempo com o sdMutex na mao) quando o relogio pula varias cues de uma vez.
  static const int kCuesPerUpdate = 4;
  // Teto de linhas varridas atras de um "-->" numa unica chamada. Um arquivo de
  // lixo nao pode prender o loop; como o fluxo so anda para a frente, cada
  // chamada progride e o EOF encerra.
  static const int kScanPerUpdate = 64;
  // Teto de linhas de texto de UMA cue. Depois disso a cue e fechada onde esta.
  static const int kTextLines = 16;

  Subtitles() { reset(); }

  // Esquece tudo. Use ao abrir outro .srt, ou depois de `arquivo.seek(0)` —
  // este leitor nao volta sozinho.
  void reset() {
    cursor_ = count_ = 0;
    first_ = true;
    eof_ = false;
    haveCur_ = haveNext_ = false;
    lastStart_ = 0;
    started_ = false;
    seq_ = 0;
    cur_.reset();
    next_.reset();
    dirty_.x = dirty_.y = dirty_.w = dirty_.h = 0;
  }

  // Avanca o parser ate a cue correspondente a `positionMs`.
  //
  // PRE-CONDICAO: o chamador segura o sdMutex durante esta chamada (ela le do
  // cartao). Nao chame com o mutex ja tomado por outro caminho, e nao segure o
  // mutex em volta de `draw()` — `draw()` nao le nada.
  template <class Stream> void update(Stream &file, uint32_t positionMs) {
    for (int guard = 0; guard < kCuesPerUpdate; ++guard) {
      if (!haveNext_) {
        if (eof_)
          break;
        if (!parseCue(file, next_))
          break; // EOF, ou orcamento de varredura estourado: tenta na proxima
        haveNext_ = true;
      }
      if (next_.startMs > positionMs)
        break; // a proxima ainda esta no futuro: nada a promover
      cur_ = next_;
      haveCur_ = true;
      haveNext_ = false;
      ++seq_;
    }
  }

  // Ha cue valida cobrindo `positionMs`?
  bool active(uint32_t positionMs) const {
    return haveCur_ && cur_.count && positionMs >= cur_.startMs && positionMs < cur_.endMs;
  }

  // 0 quando nada esta no ar; caso contrario um numero que muda a cada troca de
  // cue. Guarde o valor anterior: mudou, repinte; virou 0, apague.
  uint32_t revision(uint32_t positionMs) const { return active(positionMs) ? seq_ : 0; }

  // Linhas ja normalizadas (ASCII maiusculo) e quebradas. `i` de 0 a 1.
  uint8_t lineCount() const { return cur_.count; }
  const char *line(uint8_t i) const { return i < cur_.count ? cur_.text[i] : ""; }
  uint32_t cueStartMs() const { return cur_.startMs; }
  uint32_t cueEndMs() const { return cur_.endMs; }
  bool finished() const { return eof_ && !haveNext_; }

  // Pinta a legenda sobre a imagem. Nao le o cartao: usa a cue ja em memoria.
  // `ox`/`oy` seguem a convencao dos pintores do repositorio (dst, ox, oy, ...):
  // com deslocamento zero e o desenho normal.
  //
  // Sem cue no ar nao desenha nada E NAO MEXE no retangulo sujo — e assim que o
  // chamador ainda consegue saber o que precisa repintar depois que a cue sai.
  void draw(lgfx::LovyanGFX *dst, int ox, int oy, uint32_t positionMs) {
    if (!dst || !active(positionMs))
      return;
    const int n = cur_.count;
    const int top = layout::kBottom - n * layout::kLineH;
    int minX = crt::W, maxX = 0;
    dst->startWrite();
    for (int i = 0; i < n; ++i) {
      const int w = vcrfont::textWidth(cur_.text[i], layout::kScale);
      const int x = (crt::W - w) / 2; // centro do quadro = centro da area segura
      const int y = top + i * layout::kLineH;
      // Caixa opaca por linha, como no CC de verdade (cada fileira tinha o seu
      // fundo, e nao um bloco unico atras das duas).
      dst->fillRect(ox + x - layout::kPadX, oy + y, w + 2 * layout::kPadX, layout::kLineH, kBox);
      // Sem contorno: a caixa ja da o contraste, e contorno preto sobre preto
      // seria 2,15x os pixels por glifo de graca (ver VcrFont.h).
      vcrfont::drawText(dst, cur_.text[i], ox + x, oy + y, (int32_t)kInk, layout::kScale,
                        vcrfont::NO_OUTLINE);
      if (x - layout::kPadX < minX)
        minX = x - layout::kPadX;
      if (x + w + layout::kPadX > maxX)
        maxX = x + w + layout::kPadX;
    }
    dst->endWrite();
    dirty_.x = ox + minX;
    dirty_.y = oy + top;
    dirty_.w = maxX - minX;
    dirty_.h = n * layout::kLineH;
  }

  // Ultimo retangulo pintado, em coordenadas do destino. `w == 0` = nada sujo.
  // O caminho barato para apaga-lo e deixar o proximo quadro do filme cobrir a
  // area; com o video pausado, redecodifique o quadro (redrawCurrentFrame()).
  Rect dirty() const { return dirty_; }

  // Apaga o retangulo sujo e o zera. Atalho para quando nao ha imagem embaixo
  // (letterbox) — sobre o filme prefira repintar o quadro.
  void clear(lgfx::LovyanGFX *dst, int ox, int oy, uint16_t background = kBox) {
    if (dst && dirty_.w > 0)
      dst->fillRect(dirty_.x + ox, dirty_.y + oy, dirty_.w, dirty_.h, background);
    dirty_.x = dirty_.y = dirty_.w = dirty_.h = 0;
  }

private:
  // Capacidade do texto cru de uma cue depois de tirar as etiquetas e
  // normalizar: 2 linhas de 22 mais folga para a quebra de palavra.
  static const size_t kTextCap = 80;
  static const size_t kLineCap = 128; // linha do arquivo; o excedente e comido

  struct Cue {
    uint32_t startMs, endMs;
    uint8_t count;
    char text[layout::kMaxLines][layout::kMaxCols + 1];
    void reset() {
      startMs = endMs = 0;
      count = 0;
      text[0][0] = text[1][0] = 0;
    }
  };

  uint8_t block_[192];
  size_t cursor_, count_;
  bool first_, eof_;
  bool haveCur_, haveNext_, started_;
  uint32_t lastStart_, seq_;
  Cue cur_, next_;
  Rect dirty_;

  // -------------------------------------------------------------------------
  //  Fluxo de bytes
  // -------------------------------------------------------------------------

  // Proximo byte, ou -1 no fim. Le em blocos para nao pagar uma chamada de
  // sistema por caractere.
  template <class Stream> int nextByte(Stream &file) {
    if (cursor_ == count_) {
      if (eof_)
        return -1;
      const size_t got = file.read(block_, sizeof(block_));
      // `got` grande demais cobre tambem um read() com sinal devolvendo -1.
      if (got == 0 || got > sizeof(block_)) {
        eof_ = true;
        return -1;
      }
      count_ = got;
      cursor_ = 0;
      if (first_) {
        first_ = false;
        // BOM UTF-8: so pode estar nos 3 primeiros bytes do arquivo, entao
        // sempre cai neste primeiro bloco.
        if (count_ >= 3 && block_[0] == 0xEF && block_[1] == 0xBB && block_[2] == 0xBF)
          cursor_ = 3;
        if (cursor_ == count_)
          return nextByte(file);
      }
    }
    return block_[cursor_++];
  }

  // Le uma linha sem o terminador. CRLF, LF e a ultima linha sem quebra valem.
  // Linha maior que `cap` e truncada mas CONSUMIDA ate o fim — e o que garante
  // que um arquivo binario passado por engano nao trave o parser.
  template <class Stream> bool readLine(Stream &file, char *dst, size_t cap) {
    size_t n = 0;
    for (;;) {
      const int c = nextByte(file);
      if (c < 0) {
        dst[n] = 0;
        return n > 0;
      }
      if (c == '\n')
        break;
      if (c == '\r')
        continue;
      if (n + 1 < cap)
        dst[n++] = (char)c;
    }
    dst[n] = 0;
    return true;
  }

  // -------------------------------------------------------------------------
  //  Numeros e tempos
  // -------------------------------------------------------------------------

  static bool isDigit(char c) { return c >= '0' && c <= '9'; }

  // Le digitos a partir de `i`. Devolve quantos leu (0 = nao era numero).
  static int readUInt(const char *s, size_t &i, uint32_t &out) {
    int digits = 0;
    out = 0;
    while (isDigit(s[i])) {
      if (out < 100000000UL) // trava boba contra estouro em lixo do tipo "999999999999"
        out = out * 10 + uint32_t(s[i] - '0');
      ++i;
      ++digits;
    }
    return digits;
  }

  // `HH:MM:SS,mmm` a partir de `i`. Aceita ponto no lugar da virgula (varios
  // conversores geram assim), horas com 1 a 3 digitos e fracao de 1 a 3 casas.
  static bool parseTime(const char *s, size_t &i, uint32_t &ms) {
    while (s[i] == ' ' || s[i] == '\t')
      ++i;
    uint32_t h = 0, m = 0, sec = 0, frac = 0;
    if (!readUInt(s, i, h) || s[i] != ':')
      return false;
    ++i;
    if (!readUInt(s, i, m) || s[i] != ':')
      return false;
    ++i;
    if (!readUInt(s, i, sec))
      return false;
    if (s[i] == ',' || s[i] == '.') {
      ++i;
      const size_t before = i;
      if (!readUInt(s, i, frac))
        return false;
      size_t digits = i - before;
      // Normaliza para milissegundos: "5" = 500 ms, "05" = 50 ms, "005" = 5 ms.
      while (digits < 3) {
        frac *= 10;
        ++digits;
      }
      while (digits > 3) {
        frac /= 10;
        --digits;
      }
    }
    if (h > 999 || m > 59 || sec > 59 || frac > 999)
      return false;
    ms = h * 3600000UL + m * 60000UL + sec * 1000UL + frac;
    return true;
  }

  // Posicao do "-->" na linha, ou -1.
  static int findArrow(const char *s) {
    for (int i = 0; s[i]; ++i)
      if (s[i] == '-' && s[i + 1] == '-' && s[i + 2] == '>')
        return i;
    return -1;
  }

  // Inicio do carimbo de tempo que termina antes da seta. Voltar a partir da
  // seta em vez de comecar da coluna 0 e o que faz "1 00:00:01,000 --> ..."
  // funcionar: ha conversor que gruda o numero de sequencia na mesma linha.
  static size_t timeStart(const char *s, int arrow) {
    size_t i = (size_t)arrow;
    while (i && (s[i - 1] == ' ' || s[i - 1] == '\t'))
      --i;
    while (i && (isDigit(s[i - 1]) || s[i - 1] == ':' || s[i - 1] == ',' || s[i - 1] == '.'))
      --i;
    return i;
  }

  // -------------------------------------------------------------------------
  //  Texto
  // -------------------------------------------------------------------------

  // Tira as etiquetas que o .srt carrega (<i>, </font>, {\an8}) e devolve o
  // texto cru. Roda ANTES da normalizacao: '<', '>', '{' e '}' sao ASCII e
  // nunca aparecem no meio de uma sequencia UTF-8, entao e seguro.
  static void stripTags(const char *src, char *dst, size_t cap) {
    size_t j = 0;
    char closing = 0;
    for (size_t i = 0; src[i] && j + 1 < cap; ++i) {
      const char c = src[i];
      if (closing) {
        if (c == closing)
          closing = 0;
        continue;
      }
      if (c == '<') {
        closing = '>';
        continue;
      }
      if (c == '{') {
        closing = '}';
        continue;
      }
      dst[j++] = c;
    }
    dst[j] = 0;
  }

  // Quebra `text` (ja em ASCII maiusculo, com '\n' separando as linhas do
  // arquivo) em no maximo kMaxLines linhas de kMaxCols colunas. Quebra na
  // ultima folga que couber; palavra maior que a linha e cortada na marra. O
  // que sobrar vira "..." no fim da ultima linha — o CC tambem cortava, mas
  // sem aviso, e aqui o aviso custa 3 caracteres e evita parecer bug.
  static uint8_t wrap(const char *text, char out[layout::kMaxLines][layout::kMaxCols + 1]) {
    uint8_t n = 0;
    size_t i = 0;
    while (n < layout::kMaxLines) {
      while (text[i] == ' ' || text[i] == '\n')
        ++i;
      if (!text[i])
        break;
      size_t take = 0, lastSpace = 0;
      bool haveSpace = false;
      size_t j = i;
      while (text[j] && text[j] != '\n' && take < (size_t)layout::kMaxCols) {
        if (text[j] == ' ') {
          lastSpace = take;
          haveSpace = true;
        }
        ++take;
        ++j;
      }
      // So vale quebrar na folga se a linha realmente continua depois dela.
      size_t adv = take;
      if (text[j] && text[j] != '\n' && haveSpace && lastSpace > 0)
        adv = lastSpace;
      size_t len = adv;
      memcpy(out[n], text + i, len);
      while (len && out[n][len - 1] == ' ')
        --len;
      out[n][len] = 0;
      i += adv;
      if (len)
        ++n;
      else if (adv == 0)
        break; // paranoia: sem avanco nao pode haver segunda volta
    }
    // Sobrou conteudo? Marca o corte na ultima linha.
    while (text[i] == ' ' || text[i] == '\n')
      ++i;
    if (text[i] && n > 0) {
      char *last = out[n - 1];
      size_t len = strlen(last);
      if (len + 3 <= (size_t)layout::kMaxCols) {
        last[len] = last[len + 1] = last[len + 2] = '.';
        last[len + 3] = 0;
      } else if (len >= 3) {
        last[len - 1] = last[len - 2] = last[len - 3] = '.';
      }
    }
    for (uint8_t k = n; k < layout::kMaxLines; ++k)
      out[k][0] = 0;
    return n;
  }

  // -------------------------------------------------------------------------
  //  Uma cue
  // -------------------------------------------------------------------------

  // Le a proxima cue VALIDA. Devolve false no EOF ou quando o orcamento de
  // linhas varridas acabou (nesse caso a proxima chamada continua de onde
  // parou — o fluxo so anda para a frente, entao nao ha laco infinito).
  //
  // Tolerancias, todas exercitadas pelo sim/probes/subtitles.cpp: numero de
  // sequencia ausente, errado ou substituido por lixo; linhas em branco de
  // sobra; CRLF; BOM. Cue com fim <= inicio, com tempo impossivel ou fora de
  // ordem e DESCARTADA — sem legenda e melhor que legenda errada.
  template <class Stream> bool parseCue(Stream &file, Cue &out) {
    char line[kLineCap];
    for (int scanned = 0; scanned < kScanPerUpdate; ++scanned) {
      if (!readLine(file, line, sizeof(line))) {
        eof_ = true;
        return false;
      }
      const int arrow = findArrow(line);
      if (arrow < 0)
        continue; // numero de sequencia, linha em branco ou lixo: ignora
      size_t p = timeStart(line, arrow);
      uint32_t startMs = 0, endMs = 0;
      if (!parseTime(line, p, startMs))
        continue;
      p = (size_t)arrow + 3;
      if (!parseTime(line, p, endMs))
        continue;

      // Texto: ate a linha em branco ou o fim do arquivo. Limitado a kTextLines
      // para que uma cue absurda nao leia o arquivo inteiro numa chamada so; o
      // excedente cai na varredura seguinte e e ignorado por nao ter seta.
      char raw[kTextCap], tmp[kLineCap];
      size_t used = 0;
      raw[0] = 0;
      bool more = true;
      for (int t = 0; more && t < kTextLines; ++t) {
        more = readLine(file, line, sizeof(line));
        if (!more) {
          eof_ = true;
          break;
        }
        // Linha em branco fecha a cue. Tambem fecha se ja apareceu outra seta,
        // caso o arquivo tenha esquecido a separacao (acontece).
        if (!line[0])
          break;
        if (used && findArrow(line) >= 0)
          break;
        stripTags(line, tmp, sizeof(tmp));
        if (used + 1 < sizeof(raw) && used)
          raw[used++] = '\n';
        // normalizeUpper termina em \0 e devolve o que escreveu: da para
        // emendar as linhas da cue sem buffer intermediario.
        used += ::ascii::normalizeUpper(raw + used, sizeof(raw) - used, tmp);
      }

      // Validacao. Ordem crescente exigida porque o leitor nao volta: uma cue
      // que comeca antes da anterior nunca poderia ser exibida mesmo.
      if (endMs <= startMs)
        continue;
      if (started_ && startMs < lastStart_)
        continue;
      out.startMs = startMs;
      out.endMs = endMs;
      out.count = wrap(raw, out.text);
      if (!out.count)
        continue; // cue sem texto util (so etiquetas, ou so acento sem ASCII)
      lastStart_ = startMs;
      started_ = true;
      return true;
    }
    return false;
  }
};

// O orcamento de SRAM em constante, para nao virar comentario desatualizado.
static_assert(sizeof(Subtitles) <= 1024, "Subtitles estourou 1 KB de SRAM");

} // namespace subs

#pragma once
// ============================================================================
// TestPattern.h — carta de ajuste SMPTE, tom de referencia de 1 kHz e as telas
// de "sem sinal" / fim de transmissao.
//
// Serve a duas coisas que nenhuma outra tela deste firmware faz:
//
//   1. CALIBRAR O TUBO. As barras SMPTE sao a unica tela do aparelho que usa o
//      quadro INTEIRO de 320x240, de proposito. Todas as outras respeitam a
//      area segura (SafeArea.h) porque um tubo esconde ~7% de cada borda; aqui
//      o objetivo e justamente MEDIR quanto ele esconde. Quem olha a TV ve onde
//      as barras somem e descobre o overscan do aparelho dele. O unico elemento
//      que continua dentro da caixa segura e o TEXTO: um rotulo que a TV corta
//      nao informa nada.
//   2. ENCERRAR A TRANSMISSAO. Barras + tom de 1 kHz e o par classico de
//      sign-off; e o "sem sinal" (chuvisco ou cartaz) e o que a tela mostra
//      quando nao ha cartao SD.
//
// ---------------------------------------------------------------------------
// O que este arquivo assume sobre o codificador NTSC (medido, nao chutado)
// ---------------------------------------------------------------------------
// Os niveis abaixo saem da tabela NTSC do M5GFX 0.2.29
// (lgfx/v1/platforms/esp32/Panel_CVBS.cpp, struct signal_spec_t):
//
//     blanking = 286 mV  -> 0 IRE
//     black    = 340 mV  -> 7,5 IRE   (setup americano, o mesmo do NTSC-M)
//     white    = 960 mV  -> 94,4 IRE  (abaixo de 100 IRE de PROPOSITO: assim o
//                                      pico de croma do amarelo cai perto de
//                                      100 IRE em vez de estourar)
//
// Consequencias que mudam o desenho:
//
//   * **0x0000 NAO e o nivel de apagamento (blanking).** O codificador ja
//     insere o pedestal de 7,5 IRE, entao o preto do framebuffer sai no nivel
//     de PRETO correto do NTSC. Isso e bom (nao precisamos compensar nada) e
//     tem um preco: **nao existe "mais preto que preto"**. A barra de -4 IRE
//     do PLUGE e impossivel de gerar a partir de pixel; ela e desenhada
//     identica ao preto de referencia e o comentario do PLUGE explica como
//     calibrar mesmo assim.
//   * A escala util e 86,8 IRE para 256 codigos -> **0,3405 IRE por codigo**.
//   * Como o branco esta em 94,4 IRE e nao em 100, uma barra de 75% medida num
//     osciloscopio da ~71,9 IRE em vez dos 76,9 IRE do papel. Nao e erro de
//     conta nossa: e o ganho escolhido pelo M5GFX, e o controle de contraste da
//     TV absorve a diferenca. As PROPORCOES entre as barras, que e o que a
//     carta mede, continuam certas.
//   * O caminho RGB565 -> RGB888 do codificador e `(v5 * 0x21) >> 2` e
//     `(v6 * 0x41) >> 4`, ou seja replicacao de bits. Cada constante de cor
//     abaixo traz, no comentario, o RGB888 que o codificador realmente vai ver.
//
// ---------------------------------------------------------------------------
// Restricoes do projeto respeitadas aqui (ver AGENTS.md)
// ---------------------------------------------------------------------------
//   * **C++11** (`-std=gnu++11`): todo `constexpr` daqui e um unico `return`,
//     sem laco e sem variavel local. Conferir com `make -C sim cxx11`.
//   * **Nada de sprite nem de framebuffer proprio.** O desenho e so `fillRect`;
//     a SRAM e o recurso escasso (heap livre medido: 28-38 KB).
//   * A tabela do tom de 1 kHz tem 882 bytes e vive num `static const` dentro
//     de funcao, ou seja **em flash (.rodata), nao em SRAM**. O estado do
//     gerador sao 4 bytes.
//   * **Este header NAO toca no I2S.** I2S0 e do video composto e o I2S1 tem
//     dono (o `audioTask` do main.cpp). Aqui so se PRODUZ PCM; quem escreve e
//     o dono do barramento.
//   * Texto ASCII, sem acento: as fontes bitmap so tem ASCII.
//
// Dependencias: M5GFX (vem pela VcrFont.h), SafeArea.h e Ascii.h. Nada de
// Arduino, FreeRTOS, SD ou I2S — o destino e um `lgfx::LovyanGFX*`, entao o
// mesmo header serve ao painel CVBS do aparelho e ao painel SDL do simulador.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "VcrFont.h" // traz <M5GFX.h> e a fonte grossa 12x16 do cartaz

#include <stddef.h>
#include <stdint.h>

namespace testpattern {

// ===========================================================================
//  1. Cores
// ===========================================================================

// RGB888 -> RGB565 por truncamento, que e exatamente o que o M5GFX faz em
// color565(). Um unico `return`, para continuar valendo em C++11.
constexpr uint16_t rgb565(int r, int g, int b) {
  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | ((b & 0xF8) >> 3));
}

// Niveis de referencia da carta, em codigo de 8 bits.
constexpr int L75 = 191;  // 0,75 * 255 = 191,25 -> 191
constexpr int L100 = 255; // branco de referencia

// --- as sete barras de 75% -------------------------------------------------
// Valor 565 e, entre parenteses, o RGB888 que o codificador reconstroi.
// ATENCAO ao passar qualquer uma destas para o LovyanGFX: o tipo do argumento
// e que decide como a cor e lida. Em misc/colortype.hpp:861-866, uint8_t vira
// RGB332, uint16_t/int16_t/int32_t viram RGB565 e **uint32_t vira RGB888**.
// Um (uint32_t)GRAY75 faz 0xBDF7 ser lido como 0x00BDF7, ou seja R=0, G=189,
// B=247, e a barra cinza sai esverdeada. Era esse o defeito aqui. Passe
// uint16_t, ou lgfx::rgb565_t, nunca uint32_t.
constexpr uint16_t GRAY75 = rgb565(L75, L75, L75);  // 0xBDF7  (189,190,189)
constexpr uint16_t YELLOW75 = rgb565(L75, L75, 0);  // 0xBDE0  (189,190,  0)
constexpr uint16_t CYAN75 = rgb565(0, L75, L75);    // 0x05F7  (  0,190,189)
constexpr uint16_t GREEN75 = rgb565(0, L75, 0);     // 0x05E0  (  0,190,  0)
constexpr uint16_t MAGENTA75 = rgb565(L75, 0, L75); // 0xB817  (189,  0,189)
constexpr uint16_t RED75 = rgb565(L75, 0, 0);       // 0xB800  (189,  0,  0)
constexpr uint16_t BLUE75 = rgb565(0, 0, L75);      // 0x0017  (  0,  0,189)

// --- linha de baixo --------------------------------------------------------
constexpr uint16_t WHITE100 = rgb565(L100, L100, L100); // 0xFFFF  (255,255,255)
constexpr uint16_t BLACK = 0x0000;                      // 7,5 IRE: ver cabecalho

// -I e +Q sao os eixos de croma do NTSC. Os equivalentes RGB usuais da carta
// (croma em amplitude cheia, luma baixa) sao #00214C e #32006A.
constexpr uint16_t MINUS_I = rgb565(0, 33, 76);  // 0x0109  (  0, 32, 72)
constexpr uint16_t PLUS_Q = rgb565(50, 0, 106);  // 0x300D  ( 49,  0,107)

// PLUGE (Picture Line-Up Generating Equipment) — ajuste de brilho.
//
// O papel pede tres barras: -4 / 0 / +4 IRE em torno do preto. Aqui:
//
//   PLUGE_MINUS  impossivel. O pedestal de 7,5 IRE ja esta no codificador e o
//                codigo 0 e o piso; nao da para descer abaixo do preto a partir
//                de pixel. Fica identica ao preto de referencia, DE PROPOSITO.
//   BLACK        preto de referencia, codigo 0 = 7,5 IRE.
//   PLUGE_PLUS   codigo 8 = +2,72 IRE. Em RGB565 os cinzas neutros andam de 8
//                em 8 codigos (R5/B5 tem passo 8), entao +4 IRE (codigo ~12)
//                simplesmente nao existe nesta profundidade: 8 e o degrau
//                imediatamente acima do preto.
//
// Como calibrar com o que da para gerar: abaixe o BRILHO ate as tres barras
// virarem um bloco preto so; suba ate a TERCEIRA (a da direita) aparecer por
// pouco. Nesse ponto as duas primeiras ainda estao fundidas com o fundo — que e
// o mesmo criterio do PLUGE original, so que lido da direita para a esquerda.
constexpr uint16_t PLUGE_MINUS = BLACK;               // recortado no piso
constexpr uint16_t PLUGE_PLUS = rgb565(8, 8, 8);      // 0x0841  (8,8,8)  +2,72 IRE
constexpr uint16_t PLUGE_PLUS_HI = rgb565(16, 16, 16);// 0x1082  (16,16,16) +5,45 IRE
                                                      // degrau alternativo, para
                                                      // tubo muito surrado

// ===========================================================================
//  2. Geometria da carta (SMPTE ECR 1-1978, campo dividido)
// ===========================================================================
//
//   topo   67%  ->  161 px   sete barras de 75%
//   meio    8%  ->   19 px   barras azuis invertidas (castellation)
//   base   25%  ->   60 px   -I / branco 100% / +Q / preto / PLUGE / preto
//
// 240 * 0,67 = 160,8 ; 240 * 0,08 = 19,2 ; 240 * 0,25 = 60. Arredondado para
// 161 + 19 + 60 = 240 exatos, sem linha sobrando.
constexpr int BARS_Y = 0;
constexpr int BARS_H = 161;
constexpr int MID_Y = BARS_Y + BARS_H;  // 161
constexpr int MID_H = 19;
constexpr int BOT_Y = MID_Y + MID_H;    // 180
constexpr int BOT_H = crt::H - BOT_Y;   // 60

// Borda esquerda da barra `i` (0..7). 320/7 = 45,71, entao as barras saem com
// 45 ou 46 px — a diferenca de 1 px some no borrao horizontal do NTSC, e o
// importante (somar 320 exatos, sem coluna orfa na direita) fica garantido.
//   0, 45, 91, 137, 182, 228, 274, 320
constexpr int barX(int i) { return (i * crt::W) / 7; }

static_assert(BARS_H + MID_H + BOT_H == crt::H, "as tres faixas precisam somar 240");
static_assert(barX(0) == 0 && barX(7) == crt::W, "as barras precisam cobrir 0..320");

// O rotulo cai no bloco preto da linha de baixo, entre as barras 3 e 5. Esse
// retangulo e [137,228) x [180,240), e as duas linhas de texto ficam em
// [194,214) — dentro de crt::SAFE_* nos dois eixos, que e a regra para texto.
constexpr int LABEL_X = barX(3);
constexpr int LABEL_W = barX(5) - barX(3); // 91 px
constexpr int LABEL_Y1 = BOT_Y + 14;       // 194
constexpr int LABEL_Y2 = BOT_Y + 26;       // 206

static_assert(LABEL_X >= crt::SAFE_L && LABEL_X + LABEL_W <= crt::SAFE_R,
              "rotulo fora da area segura no eixo X");
static_assert(LABEL_Y1 >= crt::SAFE_T && LABEL_Y2 + 8 <= crt::SAFE_B,
              "rotulo fora da area segura no eixo Y");

// ===========================================================================
//  3. Desenho
// ===========================================================================

namespace detail {

inline void seg(lgfx::LovyanGFX *dst, int ox, int oy, int x0, int x1, int y, int h, uint16_t color) {
  dst->fillRect(ox + x0, oy + y, x1 - x0, h, (uint16_t)color);
}

// Normaliza texto de fora para ASCII antes de desenhar (armadilha 9 do
// AGENTS.md: acento em UTF-8 sao dois bytes sem glifo, viram dois buracos).
inline const char *norm(char *dst, size_t cap, const char *src) {
  if (!cap)
    return "";
  if (!src) {
    dst[0] = 0;
    return dst;
  }
  ascii::normalizeUpper(dst, cap, src);
  return dst;
}

} // namespace detail

// Barras SMPTE no quadro inteiro, com rotulo de emissora.
//
// `l1` / `l2` podem ser nulos (carta limpa, sem texto). Passam por
// ascii::normalizeUpper, entao aceitam texto vindo de fora.
inline void drawBarsLabeled(lgfx::LovyanGFX *dst, int ox, int oy, const char *l1, const char *l2) {
  if (!dst)
    return;

  // Em flash, nao em SRAM: 14 bytes cada.
  static const uint16_t kTop[7] = {GRAY75, YELLOW75, CYAN75, GREEN75, MAGENTA75, RED75, BLUE75};
  // Faixa do meio: as barras azuis invertidas. A ordem existe para que, com o
  // croma da TV desligado (ou so o canal azul ligado), as colunas fiquem com
  // luminancia igual e as bordas sumam — e assim que se ajusta cor/matiz.
  static const uint16_t kMid[7] = {BLUE75, BLACK, MAGENTA75, BLACK, CYAN75, BLACK, GRAY75};

  dst->startWrite();

  for (int i = 0; i < 7; ++i) {
    detail::seg(dst, ox, oy, barX(i), barX(i + 1), BARS_Y, BARS_H, kTop[i]);
    detail::seg(dst, ox, oy, barX(i), barX(i + 1), MID_Y, MID_H, kMid[i]);
  }

  // Linha de baixo. Larguras em unidades de barra: -I 1, branco 1, +Q 1,
  // preto 2, PLUGE 1, preto 1 = 7.
  detail::seg(dst, ox, oy, barX(0), barX(1), BOT_Y, BOT_H, MINUS_I);
  detail::seg(dst, ox, oy, barX(1), barX(2), BOT_Y, BOT_H, WHITE100);
  detail::seg(dst, ox, oy, barX(2), barX(3), BOT_Y, BOT_H, PLUS_Q);
  detail::seg(dst, ox, oy, barX(3), barX(5), BOT_Y, BOT_H, BLACK);

  const int p0 = barX(5), p3 = barX(6);
  const int p1 = p0 + (p3 - p0) / 3, p2 = p0 + ((p3 - p0) * 2) / 3;
  detail::seg(dst, ox, oy, p0, p1, BOT_Y, BOT_H, PLUGE_MINUS);
  detail::seg(dst, ox, oy, p1, p2, BOT_Y, BOT_H, BLACK);
  detail::seg(dst, ox, oy, p2, p3, BOT_Y, BOT_H, PLUGE_PLUS);

  detail::seg(dst, ox, oy, barX(6), barX(7), BOT_Y, BOT_H, BLACK);

  if (l1 || l2) {
    // Font0 tamanho 1 (6x8) de proposito: o rotulo e assinatura, nao conteudo.
    // Grande demais ele roubaria area preta que o PLUGE precisa ter ao lado.
    char b1[16], b2[16];
    dst->setFont(&fonts::Font0);
    dst->setTextSize(1);
    dst->setTextDatum(lgfx::textdatum::top_center);
    dst->setTextColor((uint16_t)GRAY75); // fore == back no LovyanGFX = fundo transparente
    const int cx = ox + LABEL_X + LABEL_W / 2;
    if (l1)
      dst->drawString(detail::norm(b1, sizeof(b1), l1), cx, oy + LABEL_Y1);
    if (l2)
      dst->drawString(detail::norm(b2, sizeof(b2), l2), cx, oy + LABEL_Y2);
    dst->setTextDatum(lgfx::textdatum::top_left);
  }

  dst->endWrite();
}

// Ponto de entrada padrao: mesma assinatura dos outros pintores do projeto,
// entao serve ao painel CVBS e ao LCD sem adaptacao.
inline void drawBars(lgfx::LovyanGFX *dst, int ox, int oy) {
  drawBarsLabeled(dst, ox, oy, "M5 RETRO TV", "SMPTE 75% 1KHZ");
}

// ---------------------------------------------------------------------------
//  Chuvisco ("snow") — o "sem sinal" classico
// ---------------------------------------------------------------------------
//
// Por celula de 8x8, nao por pixel: 40x30 = 1200 fillRect por quadro, contra
// 76.800 escritas de um laco pixel a pixel. O ruido de um tubo sem sinal e
// grosso mesmo, entao a celula nao custa realismo.
//
// O estado e do objeto, nao um `static` escondido (armadilha 6 do AGENTS.md:
// tela que herda o estado da visita anterior). Quem entra na tela chama
// reset().
class Snow {
public:
  static constexpr int CELL = 8;

  constexpr explicit Snow(uint32_t seed = 0x2545F491u) : s_(seed | 1u) {}

  void reset(uint32_t seed = 0x2545F491u) { s_ = seed | 1u; }

  // Um quadro de chuvisco no quadro inteiro. Chame de novo para o proximo.
  void draw(lgfx::LovyanGFX *dst, int ox, int oy, int cell = CELL) {
    if (!dst || cell < 1)
      return;
    dst->startWrite();
    for (int y = 0; y < crt::H; y += cell) {
      const int h = (y + cell > crt::H) ? crt::H - y : cell;
      for (int x = 0; x < crt::W; x += cell) {
        const int w = (x + cell > crt::W) ? crt::W - x : cell;
        const int v = (int)(next() >> 24); // byte alto: o de melhor distribuicao
        dst->fillRect(ox + x, oy + y, w, h, (uint16_t)rgb565(v, v, v));
      }
    }
    dst->endWrite();
  }

private:
  // xorshift32: 3 shifts e 3 XORs por celula. Um rand() da libc aqui custaria
  // chamada de funcao e estado global compartilhado com o resto do firmware.
  uint32_t next() {
    s_ ^= s_ << 13;
    s_ ^= s_ >> 17;
    s_ ^= s_ << 5;
    return s_;
  }
  uint32_t s_;
};

// Instancia de conveniencia para quem so quer um pintor (dst, ox, oy).
// Constante-inicializada (construtor constexpr), entao nao gera guard variable
// nem inicializacao em tempo de boot.
inline Snow &sharedSnow() {
  static Snow s;
  return s;
}

inline void drawSnow(lgfx::LovyanGFX *dst, int ox, int oy) {
  sharedSnow().draw(dst, ox, oy);
}

// ---------------------------------------------------------------------------
//  Cartaz (slate) — "NO SIGNAL" / fim de transmissao
// ---------------------------------------------------------------------------
//
// Barato: fundo preto, moldura e duas linhas de texto. Nada de por a data ou a
// hora aqui — isso obrigaria a repintar o quadro inteiro a cada segundo.
//
// `boxOnly` desenha so a caixa, sem apagar o fundo: e assim que o cartaz entra
// por cima do chuvisco em drawNoSignal().
inline void drawSlateText(lgfx::LovyanGFX *dst, int ox, int oy, const char *title, const char *sub,
                          bool boxOnly = false) {
  if (!dst)
    return;

  // Caixa centralizada e inteiramente dentro da area segura.
  const int bx = crt::SAFE_L;
  const int bw = crt::SAFE_W;
  const int bh = sub ? 84 : 56;
  const int by = (crt::H - bh) / 2;

  char t[24], s[32];
  const char *tt = detail::norm(t, sizeof(t), title ? title : "NO SIGNAL");
  const char *ss = sub ? detail::norm(s, sizeof(s), sub) : (const char *)0;

  dst->startWrite();
  if (!boxOnly)
    dst->fillRect(ox, oy, crt::W, crt::H, (uint16_t)BLACK);
  dst->fillRect(ox + bx, oy + by, bw, bh, (uint16_t)BLACK);
  dst->drawRect(ox + bx, oy + by, bw, bh, (uint16_t)GRAY75);
  dst->drawRect(ox + bx + 1, oy + by + 1, bw - 2, bh - 2, (uint16_t)GRAY75);

  // VcrFont escala 2 = celula 24x32, traco de 4 px: e a unica fonte do projeto
  // que aguenta o borrao horizontal do NTSC em tamanho grande.
  vcrfont::drawTextCentered(dst, tt, ox + bx, oy + by + 12, bw, (int32_t)WHITE100, 2);
  if (ss)
    vcrfont::drawTextCentered(dst, ss, ox + bx, oy + by + 52, bw, (int32_t)GRAY75, 1);
  dst->endWrite();
}

// Pintor (dst, ox, oy) do cartaz limpo.
inline void drawSlate(lgfx::LovyanGFX *dst, int ox, int oy) {
  drawSlateText(dst, ox, oy, "NO SIGNAL", (const char *)0);
}

// Chuvisco com o cartaz por cima — o "sem sinal" completo.
inline void drawNoSignal(lgfx::LovyanGFX *dst, int ox, int oy) {
  drawSnow(dst, ox, oy);
  drawSlateText(dst, ox, oy, "NO SIGNAL", (const char *)0, true);
}

// Adaptadores para o ScreenFx::Paint, que e (dst, ox, oy, void *user).
inline void paintBars(lgfx::LovyanGFX *dst, int ox, int oy, void *) { drawBars(dst, ox, oy); }
inline void paintSnow(lgfx::LovyanGFX *dst, int ox, int oy, void *) { drawSnow(dst, ox, oy); }
inline void paintSlate(lgfx::LovyanGFX *dst, int ox, int oy, void *) { drawSlate(dst, ox, oy); }

// ===========================================================================
//  4. Tom de referencia de 1 kHz
// ===========================================================================
//
// O outro metade do par "bars and tone". Este header NAO instala, NAO
// configura e NAO escreve no I2S: I2S0 e do video composto e o I2S1 tem dono
// (o audioTask do main.cpp). Aqui so se produz PCM.
//
// Por que 441 amostras:
//
//   1 kHz a 22050 Hz da 22,05 amostras por ciclo — nao fecha em inteiro, e uma
//   tabela de um ciclo so emendaria com salto de fase a cada volta (clique
//   audivel, e um espalhamento de espectro que estraga a medida). A saida e
//   fechar em VARIOS ciclos:
//
//       441 amostras = 20 ciclos exatos
//       f = 22050 * 20 / 441 = 1000,000000 Hz   (exato, nao aproximado)
//
//   441 = 3^2 * 7^2 e 22050 = 50 * 441, entao a divisao e exata por
//   construcao. Como mdc(20, 441) = 1, as 441 amostras sao uma permutacao de
//   sin(2*pi*k/441): a tabela usa a resolucao de fase inteira, sem repeticao.
//
//   Custo: 441 * 2 = **882 bytes**, e em FLASH (.rodata), porque e um
//   `static const` com inicializador constante dentro de funcao inline. A SRAM
//   gasta sao os 4 bytes de estado do gerador. Uma tabela de 1 segundo estereo
//   seria 88.200 bytes — mais do que o heap livre inteiro do aparelho (28-38
//   KB), que e exatamente o erro que esta conta evita.
//
//   Conferido: soma das 441 amostras = 0 exato (sem offset DC) e pico
//   +32767/-32767 (sem estouro). O gerador atenua, nunca amplifica, entao nao
//   ha como cortar.
// ---------------------------------------------------------------------------

constexpr uint32_t SAMPLE_RATE = 22050; // igual ao `sampleRate` do main.cpp
constexpr uint32_t TONE_HZ = 1000;      // exato, nao aproximado
constexpr int TONE_TABLE_LEN = 441;     // 20 ciclos
constexpr int TONE_TABLE_BYTES = TONE_TABLE_LEN * 2; // 882

// Amplitudes em Q8 (256 = escala cheia). O padrao de sala de controle para
// "bars and tone" e -20 dBFS: audivel, com folga de sobra no caminho analogico.
constexpr uint8_t AMP_MINUS20DB = 26;  // 26/256 = 0,1016 -> -19,86 dBFS
constexpr uint8_t AMP_MINUS12DB = 64;  // 64/256 = 0,2500 -> -12,04 dBFS
constexpr uint8_t AMP_MINUS6DB = 128;  // 128/256 = 0,500 ->  -6,02 dBFS
constexpr uint8_t AMP_FULL = 255;      // 255/256 -> -0,03 dBFS (ainda sem cortar)

